void main() async {
  
  WidgetsFlutterBinding.ensureInitialized();


  // Release rejimda (APK va Web production) brauzer/terminal konsolini 100% toza saqlash
  if (!kDebugMode) {
    debugPrint = (String? message, {int? wrapWidth}) {};
  }

  // 1. Production Global Crash & Error Boundary Handlers with deduplication
  DateTime? lastErrorTime;
  String? lastErrorMessage;

  FlutterError.onError = (FlutterErrorDetails details) {
    final msg = details.exceptionAsString();
    final now = DateTime.now();
    if (lastErrorMessage == msg && lastErrorTime != null && now.difference(lastErrorTime!).inMilliseconds < 1000) {
      return; // Deduplicate repeating errors within 1 second
    }
    lastErrorMessage = msg;
    lastErrorTime = now;
    if (kDebugMode) {
      FlutterError.presentError(details);
      debugPrint('🛡️ [Global FlutterError] $msg');
    }
  };

  WidgetsBinding.instance.platformDispatcher.onError = (error, stack) {
    if (kDebugMode) {
      debugPrint('🛡️ [Global Platform Error] $error');
    }
    return true; // Handled, prevent app crash
  };

  ErrorWidget.builder = (FlutterErrorDetails details) {
    return const Material(
      color: Color(0xFF0F172A),
      child: Center(
        child: Padding(
          padding: EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(Icons.info_outline, color: Colors.amber, size: 48),
              SizedBox(height: 16),
              Text(
                'Kechirasiz, kutilmagan xatolik yuz berdi.',
                textAlign: TextAlign.center,
                style: TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.bold),
              ),
              SizedBox(height: 8),
              Text(
                'Ma\'lumotlaringiz xavfsiz saqlangan. Iltimos, sahifani yangilang.',
                textAlign: TextAlign.center,
                style: TextStyle(color: Colors.white70, fontSize: 13),
              ),
            ],
          ),
        ),
      ),
    );
  };

  try {
    await TokenStorage().init();
    await LocalizationService().init();
    await LocalCacheService().init();
    await OfflineSyncService().init();
    await ApiClient().init();
    await SupabaseRealtimeService().init();
    final token = ApiClient().token;
    if (token != null && token.isNotEmpty) {
      final cachedUser = await ApiClient().readCachedUserJson();
      final cafeId = cachedUser?['cafeId'] as String?;
      if (cafeId != null && cafeId.isNotEmpty && cafeId != 'local_default') {
        SocketService().connect(token: token, cafeId: cafeId);
        SupabaseRealtimeService().subscribeToCafe(cafeId);
      }
    }
  } catch (e) {
    debugPrint('ApiClient/SocketService/SupabaseRealtime initialize error: $e');
  }
  // Butun ilova global "appState" obyektidan foydalanadi (pastda e'lon
  // qilingan). Birinchi kadr chizilishidan oldin saqlangan ma'lumotlar
  // to'liq yuklanishini ta'minlaymiz.
  await appState.loadData();

  runApp(const ZaveroApp());
}

