  void _startPrinterStationHeartbeat() {
    _printerStationHeartbeatTimer?.cancel();
    if (!isPrinterStation || currentCafeId.isEmpty) return;
    _printerStationHeartbeatTimer = Timer.periodic(const Duration(seconds: 4), (_) {
      if (isPrinterStation && currentCafeId.isNotEmpty) {
        SocketService().emitPrinterStationHeartbeat(
          currentCafeId,
          stationName: effectiveReceiptName.isNotEmpty ? effectiveReceiptName : 'Kassa stansiyasi',
          isPrinterReady: isPrinterVerified,
        );
      }
    });
  }

  Future<void> setPrinterStation(bool val) async {
    isPrinterStation = val;
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool('is_printer_station', val);
    if (currentCafeId.isNotEmpty) {
      if (val) {
        SocketService().registerPrinterStation(
          currentCafeId,
          stationName: effectiveReceiptName.isNotEmpty ? effectiveReceiptName : 'Kassa stansiyasi',
          isPrinterReady: isPrinterVerified,
        );
        _startPrinterStationHeartbeat();
        unawaited(_processPendingPrintJobs());
      } else {
        _printerStationHeartbeatTimer?.cancel();
        _printerStationHeartbeatTimer = null;
        SocketService().unregisterPrinterStation(currentCafeId);
      }
    }
    notifyListeners();
  }

  Future<void> checkCloudPrinterStationStatus() async {
    if (isPrinterStation) return;
    if (!ApiClient().isAuthenticated) return;
    final cafeId = currentCafeId.isNotEmpty ? currentCafeId : (currentUser?.cafeId ?? '');
    if (cafeId.isEmpty || cafeId == 'local_default') return;
    try {
      final res = await CloudPrintService().getPrinterStationStatus(cafeId);
      hasCloudPrinterStation = res['hasStation'] == true;
      cloudPrinterStationName = res['stationName']?.toString();
      isCloudStationPrinterReady = res['isPrinterReady'] == true;
      notifyListeners();
    } catch (_) {}
  }

  /// Server ma'lumotlari + hali yuborilmagan lokal offline buyurtmalarni birlashtirgan jonli hisobot
  TodayReportSummary? get effectiveTodayReport {
    final base = liveTodayReport;
    final pending = OfflineSyncService().getPendingReceiptsForCafe(currentCafeId);
    if (pending.isEmpty) return base;

    int extraRev = 0;
    int extraOrders = 0;
    int extraCash = 0;
    int extraCard = 0;
    for (final r in pending) {
      extraRev += r.total.round();
      extraOrders++;
      if (r.method == PaymentMethod.cash) {
        extraCash += r.total.round();
      } else if (r.method == PaymentMethod.card) {
        extraCard += r.total.round();
      } else {
        extraCash += r.cashPaid.round();
        extraCard += r.cardPaid.round();
      }
    }

    final baseRev = base?.totalRevenue ?? 0;
    final baseOrders = base?.orderCount ?? 0;
    final baseCash = base?.cashTotal ?? 0;
    final baseCard = base?.cardTotal ?? 0;
    final totalRev = baseRev + extraRev;
    final totalOrders = baseOrders + extraOrders;
    final avg = totalOrders > 0 ? (totalRev / totalOrders).round() : 0;

    // Top mahsulotlarni pending kvitansiyalar bilan birlashtiramiz (Donut va hisobot nomutanosibligini yo'qotadi)
    final productMap = <String, ({int qty, int rev})>{};
    for (final p in (base?.topProducts ?? const <TodayProductMetric>[])) {
      productMap[p.name] = (qty: p.quantity, rev: p.totalRevenue);
    }
    for (final r in pending) {
      for (final item in r.items) {
        final name = item.product.name.trim();
        if (name.isEmpty) continue;
        final current = productMap[name] ?? (qty: 0, rev: 0);
        productMap[name] = (
          qty: current.qty + item.qty,
          rev: current.rev + (item.product.price * item.qty).round(),
        );
      }
    }
    final mergedTopProducts = productMap.entries.map((e) => TodayProductMetric(
      name: e.key,
      quantity: e.value.qty,
      totalRevenue: e.value.rev,
    )).toList()..sort((a, b) => b.quantity.compareTo(a.quantity));

    // Ofitsiantlar statistikasini pending kvitansiyalar bilan birlashtiramiz
    final waiterMap = <String, ({int count, int rev})>{};
    for (final w in (base?.waiters ?? const <TodayWaiterMetric>[])) {
      waiterMap[w.name] = (count: w.orderCount, rev: w.totalRevenue);
    }
    for (final r in pending) {
      final name = r.cashierName.trim().isNotEmpty ? r.cashierName.trim() : 'Kassa';
      final current = waiterMap[name] ?? (count: 0, rev: 0);
      waiterMap[name] = (
        count: current.count + 1,
        rev: current.rev + r.total.round(),
      );
    }
    final mergedWaiters = waiterMap.entries.map((e) => TodayWaiterMetric(
      name: e.key,
      orderCount: e.value.count,
      totalRevenue: e.value.rev,
    )).toList()..sort((a, b) => b.totalRevenue.compareTo(a.totalRevenue));

    return TodayReportSummary(
      totalRevenue: totalRev,
      orderCount: totalOrders,
      cashTotal: baseCash + extraCash,
      cardTotal: baseCard + extraCard,
      averageCheck: avg,
      waiters: mergedWaiters,
      topProducts: mergedTopProducts,
      updatedAt: DateTime.now(),
    );
  }

  /// Barcha hisobotlarni 0 dan tozalash (cheklar arxivda saqlanadi, barcha qurilmalarda real-time 0 bo'ladi)
  Future<bool> clearAllReports() async {
    final cafeId = currentCafeId.isNotEmpty ? currentCafeId : (currentUser?.cafeId ?? '');
    if (cafeId.isEmpty) return false;
    final ok = await _cloudService.clearAllReports(cafeId);
    if (ok) {
      reportsResetAt = DateTime.now();
      dailyReports.clear();
      liveTodayReport = TodayReportSummary(
        totalRevenue: 0,
        orderCount: 0,
        cashTotal: 0,
        cardTotal: 0,
        averageCheck: 0,
        waiters: const [],
        topProducts: const [],
        updatedAt: DateTime.now(),
      );
      await saveData();
      notifyListeners();
    }
    return ok;
  }

  /// Tanlangan kun hisoboti va cheklarini tozalash
  Future<bool> clearDayReport(String dateId) async {
    final cafeId = currentCafeId.isNotEmpty ? currentCafeId : (currentUser?.cafeId ?? '');
    if (cafeId.isEmpty) return false;
    final ok = await _cloudService.clearDayReport(cafeId, dateId);
    if (ok) {
      dailyReports.removeWhere((r) => r.dateId == dateId);
      receipts.removeWhere((r) => r.date.toIso8601String().substring(0, 10) == dateId);
      await saveData();
      notifyListeners();
    }
    return ok;
  }

