  String? _activeLoadedCafeId;

  /// Bulutdan joriy cafe ma'lumotlarini yuklash va real-time obuna bo'lish
  Future<void> loadCloudDataForCafe(String cafeId) async {
    if (cafeId.isEmpty || cafeId == 'local_default' || !ApiClient().isAuthenticated) {
      if (categories.isEmpty && products.isEmpty) {
        await _loadFromLocalCache();
      }
      return;
    }

    final isSwitchingCafe = _activeLoadedCafeId != null && _activeLoadedCafeId != cafeId;
    _activeLoadedCafeId = cafeId;

    if (isSwitchingCafe || cafeId != 'local_default') {
      // Yangi kafe yoki kafe almashganda to'liq tozalash
      categories.clear();
      products.clear();
      halls.clear();
      tables.clear();
      customers.clear();
      receipts.clear();
      customerOrders.clear();
      tableOrders.clear();
      tableNotes.clear();
      selectedHall = null;
      selectedTable = null;
      await _loadFromLocalCache();
    } else if (categories.isEmpty && products.isEmpty) {
      // Birinchi marta kirganda lokal keshdan tezkor yuklash
      await _loadFromLocalCache();
    }

    try {
      try {
        isUnderMaintenance = await _cloudService.getMaintenanceStatus();
      } catch (_) {}
      final cloudData = await _cloudService.loadFullCafeData(cafeId);

      final cloudCats = cloudData['categories'] as List<Category>?;
      if (cloudCats != null) {
        categories
          ..clear()
          ..addAll(cloudCats);
      }

      final cloudProds = cloudData['products'] as List<Product>?;
      if (cloudProds != null) {
        final deduped = _deduplicateProducts(cloudProds);
        products
          ..clear()
          ..addAll(deduped);
      }

      final cloudHalls = cloudData['halls'] as List<Hall>?;
      if (cloudHalls != null) {
        halls
          ..clear()
          ..addAll(cloudHalls);
        if (selectedHall != null) {
          final curName = selectedHall!.name.trim().toLowerCase();
          try {
            selectedHall = halls.firstWhere(
              (h) => h.id == selectedHall!.id || h.name.trim().toLowerCase() == curName,
            );
          } catch (_) {
            selectedHall = halls.isNotEmpty ? halls.first : null;
          }
        } else if (halls.isNotEmpty) {
          selectedHall = halls.first;
        } else {
          selectedHall = null;
        }
      }

      final cloudTables = cloudData['tables'] as List<TableModel>?;
      if (cloudTables != null) {
        tables
          ..clear()
          ..addAll(cloudTables);
        if (selectedTable != null) {
          final curId = selectedTable!.id;
          final curHallId = selectedTable!.hallId;
          final curNum = selectedTable!.number;
          try {
            selectedTable = tables.firstWhere(
              (t) => t.id == curId || (t.hallId == curHallId && t.number == curNum),
            );
          } catch (_) {
            selectedTable = tables.isNotEmpty ? tables.first : null;
          }
        } else if (tables.isNotEmpty) {
          selectedTable = tables.first;
        } else {
          selectedTable = null;
        }
      }

      final cloudCusts = cloudData['customers'] as List<Customer>?;
      if (cloudCusts != null) {
        customers
          ..clear()
          ..addAll(cloudCusts);
      }

      final cloudReceipts = cloudData['receipts'] as List<Receipt>?;
      if (cloudReceipts != null) {
        receipts
          ..clear()
          ..addAll(cloudReceipts);
      }

      final cloudOrders = cloudData['customerOrders'] as List<CustomerOrder>?;
      if (cloudOrders != null) {
        customerOrders
          ..clear()
          ..addAll(cloudOrders);
      }

      final cloudTableOrders =
          cloudData['tableOrders'] as Map<int, List<CartItem>>?;
      if (cloudTableOrders != null) {
        tableOrders
          ..clear()
          ..addAll(cloudTableOrders);
      }

      final cloudTableNotes = cloudData['tableNotes'] as Map<int, String>?;
      if (cloudTableNotes != null) {
        tableNotes
          ..clear()
          ..addAll(cloudTableNotes);
      }

      final cloudReports = cloudData['reports'] as List<DailyReport>?;
      if (cloudReports != null) {
        dailyReports
          ..clear()
          ..addAll(cloudReports);
      }

      if (cloudData['todayReport'] is TodayReportSummary) {
        liveTodayReport = cloudData['todayReport'] as TodayReportSummary;
      } else {
        unawaited(fetchLiveTodayReport());
      }

      final cloudEmps = cloudData['employees'] as List<AppUser>?;
      if (cloudEmps != null && cloudEmps.isNotEmpty) {
        users
          ..clear()
          ..addAll(cloudEmps);
      }

      final cloudSettings = cloudData['settings'] as Map<String, dynamic>?;
      if (cloudSettings != null && cloudSettings.isNotEmpty) {
        restaurantName = cloudSettings['restaurantName'] ?? restaurantName;
        if (cloudSettings.containsKey('receiptName') || cloudData.containsKey('receiptName')) {
          receiptName = cloudSettings['receiptName'] ?? cloudData['receiptName'];
        }
        restaurantAddress =
            cloudSettings['restaurantAddress'] ?? restaurantAddress;
        restaurantPhone = cloudSettings['restaurantPhone'] ?? restaurantPhone;
        receiptFooterNote =
            cloudSettings['receiptFooterNote'] ?? receiptFooterNote;
        receiptSlogan = cloudSettings['receiptSlogan'] ?? receiptSlogan;
        if (cloudSettings.containsKey('showQrOnReceipt')) {
          final sq = cloudSettings['showQrOnReceipt'];
          receiptQrEnabled = sq == true || sq == 'true' || sq == 1;
        } else if (cloudSettings.containsKey('receiptQrEnabled')) {
          final qe = cloudSettings['receiptQrEnabled'];
          receiptQrEnabled = qe == true || qe == 'true' || qe == 1;
        }
        if (cloudSettings.containsKey('receiptQrUrl') && cloudSettings['receiptQrUrl'] != null) {
          final qu = cloudSettings['receiptQrUrl'].toString().trim();
          if (qu.isNotEmpty) receiptQrUrl = qu;
        }
        if (cloudSettings.containsKey('darkMode')) {
          final dm = cloudSettings['darkMode'];
          darkMode = dm == true || dm == 'true' || dm == 1;
        }
        appLogoUrl = cloudSettings['appLogoUrl']?.toString() ?? appLogoUrl;
        if (cloudSettings['promoBanners'] is List) {
          promoBanners = List<Map<String, dynamic>>.from(
            (cloudSettings['promoBanners'] as List).map((e) => Map<String, dynamic>.from(e as Map)),
          );
        }
        if (cloudSettings.containsKey('printerConnectionType')) {
          printerConnectionType = cloudSettings['printerConnectionType']?.toString() ?? printerConnectionType;
        }
        if (cloudSettings.containsKey('printerIp')) {
          printerIp = cloudSettings['printerIp']?.toString() ?? printerIp;
        }
        if (cloudSettings.containsKey('printerPort')) {
          final p = cloudSettings['printerPort'];
          printerPort = p is num ? p.toInt() : (int.tryParse('$p') ?? printerPort);
        }
        if (cloudSettings.containsKey('reports_reset_at') && cloudSettings['reports_reset_at'] != null) {
          final rAt = DateTime.tryParse(cloudSettings['reports_reset_at'].toString());
          if (rAt != null) reportsResetAt = rAt;
        }
        if (cloudSettings.containsKey('printerUsbName')) {
          printerUsbName = cloudSettings['printerUsbName']?.toString();
        }
        if (cloudSettings.containsKey('printerBtName')) {
          printerBtName = cloudSettings['printerBtName']?.toString();
        }
        if (cloudSettings.containsKey('autoPrintOnPaid')) {
          final ap = cloudSettings['autoPrintOnPaid'];
          autoPrintOnPaid = ap == true || ap == 'true' || ap == 1;
        }
        if (cloudSettings.containsKey('kitchenPrinterEnabled')) {
          final kp = cloudSettings['kitchenPrinterEnabled'];
          kitchenPrinterEnabled = kp == true || kp == 'true' || kp == 1;
        }
        if (cloudSettings.containsKey('kitchenPrinterConnectionType')) {
          kitchenPrinterConnectionType = cloudSettings['kitchenPrinterConnectionType']?.toString() ?? kitchenPrinterConnectionType;
        }
        if (cloudSettings.containsKey('kitchenPrinterIp')) {
          kitchenPrinterIp = cloudSettings['kitchenPrinterIp']?.toString() ?? kitchenPrinterIp;
        }
        if (cloudSettings.containsKey('kitchenPrinterPort')) {
          final kp = cloudSettings['kitchenPrinterPort'];
          kitchenPrinterPort = kp is num ? kp.toInt() : (int.tryParse('$kp') ?? kitchenPrinterPort);
        }
        if (cloudSettings.containsKey('kitchenPrinterUsbName')) {
          kitchenPrinterUsbName = cloudSettings['kitchenPrinterUsbName']?.toString();
        }
        if (cloudSettings.containsKey('kitchenPrinterBtName')) {
          kitchenPrinterBtName = cloudSettings['kitchenPrinterBtName']?.toString();
        }
        if (cloudSettings.containsKey('printerCharsPerLine')) {
          final cpl = cloudSettings['printerCharsPerLine'];
          printerCharsPerLine = cpl is num ? cpl.toInt() : (int.tryParse('$cpl') ?? printerCharsPerLine);
        }
        if (cloudSettings.containsKey('paperWidthMm')) {
          final pw = cloudSettings['paperWidthMm'];
          paperWidthMm = pw is num ? pw.toInt() : (int.tryParse('$pw') ?? paperWidthMm);
        }
        if (cloudSettings.containsKey('paperFormat')) {
          paperFormat = cloudSettings['paperFormat']?.toString() ?? paperFormat;
        }
        if (cloudSettings.containsKey('telegramReceiptsEnabled')) {
          telegramReceiptsEnabled = cloudSettings['telegramReceiptsEnabled'] == true ||
              cloudSettings['telegramReceiptsEnabled'] == 'true' ||
              cloudSettings['telegramReceiptsEnabled'] == 1;
        }
        if (cloudSettings.containsKey('telegramReceiptsChatId')) {
          telegramReceiptsChatId = cloudSettings['telegramReceiptsChatId']?.toString() ?? '';
        }
        if (cloudSettings.containsKey('receiptBoldHeader')) {
          final rbh = cloudSettings['receiptBoldHeader'];
          receiptBoldHeader = rbh == true || rbh == 'true' || rbh == 1;
        }

      }

      _startRealtimeListeners(cafeId);
      unawaited(loadAnnouncements());

      _cleanLegacyCategories();
      _deduplicateHallsAndTables();
      isCloudSynced = true;
      await saveData();
      notifyListeners();
    } catch (e) {
      debugPrint('loadCloudDataForCafe xatoligi: $e');
    }
  }

