  /// O'zbekiston kafelari uchun tayyor menyuni serverdan yuklab, state ga sinxronlash
  Future<bool> restoreDefaultMenu() async {
    final success = await _cloudService.restoreDefaultMenu();
    final cafeId = currentCafeId.isNotEmpty ? currentCafeId : (_activeLoadedCafeId ?? '');
    if (cafeId.isNotEmpty) {
      await loadCloudDataForCafe(cafeId);
    }
    notifyListeners();
    return success;
  }

  void _startRealtimeListeners(String cafeId) {
    if (cafeId.isEmpty || cafeId == 'local_default' || !ApiClient().isAuthenticated) {
      return;
    }
    try {
      SocketService().connect(token: ApiClient().token, cafeId: cafeId);
    } catch (_) {}
    try {
      SupabaseRealtimeService().subscribeToCafe(cafeId);
    } catch (_) {}

    _hallsSub?.cancel();
    _hallsSub = _cloudService.streamHalls(cafeId).listen((newHalls) {
      if (newHalls.isNotEmpty) {
        halls
          ..clear()
          ..addAll(newHalls);
        if (selectedHall == null || !halls.any((h) => h.id == selectedHall!.id)) {
          selectedHall = halls.isNotEmpty ? halls.first : null;
        }
        saveData();
        notifyListeners();
      }
    });

    _tablesSub?.cancel();
    _tablesSub = _cloudService.streamTables(cafeId).listen((newTables) {
      if (newTables.isNotEmpty) {
        for (final nt in newTables) {
          final curVer = _tableVersions[nt.id] ?? 0;
          if (nt.updatedAt > 0 && nt.updatedAt < curVer) {
            continue; // Eskirgan / out-of-order ma'lumotni kiritmaymiz
          }
          final idx = tables.indexWhere((t) => t.id == nt.id);
          if (idx != -1) {
            tables[idx] = nt;
          } else {
            tables.add(nt);
          }
          if (nt.updatedAt > 0) {
            _tableVersions[nt.id] = nt.updatedAt;
          }
        }
        _syncTableStatusesFromOrders();
        saveData();
        _debounceNotifyTables();
      }
    });

    _tableOrdersSub?.cancel();
    _tableOrdersSub =
        _cloudService.streamTableOrders(cafeId).listen((newOrders) {
      final now = DateTime.now().millisecondsSinceEpoch;

      // 1. To'langan yoki bo'shatilgan stollarni xotiradan to'liq tozalash
      final currentKeys = tableOrders.keys.toList();
      for (final tableId in currentKeys) {
        final lastMutation = _tableOrderMutationTimes[tableId] ?? 0;
        if (now - lastMutation < 4000) continue;
        if (!newOrders.containsKey(tableId) || (newOrders[tableId]?.isEmpty ?? true)) {
          tableOrders.remove(tableId);
          tableNotes.remove(tableId);
          final tIdx = tables.indexWhere((t) => t.id == tableId);
          if (tIdx != -1) {
            tables[tIdx].status = TableStatus.free;
            tableOrdersByZone.remove(tables[tIdx].tableKey);
            tableNotesByZone.remove(tables[tIdx].tableKey);
          }
        }
      }

      // 2. Yangi buyurtmalarni yangilash
      for (final entry in newOrders.entries) {
        final tableId = entry.key;
        final remoteItems = entry.value;
        final lastMutation = _tableOrderMutationTimes[tableId] ?? 0;
        if (now - lastMutation < 4000) {
          continue;
        }
        final tIdx = tables.indexWhere((t) => t.id == tableId);
        final tableKey = tIdx != -1 ? tables[tIdx].tableKey : null;

        if (remoteItems.isNotEmpty) {
          tableOrders[tableId] = remoteItems;
          if (tableKey != null) tableOrdersByZone[tableKey] = remoteItems;
          if (tIdx != -1) {
            tables[tIdx].status = TableStatus.occupied;
          }
        } else {
          tableOrders.remove(tableId);
          if (tableKey != null) tableOrdersByZone.remove(tableKey);
          if (tIdx != -1) {
            tables[tIdx].status = TableStatus.free;
          }
        }
      }

      _syncTableStatusesFromOrders();

      if (selectedTable != null) {
        final lastMutation = _tableOrderMutationTimes[selectedTable!.id] ?? 0;
        final userIsEditingLocally = (now - lastMutation < 4000) ||
            (_lastLocalCartUserMutationTime != null &&
                DateTime.now().difference(_lastLocalCartUserMutationTime!).inMilliseconds < 4000);

        if (!userIsEditingLocally) {
          final remoteItems = tableOrders[selectedTable!.id];
          if (remoteItems != null && remoteItems.isNotEmpty) {
            cart
              ..clear()
              ..addAll(
                remoteItems.map(
                  (c) => CartItem(
                    product: c.product,
                    qty: c.qty,
                    note: c.note,
                  ),
                ),
              );
          }
        }
      }
      notifyListeners();
    });


    _categoriesSub?.cancel();
    _categoriesSub = _cloudService.streamCategories(cafeId).listen((newCategories) {
      categories
        ..clear()
        ..addAll(newCategories);
      saveData();
      notifyListeners();
    });

    _productsSub?.cancel();
    _productsSub = _cloudService.streamProducts(cafeId).listen((newProducts) {
      final deduped = _deduplicateProducts(newProducts);
      products
        ..clear()
        ..addAll(deduped);
      saveData();
      notifyListeners();
    });

    _customersSub?.cancel();
    _customersSub = _cloudService.streamCustomers(cafeId).listen((newCustomers) {
      if (newCustomers.isEmpty) return;
      customers
        ..clear()
        ..addAll(newCustomers);
      notifyListeners();
    });

    _employeesSub?.cancel();
    final canAccessEmployees = currentUser?.role == UserRole.admin ||
        currentUser?.role == UserRole.director;
    if (canAccessEmployees) {
      _employeesSub = _cloudService.streamEmployees(cafeId).listen((newEmployees) {
        if (newEmployees.isNotEmpty) {
          users
            ..clear()
            ..addAll(newEmployees);
          notifyListeners();
        }
      });
    }

    _ordersSub?.cancel();
    _ordersSub = _cloudService.streamCustomerOrders(cafeId).listen((newOrders) {
      _handleIncomingCustomerOrders(newOrders);
    });

    _settingsSub?.cancel();
    _settingsSub = SocketService().on(CafeSocketEvent.settingsUpdated).listen((eventData) {
      // ignore: unnecessary_type_check
      if (eventData is Map) {
        final raw = eventData['settings'] ?? eventData;
        if (raw is Map) {
          if (raw.containsKey('receiptQrUrl') && raw['receiptQrUrl'] != null) {
            final qu = raw['receiptQrUrl'].toString().trim();
            if (qu.isNotEmpty) receiptQrUrl = qu;
          }
          if (raw.containsKey('showQrOnReceipt')) {
            final sq = raw['showQrOnReceipt'];
            receiptQrEnabled = sq == true || sq == 'true' || sq == 1;
          } else if (raw.containsKey('receiptQrEnabled')) {
            final re = raw['receiptQrEnabled'];
            receiptQrEnabled = re == true || re == 'true' || re == 1;
          }
          saveData();
          notifyListeners();
        }
      }
    });

    _customerOrdersPollTimer?.cancel();
    _customerOrdersPollTimer = Timer.periodic(const Duration(seconds: 4), (_) {
      // 1. Agar socket vaqtincha uzilgan bo'lsa yoki xabar kechiksa, stollarni fonda sokin sinxronlaymiz
      if (!SocketService().isConnected && currentCafeId.isNotEmpty) {
        _cloudService.fetchTables(currentCafeId).then((cloudTables) {
          if (cloudTables.isNotEmpty) {
            tables
              ..clear()
              ..addAll(cloudTables);
            _syncTableStatusesFromOrders();
            notifyListeners();
          }
        }).catchError((_) {});
      }
      // 2. FAQAT ofitsiant paneliga kelishi kerak (Admin/Kafe paneliga emas)
      if (currentUser != null && currentUser?.role == UserRole.waiter) {
        forceRefreshCustomerOrders();
      }
    });

    _receiptsSub?.cancel();
    _receiptsSub = _cloudService.streamReceipts(cafeId).listen((newReceipts) {
      receipts
        ..clear()
        ..addAll(newReceipts);
      notifyListeners();
    });

    _maintenanceSub?.cancel();
    _maintenanceSub = SocketService().on(CafeSocketEvent.maintenanceStatus).listen((data) {
      final maint = data['isUnderMaintenance'] == true;
      if (isUnderMaintenance != maint) {
        isUnderMaintenance = maint;
        notifyListeners();
      }
    });

    _reportsSub?.cancel();
    final canAccessReports = currentUser?.role == UserRole.admin ||
        currentUser?.role == UserRole.director;
    if (canAccessReports) {
      _reportsSub = _cloudService.streamReports(cafeId).listen((newReports) {
        dailyReports
          ..clear()
          ..addAll(newReports);
        notifyListeners();
      });
    }

    // ============================================================
    // REAL-TIME STOLLAR VA OFITSIANT/KAFE SINXRONIZATSIYASI (0-MS)
    // ============================================================
    _socketTableStatusSub?.cancel();
    _socketTableStatusSub = SocketService().on(CafeSocketEvent.tableStatusUpdated).listen((data) {
      if (data['resync'] == true) {
        if (currentCafeId.isNotEmpty) {
          loadCloudDataForCafe(currentCafeId);
        }
        return;
      }
      if (data['clearedAll'] == true) {
        tables.clear();
        tableOrders.clear();
        tableNotes.clear();
        _debounceNotifyTables();
        return;
      }
      final tableDeletedId = safeNullableInt(data['tableDeleted']);
      if (tableDeletedId != null) {
        tables.removeWhere((t) => t.id == tableDeletedId);
        tableOrders.remove(tableDeletedId);
        tableNotes.remove(tableDeletedId);
        if (selectedTable?.id == tableDeletedId) {
          selectedTable = null;
          cart.clear();
        }
        _debounceNotifyTables();
        return;
      }

      final tId = safeNullableInt(data['tableId']);
      final eventTs = safeInt(data['updatedAt']);
      if (tId != null && eventTs > 0) {
        final curVer = _tableVersions[tId] ?? 0;
        if (eventTs < curVer) {
          return; // Out-of-order xabar, e'tiborsiz qoldiriladi
        }
        _tableVersions[tId] = eventTs;
      }

      final tableMap = data['table'];
      if (tableMap is Map) {
        try {
          final updatedT = TableModel.fromJson(Map<String, dynamic>.from(tableMap));
          final existingIdx = tables.indexWhere((t) => t.id == updatedT.id);
          if (existingIdx != -1) {
            tables[existingIdx] = updatedT;
          } else {
            tables.add(updatedT);
          }
        } catch (_) {}
      }
      final tNum = safeNullableInt(data['tableNumber']);
      final tHallId = safeNullableInt(data['hallId']);
      final st = data['status'] as String?;
      final isOcc = (st == 'occupied');

      bool updated = false;
      if (tId != null) {
        if (!isOcc) {
          tableOrders.remove(tId);
          tableNotes.remove(tId);
        }
      }

      for (final t in tables) {
        final matches = (tHallId != null && t.hallId == tHallId && ((tId != null && t.id == tId) || (tNum != null && t.number == tNum))) ||
            (tHallId == null && tId != null && t.id == tId);
        if (matches) {
          t.status = isOcc ? TableStatus.occupied : TableStatus.free;
          if (!isOcc) {
            tableOrders.remove(t.id);
            tableOrdersByZone.remove(t.tableKey);
            tableNotes.remove(t.id);
            tableNotesByZone.remove(t.tableKey);
          }
          updated = true;
        }
      }
      if (updated) _debounceNotifyTables();
    });

    _socketTableOrderSub?.cancel();
    _socketTableOrderSub = SocketService().on(CafeSocketEvent.tableOrderUpdated).listen((data) {
      if (data['resync'] == true) {
        if (currentCafeId.isNotEmpty) {
          loadCloudDataForCafe(currentCafeId);
        }
        return;
      }
      final tId = safeNullableInt(data['tableId']);
      final eventTs = safeInt(data['updatedAt']);
      if (tId != null && eventTs > 0) {
        final curVer = _tableVersions[tId] ?? 0;
        if (eventTs < curVer) {
          return; // Out-of-order xabar, e'tiborsiz qoldiriladi
        }
        _tableVersions[tId] = eventTs;
      }

      final tNum = safeNullableInt(data['tableNumber']);
      final tHallId = safeNullableInt(data['hallId']);
      final rawItems = data['items'];
      final hasItems = rawItems is List && rawItems.isNotEmpty;

      bool updated = false;
      if (!hasItems && tId != null) {
        tableOrders.remove(tId);
        tableNotes.remove(tId);
      }

      for (final t in tables) {
        final matches = (tHallId != null && t.hallId == tHallId && ((tId != null && t.id == tId) || (tNum != null && t.number == tNum))) ||
            (tHallId == null && tId != null && t.id == tId);
        if (matches) {
          if (hasItems) {
            final items = rawItems
                .whereType<Map>()
                .map((m) => CartItem.fromJson(Map<String, dynamic>.from(m)))
                .toList();
            tableOrders[t.id] = items;
            tableOrdersByZone[t.tableKey] = items;
            t.status = TableStatus.occupied;
          } else {
            tableOrders.remove(t.id);
            tableOrdersByZone.remove(t.tableKey);
            tableNotes.remove(t.id);
            tableNotesByZone.remove(t.tableKey);
            t.status = TableStatus.free;
          }
          updated = true;
        }
      }
      if (updated) _debounceNotifyTables();
    });

    _socketTableReleasedSub?.cancel();
    _socketTableReleasedSub = SocketService().on(CafeSocketEvent.tableReleased).listen((data) {
      if (data['resync'] == true) {
        if (currentCafeId.isNotEmpty) {
          loadCloudDataForCafe(currentCafeId);
        }
        return;
      }
      final tId = safeNullableInt(data['tableId']);
      final tNum = safeNullableInt(data['tableNumber']);
      final tHallId = safeNullableInt(data['hallId']);
      final eventTs = safeInt(data['updatedAt']);
      final nowTime = DateTime.now().millisecondsSinceEpoch;

      if (tId != null) {
        if (eventTs > 0) {
          final curVer = _tableVersions[tId] ?? 0;
          if (eventTs < curVer) return;
          _tableVersions[tId] = eventTs;
        } else {
          _tableVersions[tId] = nowTime;
        }
        tableOrders.remove(tId);
        tableNotes.remove(tId);
        _tableOrderMutationTimes[tId] = nowTime;
        unawaited(OfflineSyncService().removeActionsForTable(tId, cafeId: currentCafeId));
      }

      bool updated = false;
      for (final t in tables) {
        final matches = (tHallId != null && t.hallId == tHallId && ((tId != null && t.id == tId) || (tNum != null && t.number == tNum))) ||
            (tHallId == null && tId != null && t.id == tId);
        if (matches) {
          t.status = TableStatus.free;
          tableOrders.remove(t.id);
          tableOrdersByZone.remove(t.tableKey);
          tableNotes.remove(t.id);
          tableNotesByZone.remove(t.tableKey);
          _tableOrderMutationTimes[t.id] = nowTime;
          updated = true;
        }
      }
      if (updated) _debounceNotifyTables();
    });

    // Real-time receipts sync across devices and Telegram WebApp
    _socketReceiptAddedSub?.cancel();
    _socketReceiptAddedSub = SocketService().on(CafeSocketEvent.receiptAdded).listen((data) {
      try {
        final rRaw = data['receipt'];
        if (rRaw is Map) {
          final r = Receipt.fromJson(Map<String, dynamic>.from(rRaw));
          if (!receipts.any((x) => x.id == r.id)) {
            receipts.insert(0, r);

            // Optimistik hisobot yangilanishi: 0 millisekundda Jami Daromad va Jami Buyurtmalar ko'tariladi
            final rCash = (r.method == PaymentMethod.cash)
                ? r.total.round()
                : (r.cashPaid.round());
            final rCard = (r.method == PaymentMethod.card)
                ? r.total.round()
                : (r.cardPaid.round());
            final currentRep = liveTodayReport;
            if (currentRep != null) {
              final newRev = currentRep.totalRevenue + r.total.round();
              final newOrders = currentRep.orderCount + 1;
              final newCash = currentRep.cashTotal + rCash;
              final newCard = currentRep.cardTotal + rCard;
              final newAvg = newOrders > 0 ? (newRev / newOrders).round() : 0;
              liveTodayReport = TodayReportSummary(
                totalRevenue: newRev,
                orderCount: newOrders,
                cashTotal: newCash,
                cardTotal: newCard,
                averageCheck: newAvg,
                waiters: currentRep.waiters,
                topProducts: currentRep.topProducts,
                updatedAt: DateTime.now(),
              );
            } else {
              liveTodayReport = TodayReportSummary(
                totalRevenue: r.total.round(),
                orderCount: 1,
                cashTotal: rCash,
                cardTotal: rCard,
                averageCheck: r.total.round(),
                waiters: const [],
                topProducts: const [],
                updatedAt: DateTime.now(),
              );
            }

            final placeInfo = r.tableNumber != null
                ? (r.hallName != null && r.hallName!.isNotEmpty ? '${r.hallName}, ${r.tableNumber}-stol' : '${r.tableNumber}-stol')
                : (r.hallName ?? 'Kassa');
            addAppNotification(AppNotificationItem(
              id: 'receipt_${r.id}',
              title: "Chek to'landi #${r.id}",
              body: "${formatSum(r.total)} so'm • ${r.method == PaymentMethod.card ? 'Karta' : 'Naqd'} ($placeInfo)",
              time: DateTime.now(),
              type: 'receipt',
            ));
            unawaited(fetchLiveTodayReport());
            notifyListeners();
          }
        }
      } catch (e) {
        debugPrint('⚠️ [Socket receiptAdded] parse error: $e');
      }
    }, onError: (err) {
      debugPrint('⚠️ [Socket receiptAdded] stream error: $err');
    });

    // Real-time financial reports sync across devices and Telegram WebApp
    _socketReportUpdatedSub?.cancel();
    _socketReportUpdatedSub = SocketService().on(CafeSocketEvent.reportUpdated).listen((data) {
      if (data['todayReport'] is Map) {
        try {
          liveTodayReport = TodayReportSummary.fromJson(Map<String, dynamic>.from(data['todayReport'] as Map));
        } catch (_) {}
      }
      final repRaw = data['report'];
      if (repRaw is Map) {
        final rep = DailyReport.fromJson(Map<String, dynamic>.from(repRaw));
        final idx = dailyReports.indexWhere((x) => x.dateId == rep.dateId);
        if (idx != -1) {
          dailyReports[idx] = rep;
        } else {
          dailyReports.insert(0, rep);
        }
      }
      notifyListeners();
    });

    // Real-time hisobotlar tozalanganda (barcha qurilmalarda 0 dan boshlanadi)
    _socketReportClearedSub?.cancel();
    _socketReportClearedSub = SocketService().on(CafeSocketEvent.reportCleared).listen((data) {
      if (data['all'] == true) {
        if (data['resetAt'] != null) {
          reportsResetAt = DateTime.tryParse(data['resetAt'].toString()) ?? DateTime.now();
        } else {
          reportsResetAt = DateTime.now();
        }
        dailyReports.clear();
        liveTodayReport = TodayReportSummary(
          totalRevenue: 0,
          orderCount: 0,
          cashTotal: 0,
          cardTotal: 0,
          averageCheck: 0,
          waiters: const [],
          topProducts: const [],
          updatedAt: DateTime.now(),
        );
      } else if (data['dateId'] != null) {
        final dId = data['dateId'].toString();
        dailyReports.removeWhere((r) => r.dateId == dId);
        receipts.removeWhere((r) => r.date.toIso8601String().substring(0, 10) == dId);
        unawaited(fetchLiveTodayReport());
      }
      saveData();
      notifyListeners();
    });

    // Real-time sound / voice settings sync across devices and Telegram WebApp
    _settingsSub?.cancel();
    _settingsSub = SocketService().on(CafeSocketEvent.settingsUpdated).listen((data) {
      final s = data['settings'];
      if (s is Map && s['voiceNotificationEnabled'] != null) {
        final enabled = s['voiceNotificationEnabled'] == true || s['voiceNotificationEnabled'] == 'true';
        if (voiceNotificationEnabled != enabled) {
          voiceNotificationEnabled = enabled;
          SoundService().setVoiceEnabled(enabled);
          saveData();
          notifyListeners();
        }
      }
    });

    // QR menyudan zakaz kelsa (stol skaner qilinganda) stol darhol band bo'ladi
    _socketNewCustomerOrderSub?.cancel();
    _socketNewCustomerOrderSub = SocketService().on(CafeSocketEvent.newCustomerOrder).listen((data) {
      final tNum = safeNullableInt(data['tableNumber']);
      final tHallId = safeNullableInt(data['hallId']);
      final tId = safeNullableInt(data['tableId']);
      if (tNum != null || tId != null) {
        final idx = tables.indexWhere((t) =>
            (tId != null && t.id == tId) ||
            (tNum != null && t.number == tNum && (tHallId == null || t.hallId == tHallId)));
        if (idx != -1) {
          tables[idx].status = TableStatus.occupied;
          notifyListeners();
        }
      }
    });

    // Real-time obuna uzaytirilganda (Telegram bot tasdiqlaganda)
    _subscriptionExtendedSub?.cancel();
    _subscriptionExtendedSub = SocketService().on(CafeSocketEvent.subscriptionExtended).listen((data) {
      if (currentUser != null) {
        currentUser!.isBlocked = false;
        currentUser!.isExpired = false;
        if (data['endDate'] != null) {
          currentUser!.cafeEndDate = DateTime.tryParse(data['endDate'].toString());
        }
        unawaited(saveUserSession(currentUser!));
      }
      addAppNotification(AppNotificationItem(
        id: DateTime.now().millisecondsSinceEpoch.toString(),
        title: "Obuna 30 kunga uzaytirildi! 🎉",
        body: "Admin obunangizni tasdiqladi. Barcha imkoniyatlar faol holatga keltirildi.",
        time: DateTime.now(),
        type: 'subscription',
      ));
      notifyListeners();
    });

    // Real-time promo banners (reklama) sync across QR Menu and Cafe Panel
    _socketBannersSub?.cancel();
    _socketBannersSub = SocketService().on(CafeSocketEvent.bannersUpdated).listen((data) {
      if (data['banners'] is List) {
        promoBanners = List<Map<String, dynamic>>.from(
          (data['banners'] as List).map((e) => Map<String, dynamic>.from(e as Map)),
        );
        notifyListeners();
      }
    });

    // Real-time mahsulotlar (ovqatlar) o'zgarishi va o'chirilishi sinxronizatsiyasi
    _socketProductsSub?.cancel();
    _socketProductsSub = SocketService().on(CafeSocketEvent.productsUpdated).listen((data) async {
      try {
        final deletedId = safeNullableInt(data['deletedId']);
        final rawDeletedIds = data['deletedIds'];
        if (deletedId != null) {
          products.removeWhere((p) => p.id == deletedId);
          await saveData();
          notifyListeners();
          return;
        } else if (rawDeletedIds is List && rawDeletedIds.isNotEmpty) {
          final idsSet = rawDeletedIds.map((e) => safeInt(e)).toSet();
          products.removeWhere((p) => idsSet.contains(p.id));
          await saveData();
          notifyListeners();
          return;
        }

        // Boshqa yangilanishlar (yangi ovqat yoki narx o'zgarganda)
        if (!ApiClient().isAuthenticated || cafeId.isEmpty || cafeId == 'local_default') {
          return;
        }
        final freshProds = await _cloudService.getProducts(cafeId);
        products
          ..clear()
          ..addAll(_deduplicateProducts(freshProds));
        await saveData();
        notifyListeners();
      } catch (e) {
        debugPrint('realtime productsUpdated xatosi: $e');
      }
    });

    // Real-time kategoriyalar sinxronizatsiyasi
    _socketCategoriesSub?.cancel();
    _socketCategoriesSub = SocketService().on(CafeSocketEvent.categoriesUpdated).listen((data) async {
      try {
        if (!ApiClient().isAuthenticated || cafeId.isEmpty || cafeId == 'local_default') {
          return;
        }
        final freshCats = await _cloudService.getCategories(cafeId);
        if (freshCats.isNotEmpty || categories.isNotEmpty) {
          categories
            ..clear()
            ..addAll(freshCats);
          await saveData();
          notifyListeners();
        }
      } catch (e) {
        debugPrint('realtime categoriesUpdated xatosi: $e');
      }
    });

    // Real-time Cloud / Station printing listener (Kassa printer stansiyasi uchun)
    _socketPrintJobSub?.cancel();
    _socketPrintJobSub = SocketService().on(CafeSocketEvent.executePrintJob).listen((payload) async {
      if (!isPrinterStation) return;
      final jobId = payload['id']?.toString() ?? '';
      final now = DateTime.now().millisecondsSinceEpoch;
      if (jobId.isNotEmpty) {
        final last = _executedPrintJobs[jobId] ?? 0;
        if (now - last < 5000) {
          debugPrint('⚠️ [PrinterStation] Takroriy chop etish so‘rovi rad etildi ($jobId)');
          return;
        }
        _executedPrintJobs[jobId] = now;
        if (_executedPrintJobs.length > 200) _executedPrintJobs.clear();
      }

      final html = payload['html']?.toString() ?? '';
      if (html.isEmpty) return;

      final tbl = payload['tableNumber']?.toString();
      await _executeSingleStationPrint(jobId, html, tbl);
    });

    // Real-time printer stansiyasi holatini kuzatish (Ofitsiant / mobil qurilmalar uchun)
    _socketPrinterStationStatusSub?.cancel();
    _socketPrinterStationStatusSub = SocketService().on(CafeSocketEvent.printerStationStatusChanged).listen((data) {
      hasCloudPrinterStation = data['hasStation'] == true;
      cloudPrinterStationName = data['stationName']?.toString();
      isCloudStationPrinterReady = data['isPrinterReady'] == true;
      notifyListeners();
    });

    // Majburiy sessiyani tugatish (parol/login o'zgarganda yoki xodim o'chirilganda)
    _userForceLogoutSub?.cancel();
    _userForceLogoutSub = SocketService().on(CafeSocketEvent.userForceLogout).listen((data) {
      final targetUserId = data['userId'];
      final targetUsername = data['username']?.toString().toLowerCase();
      final currentUserId = currentUser?.id;
      final currentUsername = currentUser?.username.toLowerCase();
      if ((targetUserId != null && targetUserId == currentUserId) ||
          (targetUsername != null && targetUsername == currentUsername)) {
        logout();
      }
    });

    // Real-time e'lonlar (Direktor e'lonlari)
    _socketAnnouncementSub?.cancel();
    _socketAnnouncementSub = SocketService().on(CafeSocketEvent.newAnnouncement).listen((data) {
      final annData = data['announcement'];
      if (annData is Map) {
        final ann = AnnouncementItem.fromJson(Map<String, dynamic>.from(annData));
        announcements.insert(0, ann);

        try {
          SoundService().playNewOrderSound();
        } catch (_) {}

        addAppNotification(AppNotificationItem(
          id: ann.id.toString(),
          title: "📢 E'lon: ${ann.title}",
          body: ann.message,
          time: ann.createdAt,
          type: 'announcement',
        ));

        final messenger = rootMessengerKey.currentState ?? appMessengerKey.currentState;
        if (messenger != null) {
          final isUrgent = ann.priority == 'urgent';
          final isImportant = ann.priority == 'important';
          messenger.showSnackBar(
            SnackBar(
              duration: Duration(seconds: isUrgent ? 10 : 6),
              backgroundColor: isUrgent
                  ? const Color(0xFFDC2626)
                  : (isImportant ? const Color(0xFFD97706) : const Color(0xFF1E293B)),
              behavior: SnackBarBehavior.floating,
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
              content: Row(
                children: [
                  Icon(
                    isUrgent ? Icons.warning_rounded : Icons.campaign_rounded,
                    color: Colors.white,
                    size: 24,
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          ann.title.isNotEmpty ? ann.title : "Direktor e'loni",
                          style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 14),
                        ),
                        Text(
                          ann.message,
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(color: Colors.white70, fontSize: 12),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          );
        }

        notifyListeners();
      }
    });

    if (isPrinterStation && cafeId.isNotEmpty && cafeId != 'local_default') {
      SocketService().registerPrinterStation(
        cafeId,
        stationName: effectiveReceiptName.isNotEmpty ? effectiveReceiptName : 'Kassa stansiyasi',
        isPrinterReady: isPrinterVerified,
      );
      _startPrinterStationHeartbeat();
      unawaited(_processPendingPrintJobs());
    } else if (cafeId.isNotEmpty && cafeId != 'local_default') {
      unawaited(checkCloudPrinterStationStatus());
    }

    // Xodimlar ro'yxatini kuzatuv xizmatiga sinxronlash
    StaffTrackingService().syncStaffList(users);
  }

  Future<bool> _executeSingleStationPrint(String jobId, String html, String? tableNumber) async {
    final tblText = (tableNumber != null && tableNumber.isNotEmpty) ? ' (Stol $tableNumber)' : '';
    debugPrint('🖨️ [PrinterStation] Masofaviy chek keldi va chop etilmoqda$tblText: $jobId');

    showZaveroSnackBar(
      message: '🖨️ Kassa printeri: Chek chop etilmoqda$tblText',
      duration: const Duration(seconds: 2),
      backgroundColor: const Color(0xFF1E293B),
    );

    bool printedSuccess = false;
    try {
      final is58mm = paperWidthMm == 58 || printerCharsPerLine <= 32;
      if (kIsWeb) {
        final isAgentUp = await PrintAgentService().isAgentRunning();
        if (isAgentUp && printerConfigured) {
          final pngBase64 = await WebReceiptPrinter.renderHtmlToPng(html, widthPx: is58mm ? 384 : 576);
          if (pngBase64 != null && pngBase64.isNotEmpty) {
            printedSuccess = await PrintAgentService().printJob(
              jobId: jobId,
              type: 'remote',
              printerConfig: {
                'type': printerConnectionType,
                'ip': printerIp,
                'port': printerPort,
                'deviceId': printerConnectionType == 'usb' ? printerUsbName : printerBtName,
                'paperWidth': paperWidthMm,
              },
              imageBase64: pngBase64,
              openDrawer: true,
            );
          }
        }
        if (!printedSuccess) {
          printedSuccess = await WebReceiptPrinter.printHtml(html);
        }
      } else if (!kIsWeb && printerConfigured && printerConnectionType == 'wifi') {
        printedSuccess = true;
      }
    } catch (e) {
      debugPrint('❌ [PrinterStation] Chop etishda xatolik: $e');
    }

    if (printedSuccess) {
      unawaited(ApiClient().post('/receipts/print-jobs/$jobId/complete').catchError((_) => <String, dynamic>{}));
    } else {
      unawaited(ApiClient().post('/receipts/print-jobs/$jobId/fail', body: {'error': 'Chop etib bo\'lmadi'}).catchError((_) => <String, dynamic>{}));
    }
    return printedSuccess;
  }

  Future<void> _processPendingPrintJobs() async {
    if (!isPrinterStation || currentCafeId.isEmpty) return;
    try {
      final res = await ApiClient().get('/receipts/pending-jobs?cafeId=$currentCafeId');
      if (res['success'] == true && res['jobs'] is List) {
        for (final job in (res['jobs'] as List)) {
          if (job is Map) {
            final jobId = job['id']?.toString() ?? '';
            final html = job['html']?.toString() ?? '';
            if (html.isNotEmpty && jobId.isNotEmpty) {
              await _executeSingleStationPrint(jobId, html, job['table_number']?.toString());
            }
          }
        }
      }
    } catch (e) {
      debugPrint('pending-jobs error: $e');
    }
  }

  DailyReport? reportForDate(DateTime date) {
    final id = DailyReport.dateIdFrom(date);
    try {
      return dailyReports.firstWhere((r) => r.dateId == id);
    } catch (_) {
      final dayReceipts = receipts
          .where(
            (r) =>
                r.date.year == date.year &&
                r.date.month == date.month &&
                r.date.day == date.day,
          )
          .toList();

      if (dayReceipts.isEmpty) return null;

      double total = 0;
      final qtyMap = <String, int>{};
      final revMap = <String, double>{};
      final tableMap = <String, double>{};

      for (final r in dayReceipts) {
        total += r.total;
        final tKey =
            r.tableNumber != null ? 'Stol ${r.tableNumber}' : 'Olib ketish';
        tableMap[tKey] = (tableMap[tKey] ?? 0) + r.total;

        for (final item in r.items) {
          final pName = item.product.name;
          qtyMap[pName] = (qtyMap[pName] ?? 0) + item.qty;
          revMap[pName] = (revMap[pName] ?? 0) + item.total;
        }
      }

      String topP = '';
      int maxQty = 0;
      qtyMap.forEach((k, v) {
        if (v > maxQty) {
          maxQty = v;
          topP = k;
        }
      });

      return DailyReport(
        dateId: id,
        totalRevenue: total,
        orderCount: dayReceipts.length,
        productQuantities: qtyMap,
        productRevenue: revMap,
        topProduct: topP,
        tableRevenue: tableMap,
        updatedAt: DateTime.now(),
      );
    }
  }

  // ---------------- KASSIR SAVATI & STOL BAND QILISH LOGIKASI ----------------

  /// Stol uchun aktiv (bo'sh bo'lmagan) buyurtma bormi?
  bool hasActiveOrder(dynamic tableOrId) {
    if (tableOrId is TableModel) {
      final byZone = tableOrdersByZone[tableOrId.tableKey];
      if (byZone != null && byZone.isNotEmpty) return true;
      final byId = tableOrders[tableOrId.id];
      return byId != null && byId.isNotEmpty;
    }
    if (tableOrId is int) {
      final byId = tableOrders[tableOrId];
      if (byId != null && byId.isNotEmpty) return true;
      for (final e in tableOrdersByZone.entries) {
        if (e.key.endsWith('_$tableOrId') && e.value.isNotEmpty) return true;
      }
    }
    return false;
  }

  /// Barcha stollar holatini `tableOrders` bilan sinxronlashtiradi.
  void _reconcileAllTableStatuses() {
    for (final table in tables) {
      final occupied = hasActiveOrder(table);
      table.status = occupied ? TableStatus.occupied : TableStatus.free;
      if (!occupied && selectedTable?.id != table.id) {
        tableOrders.remove(table.id);
        tableOrdersByZone.remove(table.tableKey);
        tableNotes.remove(table.id);
        tableNotesByZone.remove(table.tableKey);
      }
    }
  }

  void _syncTableStatusesFromOrders() {
    for (final table in tables) {
      final hasOrder = hasActiveOrder(table);
      if (hasOrder) {
        table.status = TableStatus.occupied;
      } else if (table.status == TableStatus.free) {
        if (selectedTable?.id != table.id) {
          tableOrders.remove(table.id);
          tableOrdersByZone.remove(table.tableKey);
          tableNotes.remove(table.id);
          tableNotesByZone.remove(table.tableKey);
        }
      }
    }
  }

  /// Bitta stol holatini aktiv buyurtmaga qarab yangilaydi (bulut + disk).
  void _syncTableStatusFor(int tableId) {
    final idx = tables.indexWhere((t) => t.id == tableId);
    if (idx == -1) return;

    final occupied = hasActiveOrder(tables[idx]);
    final table = tables[idx];
    final newStatus = occupied ? TableStatus.occupied : TableStatus.free;
    table.status = newStatus;
    unawaited(_persistTableStatus(tableId, occupied));
  }

  Future<void> _persistTableStatus(int tableId, bool occupied) async {
    try {
      if (occupied) {
        await _cloudService.updateTableStatus(
          cafeId: currentCafeId,
          tableId: tableId,
          status: TableStatus.occupied,
        );
      } else {
        await _cloudService.releaseTable(
          cafeId: currentCafeId,
          tableId: tableId,
        );
      }
      _cartSaveDebounceTimer?.cancel();
      await _saveCartAndTablesOnly();
    } catch (e) {
      debugPrint('_persistTableStatus xatoligi: $e');
    }
  }

  /// To'lov/menyu ekranidan stol tanlashga qaytganda sessiyani saqlab tozalaydi
  void leaveOrderSession() {
    if (selectedTable != null && cart.isNotEmpty) {
      final tId = selectedTable!.id;
      final savedItems = List<CartItem>.from(cart);
      final savedNote = selectedTableNote;
      _syncCartToTable();
      _saveCartRemoteOnly(targetTableId: tId, targetItems: savedItems, targetNote: savedNote);
    }
    _saveCartLocalOnly();
    cart.clear();
    selectedTable = null;
    notifyListeners();
  }

  /// Stol tanlanganda uning joriy buyurtmasi cartga yuklanadi.
  void selectTable(TableModel t) {
    selectedTable = t;
    if (selectedHall?.id != t.hallId) {
      final hIdx = halls.indexWhere((h) => h.id == t.hallId);
      if (hIdx != -1) {
        selectedHall = halls[hIdx];
      }
    }
    final items = tableOrdersByZone[t.tableKey] ?? tableOrders[t.id];
    cart
      ..clear()
      ..addAll(
        (items ?? const [])
            .map((c) => CartItem(product: c.product, qty: c.qty, note: c.note)),
      );
    if (cart.isNotEmpty) {
      t.status = TableStatus.occupied;
    } else if (t.status == TableStatus.occupied) {
      _loadTableOrderFor(t.id);
    }
    notifyListeners();
  }

  Future<void> _loadTableOrderFor(int tableId) async {
    try {
      final cached = await LocalCacheService().getCachedMap('cache_table_orders_$currentCafeId');
      if (cached != null && cached.containsKey('$tableId')) {
        final rawList = cached['$tableId'];
        if (rawList is List && rawList.isNotEmpty) {
          final loadedItems = rawList
              .whereType<Map>()
              .map((e) => CartItem.fromJson(Map<String, dynamic>.from(e)))
              .toList();
          if (loadedItems.isNotEmpty) {
            tableOrders[tableId] = loadedItems;
            final tIdx = tables.indexWhere((tbl) => tbl.id == tableId);
            if (tIdx != -1) {
              tableOrdersByZone[tables[tIdx].tableKey] = loadedItems;
              tables[tIdx].status = TableStatus.occupied;
            }
            if (selectedTable?.id == tableId && cart.isEmpty) {
              cart
                ..clear()
                ..addAll(loadedItems.map((c) => CartItem(product: c.product, qty: c.qty, note: c.note)));
              notifyListeners();
            }
          }
        }
      }
    } catch (e) {
      debugPrint('_loadTableOrderFor error: $e');
    }
  }

  void _syncCartToTable() {
    if (selectedTable == null) return;
    final table = selectedTable!;
    final tableId = table.id;
    final zoneKey = table.tableKey;

    if (cart.isEmpty) {
      tableOrders.remove(tableId);
      tableOrdersByZone.remove(zoneKey);
      tableNotes.remove(tableId);
      tableNotesByZone.remove(zoneKey);
    } else {
      final items = List<CartItem>.from(
        cart.map((c) => CartItem(product: c.product, qty: c.qty, note: c.note)),
      );
      tableOrders[tableId] = items;
      tableOrdersByZone[zoneKey] = items;
      _tableOrderMutationTimes[tableId] = DateTime.now().millisecondsSinceEpoch;
    }

    _syncTableStatusFor(tableId);
    _scheduleCartSave();
  }

  /// Savat o'zgarishlarini mahalliy xotiraga darhol, serverga esa debounce bilan saqlash.
  void _scheduleCartSave() {
    _saveCartLocalOnly();
    _cartSaveDebounceTimer?.cancel();
    _cartSaveDebounceTimer = Timer(const Duration(milliseconds: 350), () {
      _saveCartRemoteOnly();
    });
  }

  /// Savat va stol buyurtmalarini mahalliy SharedPreferences + LocalCacheService ga yozish (0-ms)
  Future<void> _saveCartLocalOnly() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final jsonTableOrders = tableOrders.map(
        (k, v) => MapEntry(k.toString(), v.map((e) => e.toJson()).toList()),
      );
      for (final e in tableOrdersByZone.entries) {
        jsonTableOrders[e.key] = e.value.map((item) => item.toJson()).toList();
      }
      await prefs.setString('tableOrders', jsonEncode(jsonTableOrders));
      await prefs.setString('tableNotes', jsonEncode(tableNotes));
      await LocalCacheService().setCachedMap('cache_table_orders_$currentCafeId', jsonTableOrders);
    } catch (e) {
      debugPrint('_saveCartLocalOnly xatoligi: $e');
    }
  }

  /// Serverga fon rejimida saqlash (tezkor ketma-ket bosishlarni birlashtiradi)
  Future<void> _saveCartRemoteOnly({int? targetTableId, List<CartItem>? targetItems, String? targetNote}) async {
    final tableId = targetTableId ?? selectedTable?.id;
    if (tableId == null) return;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    _tableVersions[tableId] = nowMs;
    _tableOrderMutationTimes[tableId] = nowMs;
    final items = targetItems ?? List<CartItem>.from(cart);
    final note = targetNote ?? selectedTableNote;
    try {
      if (items.isNotEmpty) {
        final isPrivileged = currentUser?.role == UserRole.director ||
            currentUser?.role == UserRole.admin ||
            currentUser?.role == UserRole.cashier;
        await _cloudService.saveTableOrder(
          cafeId: currentCafeId,
          tableId: tableId,
          items: items,
          note: note,
          forceOccupy: isPrivileged,
        );
      }
    } on TableBusyException catch (e) {
      debugPrint('_saveCartRemoteOnly stol band: $e');
      if (currentCafeId.isNotEmpty) {
        loadCloudDataForCafe(currentCafeId);
      }
      addAppNotification(AppNotificationItem(
        id: 'table_busy_${DateTime.now().millisecondsSinceEpoch}',
        title: "⚠️ Stol allaqachon band!",
        body: e.message,
        time: DateTime.now(),
        type: 'table_busy',
      ));
    } catch (e) {
      debugPrint('_saveCartRemoteOnly xatoligi: $e');
    }
  }


  /// Stol holati va savatni saqlaydi (to'liq saveData() dan yengil).
  Future<void> _saveCartAndTablesOnly() async {
    await _saveCartLocalOnly();
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
        'tables',
        jsonEncode(tables.map((e) => e.toJson()).toList()),
      );
    } catch (e) {
      debugPrint('_saveCartAndTablesOnly xatoligi: $e');
    }
  }

  // ---- JOY / STOLLARNI BOSHQARISH METODLARI (SETTINGS UCHUN) ----

  Future<void> addTableToHall({
    required int hallId,
    required int number,
    int seats = 4,
  }) async {
    final newTable = TableModel(
      id: nextId(),
      hallId: hallId,
      number: number,
      seats: seats,
      status: TableStatus.free,
    );
    tables.add(newTable);
    _deduplicateHallsAndTables();
    await saveData();
    notifyListeners();

    try {
      final cloudTable = await _cloudService.createTable(
        cafeId: currentCafeId,
        hallId: hallId,
        number: number,
        seats: seats,
      );
      if (cloudTable != null) {
        final idx = tables.indexWhere((t) => t.id == newTable.id);
        if (idx != -1) {
          tables[idx] = cloudTable;
          await saveData();
          notifyListeners();
        }
      }
    } catch (e) {
      debugPrint('addTableToHall cloud xatoligi: $e');
    }
  }

  Future<void> updateTableDetails({
    required int tableId,
    required int number,
    int seats = 4,
  }) async {
    final idx = tables.indexWhere((t) => t.id == tableId);
    if (idx != -1) {
      tables[idx].number = number;
      tables[idx].seats = seats;
      await saveData();
      notifyListeners();

      try {
        await _cloudService.updateTable(
          cafeId: currentCafeId,
          tableId: tableId,
          number: number,
          seats: seats,
        );
      } catch (e) {
        debugPrint('updateTableDetails cloud xatoligi: $e');
      }
    }
  }

  Future<bool> deleteTableById({
    required int tableId,
    bool force = false,
  }) async {
    final hasOrder = hasActiveOrder(tableId);
    if (hasOrder && !force) {
      return false;
    }

    tables.removeWhere((t) => t.id == tableId);
    tableOrders.remove(tableId);
    tableNotes.remove(tableId);
    if (selectedTable?.id == tableId) {
      selectedTable = null;
      cart.clear();
    }
    await saveData();
    notifyListeners();

    try {
      await _cloudService.deleteTable(
        cafeId: currentCafeId,
        tableId: tableId,
        force: force,
      );
    } catch (e) {
      debugPrint('deleteTableById cloud xatoligi: $e');
    }
    return true;
  }

  Future<Hall> addHall(String name, [IconData icon = Icons.meeting_room_outlined]) async {
    final hall = Hall(id: nextId(), name: name, icon: icon);
    halls.add(hall);
    await saveData();
    notifyListeners();

    try {
      final cloudHall = await _cloudService.saveHall(
        currentCafeId,
        name: name,
        iconCodePoint: icon.codePoint,
      );
      if (cloudHall != null) {
        final idx = halls.indexWhere((h) => h.id == hall.id);
        if (idx != -1) {
          final oldId = hall.id;
          final newId = cloudHall.id;
          halls[idx] = cloudHall;
          for (final t in tables) {
            if (t.hallId == oldId) {
              t.hallId = newId;
            }
          }
          await saveData();
          notifyListeners();
          return cloudHall;
        }
      }
    } catch (e) {
      debugPrint('addHall cloud xatoligi: $e');
    }

    return hall;
  }

  Future<void> deleteHall(int hallId) async {
    halls.removeWhere((h) => h.id == hallId);
    final toRemove = tables.where((t) => t.hallId == hallId).map((t) => t.id).toSet();
    tables.removeWhere((t) => t.hallId == hallId);
    for (final tid in toRemove) {
      tableOrders.remove(tid);
      tableNotes.remove(tid);
      if (selectedTable?.id == tid) {
        selectedTable = null;
        cart.clear();
      }
    }
    if (selectedHall?.id == hallId) {
      selectedHall = halls.isNotEmpty ? halls.first : null;
    }
    await saveData();
    notifyListeners();

    try {
      await _cloudService.deleteHall(currentCafeId, hallId);
    } catch (e) {
      debugPrint('deleteHall cloud xatoligi: $e');
    }
  }

  Future<void> clearAllTables() async {
    tables.clear();
    tableOrders.clear();
    tableOrdersByZone.clear();
    tableNotes.clear();
    tableNotesByZone.clear();
    selectedTable = null;
    cart.clear();
    await saveData();
    notifyListeners();

    try {
      await _cloudService.clearAllTables(currentCafeId);
    } catch (e) {
      debugPrint('clearAllTables error: $e');
    }
  }

  Future<void> clearHallTables(int hallId) async {
    final toRemove = tables.where((t) => t.hallId == hallId).map((t) => t.id).toSet();
    tables.removeWhere((t) => t.hallId == hallId);
    for (final tid in toRemove) {
      tableOrders.remove(tid);
      tableNotes.remove(tid);
      if (selectedTable?.id == tid) {
        selectedTable = null;
        cart.clear();
      }
    }
    await saveData();
    notifyListeners();

    try {
      await _cloudService.clearHallTables(currentCafeId, hallId);
    } catch (e) {
      debugPrint('clearHallTables error: $e');
    }
  }

  void setTableNote(String note) {
    if (selectedTable != null) {
      tableNotes[selectedTable!.id] = note;
      saveData();
      notifyListeners();
    }
  }

  String get selectedTableNote =>
      selectedTable != null ? (tableNotes[selectedTable!.id] ?? '') : '';

  double tableOrderTotal(TableModel t) {
    return (tableOrders[t.id] ?? const []).fold(0.0, (s, i) => s + i.total);
  }

  void addToCart(Product p) {
    _lastLocalCartUserMutationTime = DateTime.now();
    if (selectedTable != null) {
      _tableOrderMutationTimes[selectedTable!.id] = DateTime.now().millisecondsSinceEpoch;
    }
    final existing = cart.where((c) => c.product.id == p.id);
    if (existing.isNotEmpty) {
      existing.first.qty++;
    } else {
      cart.add(CartItem(product: p));
    }
    _syncCartToTable();
    notifyListeners();
  }

  void changeQty(CartItem item, int delta) {
    _lastLocalCartUserMutationTime = DateTime.now();
    if (selectedTable != null) {
      _tableOrderMutationTimes[selectedTable!.id] = DateTime.now().millisecondsSinceEpoch;
    }
    if (delta < 0) {
      if (item.qty <= 1) {
        cart.remove(item);
      } else {
        item.qty--;
      }
    } else {
      item.qty += delta;
    }
    _syncCartToTable();
    notifyListeners();
  }

  void removeFromCart(CartItem item) {
    _lastLocalCartUserMutationTime = DateTime.now();
    if (selectedTable != null) {
      _tableOrderMutationTimes[selectedTable!.id] = DateTime.now().millisecondsSinceEpoch;
    }
    cart.remove(item);
    _syncCartToTable();
    notifyListeners();
  }

  void setNote(CartItem item, String note) {
    _lastLocalCartUserMutationTime = DateTime.now();
    if (selectedTable != null) {
      _tableOrderMutationTimes[selectedTable!.id] = DateTime.now().millisecondsSinceEpoch;
    }
    item.note = note;
    _syncCartToTable();
    notifyListeners();
  }

  double get cartTotal => cart.fold(0, (sum, item) => sum + item.total);

  void clearCart() {
    _lastLocalCartUserMutationTime = DateTime.now();
    if (selectedTable != null) {
      _tableOrderMutationTimes[selectedTable!.id] = DateTime.now().millisecondsSinceEpoch;
    }
    cart.clear();
    _syncCartToTable();
    notifyListeners();
  }


  /// "TO'LOVGA O'TISH" bosilganda: buyurtmani saqlaydi va to'lov ekraniga ruxsat beradi.
  /// Stol holati `_syncCartToTable` orqali aktiv buyurtmaga bog'langan.
  Future<bool> proceedToPayment() async {
    if (cart.isEmpty || proceedingToPayment) return false;

    proceedingToPayment = true;
    notifyListeners();

    try {
      if (selectedTable != null) {
        _syncCartToTable();
        if (selectedTableNote.isNotEmpty) {
          tableNotes[selectedTable!.id] = selectedTableNote;
        }

        try {
          await _cloudService
              .lockTableForCheckout(
                cafeId: currentCafeId,
                tableId: selectedTable!.id,
                items: cart,
                note: selectedTableNote,
              )
              .timeout(const Duration(seconds: 5));
        } catch (e) {
          debugPrint('proceedToPayment cloud xatoligi (offline rejim): $e');
        }

        _cartSaveTimer?.cancel();
        await _saveCartAndTablesOnly();
        notifyListeners();
      }
      return true;
    } finally {
      proceedingToPayment = false;
      notifyListeners();
    }
  }

  /// Stolni bo'shatish va buyurtmani bekor qilish.
  Future<void> releaseCurrentTable() async {
    if (selectedTable == null) return;
    final table = selectedTable!;
    final tId = table.id;
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    _tableVersions[tId] = nowMs;
    _tableOrderMutationTimes[tId] = nowMs;
    cart.clear();
    tableOrders.remove(tId);
    tableOrdersByZone.remove(table.tableKey);
    tableNotes.remove(tId);
    tableNotesByZone.remove(table.tableKey);
    table.status = TableStatus.free;
    unawaited(OfflineSyncService().removeActionsForTable(tId, cafeId: currentCafeId));
    await _persistTableStatus(tId, false);
    selectedTable = null;
    _debounceNotifyTables();
  }

  Future<Receipt> checkout({
    required PaymentMethod method,
    double cashPaid = 0,
    double cardPaid = 0,
    String? idempotencyKey,
    String printStatus = 'unprinted',
    DateTime? printedAt,
  }) async {
    final r = Receipt(
      id: nextId(),
      date: DateTime.now(),
      items: List<CartItem>.from(
        cart.map((c) => CartItem(product: c.product, qty: c.qty, note: c.note)),
      ),
      total: cartTotal,
      method: method,
      cashierName: currentUser?.name ?? guestName ?? 'Mehmon',
      waiterId: currentUser?.id,
      waiterName: currentUser?.name ?? guestName ?? 'Ofitsiant',
      tableId: selectedTable?.id,
      tableNumber: selectedTable?.number,
      hallId: selectedHall?.id ?? selectedTable?.hallId,
      hallName: selectedHall?.name,
      cashPaid: cashPaid,
      cardPaid: cardPaid,
      printStatus: printStatus,
      printedAt: printedAt,
    );
    receipts.insert(0, r);

    // Optimistik hisobot yangilanishi: 0 millisekundda Jami Daromad va Jami Buyurtmalar ko'tariladi
    final rCash = (r.method == PaymentMethod.cash)
        ? r.total.round()
        : (r.cashPaid.round());
    final rCard = (r.method == PaymentMethod.card)
        ? r.total.round()
        : (r.cardPaid.round());
    final currentRep = liveTodayReport;
    if (currentRep != null) {
      final newRev = currentRep.totalRevenue + r.total.round();
      final newOrders = currentRep.orderCount + 1;
      final newCash = currentRep.cashTotal + rCash;
      final newCard = currentRep.cardTotal + rCard;
      final newAvg = newOrders > 0 ? (newRev / newOrders).round() : 0;
      liveTodayReport = TodayReportSummary(
        totalRevenue: newRev,
        orderCount: newOrders,
        cashTotal: newCash,
        cardTotal: newCard,
        averageCheck: newAvg,
        waiters: currentRep.waiters,
        topProducts: currentRep.topProducts,
        updatedAt: DateTime.now(),
      );
    } else {
      liveTodayReport = TodayReportSummary(
        totalRevenue: r.total.round(),
        orderCount: 1,
        cashTotal: rCash,
        cardTotal: rCard,
        averageCheck: r.total.round(),
        waiters: const [],
        topProducts: const [],
        updatedAt: DateTime.now(),
      );
    }

    final rPlace = r.tableNumber != null
        ? (r.hallName != null && r.hallName!.isNotEmpty ? '${r.hallName} - Stol ${r.tableNumber}' : 'Stol ${r.tableNumber}')
        : (r.hallName ?? 'Kassa');
    addAppNotification(AppNotificationItem(
      id: 'receipt_${r.id}',
      title: "Chek to'landi #${r.id}",
      body: "${formatSum(r.total)} so'm • ${r.method == PaymentMethod.card ? 'Karta' : 'Naqd'} ($rPlace)",
      time: DateTime.now(),
      type: 'receipt',
    ));

    final tableIdToRelease = selectedTable?.id;
    final tableNumToRelease = selectedTable?.number;
    final tableHallIdToRelease = selectedTable?.hallId;
    final nowMs = DateTime.now().millisecondsSinceEpoch;

    // 1. Zudlik bilan xotiradagi mutatsiya vaqtini yangilaymiz (socket orqali kelishi mumkin bo'lgan eski buyurtma stolni qayta band qilmasligi uchun)
    if (tableIdToRelease != null) {
      _tableOrderMutationTimes[tableIdToRelease] = nowMs;
      _tableVersions[tableIdToRelease] = nowMs;
      tableOrders.remove(tableIdToRelease);
      tableNotes.remove(tableIdToRelease);
      unawaited(OfflineSyncService().removeActionsForTable(tableIdToRelease, cafeId: currentCafeId));
      if (selectedTable != null) {
        tableOrdersByZone.remove(selectedTable!.tableKey);
        tableNotesByZone.remove(selectedTable!.tableKey);
      }
    }

    // 2. Stolni xotirada darhol bo'shatamiz
    for (var i = 0; i < tables.length; i++) {
      final matches = (tableIdToRelease != null && tables[i].id == tableIdToRelease) ||
          (tableIdToRelease == null && tableNumToRelease != null && tableHallIdToRelease != null &&
           tables[i].number == tableNumToRelease && tables[i].hallId == tableHallIdToRelease);
      if (matches) {
        tables[i].status = TableStatus.free;
        tableOrders.remove(tables[i].id);
        tableOrdersByZone.remove(tables[i].tableKey);
        tableNotes.remove(tables[i].id);
        tableNotesByZone.remove(tables[i].tableKey);
        _tableOrderMutationTimes[tables[i].id] = nowMs;
        unawaited(_persistTableStatus(tables[i].id, false));
      }
    }
    if (tableIdToRelease != null) {
      tableOrders.remove(tableIdToRelease);
      tableNotes.remove(tableIdToRelease);
      if (selectedTable != null) {
        tableOrdersByZone.remove(selectedTable!.tableKey);
        tableNotesByZone.remove(selectedTable!.tableKey);
      }
    }

    try {
      final cached = await LocalCacheService().getCachedMap('cache_table_orders_$currentCafeId');
      if (cached != null) {
        if (tableIdToRelease != null) cached.remove('$tableIdToRelease');
        for (final t in tables) {
          if (t.status == TableStatus.free) cached.remove('${t.id}');
        }
        await LocalCacheService().setCachedMap('cache_table_orders_$currentCafeId', cached);
      }
    } catch (_) {}

    if (selectedTable != null) {
      selectedTable!.status = TableStatus.free;
    }
    selectedTable = null;
    cart.clear();
    try {
      notifyListeners();
    } catch (e) {
      debugPrint('⚠️ [checkout] notifyListeners transient notice: $e');
    }

    // 3. Offline-first navbatga darhol yozamiz va diskka saqlaymiz (zero data-loss kafolati)
    final effIdemKey = idempotencyKey ??
        'rcpt_${r.id}_${nowMs}_${tableIdToRelease ?? tableNumToRelease ?? 0}';
    await OfflineSyncService().queueCheckout(
      cafeId: currentCafeId,
      receipt: r,
      tableId: tableIdToRelease,
      items: List<CartItem>.from(r.items),
      idempotencyKey: effIdemKey,
    );

    if (liveTodayReport != null) {
      unawaited(LocalCacheService().setCachedMap(
        'cache_today_report_$currentCafeId',
        liveTodayReport!.toJson(),
      ));
    }

    try {
      await _cloudService.completeCheckout(
        cafeId: currentCafeId,
        receipt: r,
        tableId: tableIdToRelease,
        items: List<CartItem>.from(r.items),
        allProducts: products,
        ownerId: '',
        idempotencyKey: effIdemKey,
      );
      // Serverga yetib bordi, navbatdan o'chiramiz
      await OfflineSyncService().removeCheckoutByReceiptId(r.id);
      unawaited(fetchLiveTodayReport());
    } catch (e) {
      debugPrint('ℹ️ [Checkout] Server oflayn yoki uxlab qolgan, buyurtma mahalliy navbatda saqlandi: $e');
    }

    // 4. Lokal ma'lumotlar bazasini saqlaymiz
    await saveData();
    try {
      notifyListeners();
    } catch (e) {
      debugPrint('⚠️ [checkout] final notifyListeners notice: $e');
    }
    return r;
  }

  // ---------------- MIJOZ SAVATI VA ONLINE ZAKAS ----------------
  void addToCustomerCart(Product p) {
    final existing = customerCart.where((c) => c.product.id == p.id);
    if (existing.isNotEmpty) {
      existing.first.qty++;
    } else {
      customerCart.add(CartItem(product: p));
    }
    notifyListeners();
  }

  void changeCustomerQty(CartItem item, int delta) {
    item.qty += delta;
    if (item.qty <= 0) customerCart.remove(item);
    notifyListeners();
  }

  void removeFromCustomerCart(CartItem item) {
    customerCart.remove(item);
    notifyListeners();
  }

  double get customerCartTotal =>
      customerCart.fold(0, (sum, item) => sum + item.total);

  void clearCustomerCart() {
    customerCart.clear();
    notifyListeners();
  }

  CustomerOrder placeCustomerOrder({
    required String name,
    required String phone,
    required OrderType type,
    int? tableNumber,
    int? hallId,
    String? deliveryAddress,
  }) {
    final order = CustomerOrder(
      id: nextId(),
      date: DateTime.now(),
      items: List<CartItem>.from(
        customerCart.map(
          (c) => CartItem(product: c.product, qty: c.qty, note: c.note),
        ),
      ),
      customerName: name.isEmpty ? (guestName ?? 'Mehmon') : name,
      phone: phone,
      type: type,
      tableNumber: tableNumber,
      hallId: hallId,
      deliveryAddress: deliveryAddress,
    );
    customerOrders.insert(0, order);
    customerCart.clear();
    _cloudService.saveCustomerOrder(currentCafeId, order);
    saveData();
    notifyListeners();
    return order;
  }

  Future<void> forceRefreshCustomerOrders() async {
    // SMS / bildirishnomalar va buyurtmalar faqat ofitsiant paneliga kelishi kerak
    if (currentUser == null || currentUser?.role != UserRole.waiter) return;
    try {
      final res = await ApiClient().get('/customer-orders');
      if (res['customerOrders'] is List) {
        final list = (res['customerOrders'] as List)
            .map((e) => CustomerOrder.fromJson(Map<String, dynamic>.from(e as Map)))
            .toList();
        _handleIncomingCustomerOrders(list);
      }
    } catch (_) {}
  }

  void _handleIncomingCustomerOrders(List<CustomerOrder> newOrders) {
    // FAQAT ofitsiant paneliga SMS / pop-up / audio xabarlari kelishi kerak (Admin/Kafe paneliga kelmasin):
    if (currentUser?.role != UserRole.waiter) {
      return;
    }

    for (final o in newOrders) {
      // 2. Faqat o'sha QR menyusi skaner qilingan kafe paneliga (currentCafeId) xabar borishi kerak:
      if (o.cafeId != null && o.cafeId!.isNotEmpty && o.cafeId != currentCafeId) {
        continue;
      }

      if (o.status == OrderStatus.pending && !_notifiedOrderIds.contains(o.id)) {
        _notifiedOrderIds.add(o.id);
        addAppNotification(AppNotificationItem(
          id: 'order_${o.id}',
          title: "Yangi buyurtma #${o.id}",
          body: "${o.tableNumber != null ? '${o.tableNumber}-stol: ' : ''}${o.items.map((e) => '${e.product.name} x${e.qty}').join(', ')}",
          time: DateTime.now(),
          type: 'order',
        ));
        InAppNotificationService().showNewOrderNotification(
          order: o,
          onAcceptOrder: () {
            updateOrderStatus(o, OrderStatus.preparing);
          },
          onViewOrder: () {
            appNavigatorKey.currentState?.push(
              MaterialPageRoute(builder: (_) => const CustomerOrdersScreen()),
            );
          },
        );
      }
    }
    customerOrders
      ..clear()
      ..addAll(newOrders);
    notifyListeners();
  }

  void updateOrderStatus(CustomerOrder order, OrderStatus status) {
    order.status = status;
    // Buyurtma qabul qilinganda yoki holati o'zgarganda takroriy ovoz to'xtatiladi
    SoundService().stopOrderVoice(order.id);
    _cloudService.updateCustomerOrderStatus(currentCafeId, order.id, status);
    saveData();
    notifyListeners();
  }

  Future<void> deleteCustomerOrder(CustomerOrder order) async {
    customerOrders.removeWhere((o) => o.id == order.id);
    _notifiedOrderIds.remove(order.id);
    SoundService().stopOrderVoice(order.id);
    saveData();
    notifyListeners();
    try {
      await ApiClient().delete('/customer-orders/${order.id}');
    } catch (e) {
      debugPrint('deleteCustomerOrder error: $e');
    }
  }

  Future<void> clearCompletedCustomerOrders() async {
    customerOrders.removeWhere((o) =>
        o.status == OrderStatus.completed ||
        o.status == OrderStatus.cancelled ||
        o.status == OrderStatus.delivered);
    saveData();
    notifyListeners();
    try {
      await ApiClient().post('/customer-orders/clear-completed');
    } catch (e) {
      debugPrint('clearCompletedCustomerOrders error: $e');
    }
  }

