  List<Product> _deduplicateProducts(List<Product> list) {
    final seenIds = <int>{};
    final result = <Product>[];
    for (final p in list) {
      if (seenIds.contains(p.id)) continue;
      seenIds.add(p.id);
      result.add(p);
    }
    return result;
  }

  Future<void> addOrUpdateProduct(Product p, {String? originalName}) async {
    final normName = p.name.trim().toLowerCase();
    final normOrigName = originalName?.trim().toLowerCase();
    final idx = products.indexWhere(
      (e) =>
          (p.id > 0 && e.id == p.id) ||
          e.name.trim().toLowerCase() == normName ||
          (normOrigName != null && e.name.trim().toLowerCase() == normOrigName),
    );
    if (idx != -1) {
      products[idx] = Product(
        id: products[idx].id,
        name: p.name.trim(),
        price: p.price,
        categoryId: p.categoryId,
        stock: p.stock,
        icon: p.icon,
        imageUrl: p.imageUrl,
      );
    } else {
      final tempId = p.id > 0 ? p.id : nextId();
      products.add(Product(
        id: tempId,
        name: p.name.trim(),
        price: p.price,
        categoryId: p.categoryId,
        stock: p.stock,
        icon: p.icon,
        imageUrl: p.imageUrl,
      ));
    }
    saveData();
    notifyListeners();

    try {
      final savedProduct = await _cloudService.saveProduct(
        currentCafeId,
        p,
        originalName: originalName,
      );
      if (savedProduct != null) {
        final savedIdx = products.indexWhere(
          (e) =>
              e.id == p.id ||
              e.id == savedProduct.id ||
              e.name.trim().toLowerCase() == savedProduct.name.trim().toLowerCase() ||
              (normOrigName != null && e.name.trim().toLowerCase() == normOrigName),
        );
        if (savedIdx != -1) {
          products[savedIdx] = savedProduct;
        } else {
          products.add(savedProduct);
        }
        final deduped = _deduplicateProducts(products);
        products
          ..clear()
          ..addAll(deduped);
        saveData();
        notifyListeners();
      }
    } catch (e) {
      debugPrint('addOrUpdateProduct cloud error: $e');
    }
  }

  Future<bool> deleteProduct(Product p) async {
    try {
      // 1. Avval backend bazasidan to'liq o'chirish (Hard Delete)
      await _cloudService.deleteProduct(currentCafeId, p.id, productName: p.name);

      // 2. Faqat backend muvaffaqiyatli javob bergandagina ro'yxatdan va keshdan o'chirish
      final normName = p.name.trim().toLowerCase();
      products.removeWhere(
        (e) =>
            e.id == p.id ||
            (e.name.trim().toLowerCase() == normName &&
                e.categoryId == p.categoryId),
      );
      await saveData();
      notifyListeners();
      return true;
    } catch (e) {
      debugPrint('deleteProduct backend xatosi: $e');
      rethrow;
    }
  }

  Future<bool> deleteProductsBulk(List<int> productIds) async {
    try {
      // 1. Avval backend bazasidan to'liq o'chirish (Hard Delete)
      await _cloudService.deleteProductsBulk(currentCafeId, productIds);

      // 2. Faqat backend muvaffaqiyatli javob bergandagina ro'yxatdan va keshdan o'chirish
      products.removeWhere((e) => productIds.contains(e.id));
      await saveData();
      notifyListeners();
      return true;
    } catch (e) {
      debugPrint('deleteProductsBulk backend xatosi: $e');
      rethrow;
    }
  }

