// ============================================================
// TARMOQ (Wi-Fi / LAN) PRINTERGA ULANISH — ESC/POS PROTOKOLI
// ============================================================
//
// Bu bo'lim restoran/kassada ko'p ishlatiladigan tarmoqli (Wi-Fi yoki LAN
// kabel bilan ulanadigan) termal cheklar printeriga TO'G'RIDAN-TO'G'RI,
// hech qanday qo'shimcha paket o'rnatmasdan (faqat dart:io Socket orqali)
// ulanish va chek chiqarish uchun yozilgan.
//
// MUHIM — LOTINCHA/KIRILLCHA (O'ZBEKCHA) MATNLARNING TO'G'RI CHIQISHI:
// Ko'pchilik arzon termal (ESC/POS) printerlar UTF-8'ni tushunmaydi —
// ular faqat bitta-baytli "code page" (masalan CP866 — kirillcha uchun
// eng keng tarqalgan code page) orqali ishlaydi. Shuning uchun avval
// printerga "ESC t 17" buyrug'i bilan CP866 code page tanlanadi, so'ngra
// har bir belgi shu code page bo'yicha bitta baytga aylantirilib
// yuboriladi (_Cp866.encode). Lotin harflari (a-z, A-Z, raqamlar,
// apostrof) CP866'da ham oddiy ASCII bilan bir xil bo'lgani uchun ular
// har doim to'g'ri chiqadi; kirillcha harflar esa maxsus jadval bo'yicha
// mos baytga almashtiriladi.
//
// Printerning IP-manzilini bilish uchun odatda:
//  - printerning o'zidagi "Self test" / tarmoq sozlamalari chekini
//    chiqarish (printerni yoqib turib FEED tugmasini bosib turish),
//  - yoki router (masalan TP-Link, Wi-Fi router) sozlamalaridagi
//    "ulangan qurilmalar" ro'yxatidan foydalanish mumkin.
//
// Bu bo'lim 3 xil chek chiqaradi (pastdagi PDF versiyalari bilan bir xil
// ma'lumotlarni oladi):
//   1) printReceiptNetwork      -> to'langan chek (mijozga)
//   2) printBillNetwork         -> hali to'lanmagan hisob (stol uchun)
//   3) printKitchenTicketNetwork-> oshxona/oshpaz cheki (narxsiz)
// ============================================================

/// Printerga ulanish uchun sozlamalar (IP-manzil, port, qog'oz kengligi).
class PrinterConnectionSettings {
  final String ip;
  final int port;
  final int charsPerLine; // 32 -> 58mm qog'oz, 48 -> 80mm qog'oz

  const PrinterConnectionSettings({
    required this.ip,
    this.port = 9100,
    this.charsPerLine = 48,
  });
}

/// Xato holatida chiqariladigan maxsus exception — ekranda tushunarli
/// xabar ko'rsatish uchun.
class PrinterConnectionException implements Exception {
  final String message;
  PrinterConnectionException(this.message);
  @override
  String toString() => message;
}

// ---- KIRILLCHA (O'ZBEKCHA/RUSCHA) HARFLARNI CP866 BAYTLARIGA
// AYLANTIRISH — termal printer to'g'ri kirillcha chiqarishi uchun ----
class _Cp866 {
  static List<int> encode(String s) {
    final bytes = <int>[];
    for (final rune in s.runes) {
      bytes.add(_byteFor(rune));
    }
    return bytes;
  }

  static int _byteFor(int rune) {
    // Lotin harflari, raqamlar, tinish belgilari — ASCII bilan bir xil
    if (rune < 0x80) return rune;

    // Katta harflar А-Я (U+0410 - U+042F) -> 0x80-0x9F
    if (rune >= 0x0410 && rune <= 0x042F) return 0x80 + (rune - 0x0410);
    // Kichik harflar а-п (U+0430 - U+043F) -> 0xA0-0xAF
    if (rune >= 0x0430 && rune <= 0x043F) return 0xA0 + (rune - 0x0430);
    // Kichik harflar р-я (U+0440 - U+044F) -> 0xE0-0xEF
    if (rune >= 0x0440 && rune <= 0x044F) return 0xE0 + (rune - 0x0440);
    // Ё / ё
    if (rune == 0x0401) return 0xF0;
    if (rune == 0x0451) return 0xF1;

    // O'zbekcha kirill harflari CP866 jadvalida yo'q — eng yaqin
    // ko'rinishdagi harf bilan almashtiramiz (butunlay yo'qolib
    // ketmasligi uchun)
    switch (rune) {
      case 0x040E: // Ў
        return 0x93; // У
      case 0x045E: // ў
        return 0xE3; // у
      case 0x049A: // Қ
        return 0x8A; // К
      case 0x049B: // қ
        return 0xAA; // к
      case 0x0492: // Ғ
        return 0x83; // Г
      case 0x0493: // ғ
        return 0xA3; // г
      case 0x04B2: // Ҳ
        return 0x95; // Х
      case 0x04B3: // ҳ
        return 0xE5; // х
    }

    // Lotincha o'zbekcha tutuq belgisi (oʻ, gʻ) turli xil unicode
    // ko'rinishlarda kelishi mumkin — barchasini oddiy apostrofga
    // almashtiramiz
    if (rune == 0x02BB || rune == 0x02BC || rune == 0x2018 || rune == 0x2019) {
      return 0x27; // '
    }
    if (rune == 0x2013 || rune == 0x2014) return 0x2D; // – — -> -
    if (rune == 0x201C || rune == 0x201D) return 0x22; // “ ” -> "

    // Tanilmagan belgi
    return 0x3F; // ?
  }
}

// ---- ESC/POS BUYRUQLARI (termal printerlar tushunadigan xom baytlar) ----
class _Esc {
  static const List<int> init = [0x1B, 0x40]; // ESC @  -> printerni tozalash
  // ESC t 17 -> CP866 (kirillcha) code page'ni tanlash
  static const List<int> codepageCp866 = [0x1B, 0x74, 17];
  static const List<int> alignLeft = [0x1B, 0x61, 0x00];
  static const List<int> alignCenter = [0x1B, 0x61, 0x01];
  // ignore: unused_field
  static const List<int> alignRight = [0x1B, 0x61, 0x02];
  static const List<int> boldOn = [0x1B, 0x45, 0x01];
  static const List<int> boldOff = [0x1B, 0x45, 0x00];
  static const List<int> doubleOn = [0x1D, 0x21, 0x11]; // 2x katta shrift
  // ignore: unused_field
  static const List<int> doubleHeightOn = [0x1D, 0x21, 0x01];
  static const List<int> normalSize = [0x1D, 0x21, 0x00];
  // ignore: unused_field
  static const List<int> underlineOn = [0x1B, 0x2D, 0x01];
  // ignore: unused_field
  static const List<int> underlineOff = [0x1B, 0x2D, 0x00];
  // ESC M 0/1 -> shrift turini tanlash: Font A (standart, kattaroq) yoki
  // Font B (odatda ~20-25% kichikroq) — "Kichik" o'lcham shu bilan olinadi.
  static const List<int> fontA = [0x1B, 0x4D, 0x00];
  static const List<int> fontB = [0x1B, 0x4D, 0x01];
  // ESC 3 n -> qatorlar orasidagi masofani (line spacing) n nuqtaga
  // o'rnatadi. Standart printer sozlamasi odatda juda keng (~30-40 nuqta)
  // bo'lganligi uchun chek "bo'sh joy ko'p" bo'lib chiqadi; buni kichikroq
  // songa o'rnatib, qatorlarni bir-biriga yaqinlashtiramiz.
  static List<int> lineSpacing(int dots) => [0x1B, 0x33, dots];
  // ESC 2 -> printerning standart (zavod) qator oralig'iga qaytarish.
  static const List<int> lineSpacingDefault = [0x1B, 0x32];
  static List<int> feed(int lines) => [0x1B, 0x64, lines];
  static const List<int> cut = [0x1D, 0x56, 0x01]; // qog'ozni qisman kesish
  // Kassa qutisini ochish signali (agar printerga ulangan bo'lsa)
  static const List<int> openDrawer = [0x1B, 0x70, 0x00, 0x19, 0xFA];
}

class NetworkPrinterService {
  NetworkPrinterService._();

  /// Baytlarni printerning IP-manzili va porti orqali (xom TCP socket
  /// bilan) yuboradi. Bu — printerga "ulanish"ning o'zi shu yerda sodir
  /// bo'ladi: Socket.connect(ip, port) chaqirilganda qurilma printer
  /// bilan tarmoq orqali bog'lanadi.
  static Future<void> _sendRaw(
    List<int> bytes, {
    required String ip,
    required int port,
    Duration timeout = const Duration(seconds: 6),
  }) async {
    if (ip.trim().isEmpty) {
      throw PrinterConnectionException(
        'Printer IP-manzili kiritilmagan. Sozlamalar -> Printer bo\'limida '
        'IP-manzilni kiriting.',
      );
    }
    Socket? socket;
    try {
      socket = await Socket.connect(ip.trim(), port, timeout: timeout);
      socket.add(bytes);
      await socket.flush();
      // Printer baytlarni qabul qilib ulgurishi uchun kichik pauza
      await Future.delayed(const Duration(milliseconds: 150));
    } on SocketException catch (e) {
      throw PrinterConnectionException(
        'Printerga ulanib bo\'lmadi ($ip:$port). Printer yoqilganligini, '
        'bir xil Wi-Fi tarmog\'ida ekanligini va IP-manzil to\'g\'riligini '
        'tekshiring.\n\nTexnik xato: ${e.osError?.message ?? e.message}',
      );
    } catch (e) {
      throw PrinterConnectionException('Chop etishda kutilmagan xatolik: $e');
    } finally {
      try {
        await socket?.close();
      } catch (_) {
        // socket allaqachon yopilgan bo'lishi mumkin — e'tiborsiz qoldiramiz
      }
    }
  }

  // Matnni printer tushunadigan CP866 baytlariga aylantiradi (kirillcha
  // va lotincha o'zbekcha matnlar to'g'ri chiqishi uchun)
  static List<int> _t(String s) => _Cp866.encode(s);

  /// Chapga va o'ngga tekislangan ikkita matnni bitta qatorga sig'diradi
  /// (masalan "Taom nomi x2 .......... 25 000").
  static List<int> _row(String left, String right, int width) {
    final maxLeft = width - right.length - 1;
    var l = left;
    if (l.length > maxLeft && maxLeft > 3) {
      l = '${l.substring(0, maxLeft - 1)}.';
    }
    final spaces = width - l.length - right.length;
    final gap = spaces > 1 ? ' ' * spaces : ' ';
    return _t('$l$gap$right\n');
  }

  // Rasmdagi chekka o'xshash "punktir" (- - - - -) ko'rinishidagi
  // ajratuvchi chiziq — tutash chiziq emas, dash+bo'sh joy almashinib
  // keladi, xuddi namuna chekdagi kabi.
  static List<int> _divider(int width) {
    final buffer = StringBuffer();
    for (var i = 0; i < width; i++) {
      buffer.write(i.isEven ? '-' : ' ');
    }
    return _t('${buffer.toString()}\n');
  }

  static List<int> _center(String text) => _t('$text\n');

  // ignore: unused_element
  static List<int> _alignFor(ReceiptHeaderAlign align) {
    switch (align) {
      case ReceiptHeaderAlign.left:
        return _Esc.alignLeft;
      case ReceiptHeaderAlign.right:
        return _Esc.alignRight;
      case ReceiptHeaderAlign.center:
        return _Esc.alignCenter;
    }
  }

  // ------------------------------------------------------------
  // JIMGINA ULANISHNI TEKSHIRISH (Chek chop etmasdan soket tekshirish)
  // ------------------------------------------------------------
  static Future<bool> ping({
    required String ip,
    required int port,
    Duration timeout = const Duration(seconds: 2),
  }) async {
    if (ip.trim().isEmpty) return false;
    Socket? socket;
    try {
      socket = await Socket.connect(ip.trim(), port, timeout: timeout);
      return true;
    } catch (_) {
      return false;
    } finally {
      try {
        await socket?.close();
      } catch (_) {}
    }
  }

  // ------------------------------------------------------------
  // ULANISHNI TEKSHIRISH (Sozlamalar ekranidagi "Ulanishni tekshirish")
  // ------------------------------------------------------------
  static Future<void> testConnection({
    required String ip,
    required int port,
    int charsPerLine = 48,
  }) async {
    final w = charsPerLine;
    final bytes = <int>[
      ..._Esc.init,
      ..._Esc.codepageCp866,
      ..._Esc.alignCenter,
      ..._Esc.boldOn,
      ..._Esc.doubleOn,
      ..._t('ULANISH OK\n'),
      ..._Esc.normalSize,
      ..._Esc.boldOff,
      ..._t('${appState.effectiveReceiptName}\n'),
      ..._divider(w),
      ..._Esc.alignLeft,
      ..._t('Printer: $ip:$port\n'),
      ..._t('Sana: ${DateTime.now().toString().substring(0, 16)}\n'),
      ..._Esc.alignCenter,
      ..._t('Test cheki muvaffaqiyatli chiqdi.\n'),
      ..._Esc.lineSpacingDefault,
      ..._Esc.feed(6),
      ..._Esc.cut,
      ..._Esc.feed(1),
    ];

    await _sendRaw(bytes, ip: ip, port: port);
  }

  /// Uchta ustunli qatorni (Menyu / Soni / Summa) bitta chek qatoriga
  /// joylashtiradi — birinchi ustun chapga, ikkinchisi markazga, uchinchisi
  /// o'ngga tekislanadi (namuna chekdagi kabi).
  // ignore: unused_element
  static List<int> _row3(String a, String b, String c, int width) {
    final colB = (width <= 36) ? 7 : 8;
    final colC = (width <= 36) ? 9 : 12;
    final colA = (width - colB - colC - 2).clamp(6, width).toInt();

    String padLeft(String s, int len) {
      if (s.length > len) {
        s = len > 1 ? '${s.substring(0, len - 1)}.' : s.substring(0, len);
      }
      return s + ' ' * (len - s.length);
    }

    String padRight(String s, int len) {
      if (s.length > len) s = s.substring(0, len);
      return ' ' * (len - s.length) + s;
    }

    String padCenter(String s, int len) {
      if (s.length > len) s = s.substring(0, len);
      final totalGap = len - s.length;
      final left = totalGap ~/ 2;
      final right = totalGap - left;
      return ' ' * left + s + ' ' * right;
    }

    final line =
        '${padLeft(a, colA)} ${padCenter(b, colB)} ${padRight(c, colC)}';
    return _t('$line\n');
  }

  /// Tanlangan shrift o'lchamiga mos ESC/POS baytlarini qaytaradi:
  /// - `small`  -> Font B (kichikroq shrift), oddiy (1x) o'lcham
  /// - `normal` -> Font A, oddiy (1x) o'lcham — HAQIQIY standart o'lcham
  /// - `large`  -> Font A, 2x (eni va bo'yi)
  // ignore: unused_element
  static List<int> _fontBytes(PrinterFontSize size) {
    switch (size) {
      case PrinterFontSize.small:
        return [..._Esc.fontB, ..._Esc.normalSize];
      case PrinterFontSize.normal:
        return [..._Esc.fontA, ..._Esc.normalSize];
      case PrinterFontSize.large:
        return [..._Esc.fontA, ..._Esc.doubleOn];
    }
  }

  /// Chekning umumiy qatorlar orasidagi bo'shlig'ini (line-height) tanlangan
  /// shrift o'lchamiga qarab ixchamlashtiradi.
  // ignore: unused_element
  static List<int> _lineSpacingFor(PrinterFontSize size) {
    switch (size) {
      case PrinterFontSize.small:
        return _Esc.lineSpacing(22);
      case PrinterFontSize.normal:
        return _Esc.lineSpacing(26);
      case PrinterFontSize.large:
        return _Esc.lineSpacing(34);
    }
  }

  /// ReceiptWidget va namunaviy chek (Reference Image 2) bilan 100% bir xil
  /// professional ESC/POS baytlarini generatsiya qiluvchi universal metod.
  static List<int> _buildReceiptBytes({
    required String checkId,
    required String cashierName,
    required String? hallName,
    required String? tableNumberStr,
    required String customer,
    required DateTime dateTime,
    required List<CartItem> items,
    required double productsTotal,
    required double serviceTotal,
    required double grandTotal,
    required int charsPerLine,
    required PrinterFontSize fontSize,
  }) {
    final printItems = <ReceiptPrintItem>[];
    for (var i = 0; i < items.length; i++) {
      final item = items[i];
      printItems.add(
        ReceiptPrintItem(
          index: i + 1,
          name: item.product.name,
          qty: item.qty,
          unitPrice: item.product.price,
          lineTotal: item.product.price * item.qty,
          note: item.note,
        ),
      );
    }

    final is58 = charsPerLine <= 36 || appState.paperWidthMm == 58;
    final printData = ReceiptPrintData(
      checkId: checkId,
      dateTime: dateTime,
      cashierName: cashierName.isNotEmpty ? cashierName : (appState.currentUser?.name ?? 'Admin'),
      cafeName: appState.effectiveReceiptName,
      address: appState.restaurantAddress,
      phone: appState.restaurantPhone,
      slogan: appState.receiptSlogan.isNotEmpty ? appState.receiptSlogan : "Yaxshi ta'm • Baxtli onlar",
      footerMessage: appState.receiptFooterNote.isNotEmpty
          ? appState.receiptFooterNote
          : "Bizni tanlaganingiz uchun rahmat!",
      qrUrl: appState.receiptQrEnabled ? appState.effectiveReceiptQrUrl : '',
      tableNumber: tableNumberStr,
      hallName: hallName,
      items: printItems,
      subtotal: productsTotal,
      discount: 0,
      grandTotal: grandTotal,
      paymentMethod: 'cash',
      is58mm: is58,
    );

    return EscPosBuilder.buildReceiptBytes(printData);
  }

  // ------------------------------------------------------------
  // 1) TO'LANGAN CHEK (mijozga beriladigan chek)
  // ------------------------------------------------------------
  static Future<void> printReceiptNetwork(
    Receipt receipt, {
    required String ip,
    required int port,
    int charsPerLine = 48,
    PrinterFontSize fontSize = PrinterFontSize.normal,
    String customer = '1',
  }) async {
    final bytes = _buildReceiptBytes(
      checkId: 'T${receipt.id}',
      cashierName: receipt.cashierName,
      hallName: receipt.hallName,
      tableNumberStr:
          receipt.tableNumber != null ? '${receipt.tableNumber}' : null,
      customer: customer,
      dateTime: receipt.date,
      items: receipt.items,
      productsTotal: receipt.total,
      serviceTotal: 0,
      grandTotal: receipt.total,
      charsPerLine: charsPerLine,
      fontSize: fontSize,
    );

    await _sendRaw(bytes, ip: ip, port: port);
  }

  // ------------------------------------------------------------
  // 2) HALI TO'LANMAGAN HISOB ("Xarid cheki")
  // ------------------------------------------------------------
  static Future<void> printBillNetwork({
    required List<CartItem> items,
    required double productsTotal,
    required double serviceTotal,
    required double grandTotal,
    required PaymentMethod method,
    required String ip,
    required int port,
    TableModel? table,
    String? hallName,
    String? cashierName,
    int charsPerLine = 48,
    PrinterFontSize fontSize = PrinterFontSize.normal,
  }) async {
    final now = DateTime.now();
    final checkId = 'T${table?.number ?? '-'}-${now.millisecondsSinceEpoch}';
    final name = cashierName ??
        appState.currentUser?.name ??
        appState.guestName ??
        'Mehmon';

    final bytes = _buildReceiptBytes(
      checkId: checkId,
      cashierName: name,
      hallName: hallName ?? 'Zal',
      tableNumberStr: table != null ? '${table.number}' : null,
      customer: '1',
      dateTime: now,
      items: items,
      productsTotal: productsTotal,
      serviceTotal: serviceTotal,
      grandTotal: grandTotal,
      charsPerLine: charsPerLine,
      fontSize: fontSize,
    );

    await _sendRaw(bytes, ip: ip, port: port);
  }

  // ------------------------------------------------------------
  // 3) OSHXONA / OSHPAZ CHEKI (narxsiz)
  // ------------------------------------------------------------
  static Future<void> printKitchenTicketNetwork({
    required List<CartItem> items,
    required String ip,
    required int port,
    TableModel? table,
    String? hallName,
    String note = '',
    int charsPerLine = 48,
  }) async {
    final w = charsPerLine;
    final bytes = <int>[..._Esc.init, ..._Esc.codepageCp866];

    bytes
      ..addAll(_Esc.alignCenter)
      ..addAll(_Esc.boldOn)
      ..addAll(_Esc.doubleOn)
      ..addAll(_center('OSHPAZ CHEKI'))
      ..addAll(_Esc.normalSize)
      ..addAll(_Esc.boldOff)
      ..addAll(_divider(w))
      ..addAll(_Esc.alignLeft);

    if (table != null) {
      bytes
        ..addAll(_Esc.boldOn)
        ..addAll(_t('${hallName ?? ''} - Stol ${table.number}\n'))
        ..addAll(_Esc.boldOff);
    }
    bytes
      ..addAll(_t('${DateTime.now().toString().substring(0, 16)}\n'))
      ..addAll(_divider(w));

    for (final item in items) {
      bytes
        ..addAll(_Esc.boldOn)
        ..addAll(_Esc.doubleOn)
        ..addAll(_row(item.product.name, 'x${item.qty}', w ~/ 2))
        ..addAll(_Esc.normalSize)
        ..addAll(_Esc.boldOff);
    }

    if (note.trim().isNotEmpty) {
      bytes
        ..addAll(_divider(w))
        ..addAll(_t('Izoh: $note\n'));
    }

    bytes
      ..addAll(_Esc.lineSpacingDefault)
      ..addAll(_Esc.feed(6))
      ..addAll(_Esc.cut)
      ..addAll(_Esc.feed(1));

    await _sendRaw(bytes, ip: ip, port: port);
  }

  /// Kassa qutisini printer orqali ochish (agar printerga ulangan bo'lsa).
  static Future<void> openCashDrawer({
    required String ip,
    required int port,
  }) async {
    await _sendRaw(_Esc.openDrawer, ip: ip, port: port);
  }
}

// ============================================================
// PRINTING (chek chiqarish — Bluetooth printerlar ham shu orqali
// tizim "Print" oynasida ko'rinadi va tanlanadi)
// ============================================================

bool _isPrintingWindowActive = false;
int _lastPrintWindowTimestamp = 0;

Future<bool> _acquirePrintLock() async {
  final now = DateTime.now().millisecondsSinceEpoch;
  if (_isPrintingWindowActive || (now - _lastPrintWindowTimestamp < 2500)) {
    debugPrint('⚠️ [Chop etish] Chek oynasi allaqachon ochiq yoki bloklangan.');
    return false;
  }
  _isPrintingWindowActive = true;
  _lastPrintWindowTimestamp = now;
  return true;
}

void _releasePrintLock() {
  _isPrintingWindowActive = false;
}

Future<void> printReceipt(Receipt receipt, {bool isAutoCheckout = false}) async {
  final is58mm = appState.paperWidthMm == 58 || appState.printerCharsPerLine <= 32;
  final printData = ReceiptPrintData(
    checkId: '${receipt.id}',
    dateTime: receipt.date,
    cashierName: receipt.cashierName.isNotEmpty ? receipt.cashierName : 'Admin',
    cafeName: appState.effectiveReceiptName.isNotEmpty ? appState.effectiveReceiptName : 'Family Cafe',
    address: appState.restaurantAddress.trim().isNotEmpty ? appState.restaurantAddress.trim() : "Navoi ko'chasi 12, Buxoro",
    phone: appState.restaurantPhone.trim().isNotEmpty ? appState.restaurantPhone.trim() : '+998 90 123 45 67',
    slogan: appState.receiptSlogan.trim().isNotEmpty ? appState.receiptSlogan.trim() : "Yaxshi ta'm • Baxtli onlar",
    footerMessage: appState.receiptFooterNote.trim().isNotEmpty ? appState.receiptFooterNote.trim() : 'Bizni tanlaganingiz uchun rahmat!',
    qrUrl: appState.receiptQrEnabled ? appState.effectiveReceiptQrUrl : '',
    tableNumber: receipt.tableNumber != null ? '${receipt.tableNumber}' : null,
    hallName: receipt.hallName,
    items: receipt.items.asMap().entries.map((e) => ReceiptPrintItem(
      index: e.key + 1,
      name: e.value.product.name,
      qty: e.value.qty,
      unitPrice: e.value.product.price,
      lineTotal: e.value.product.price * e.value.qty,
    )).toList(),
    subtotal: receipt.total,
    discount: 0,
    grandTotal: receipt.total,
    paymentMethod: receipt.method == PaymentMethod.card ? 'card' : 'cash',
    is58mm: is58mm,
  );

  final html = ThermalHtmlGenerator.buildReceiptHtml(
    printData,
    logoUrl: (appState.appLogoUrl != null && appState.appLogoUrl!.trim().isNotEmpty) ? appState.appLogoUrl!.trim() : null,
  );

  // 1. Termal printerga to'g'ridan-to'g'ri (Print Agent yoki mahalliy tarmoq orqali) chiqarish
  bool printedViaDirect = false;
  if (kIsWeb) {
    try {
      final isAgentUp = await PrintAgentService().isAgentRunning();
      if (isAgentUp && appState.printerConfigured) {
        final pngBase64 = await WebReceiptPrinter.renderHtmlToPng(html, widthPx: is58mm ? 384 : 576);
        if (pngBase64 != null && pngBase64.isNotEmpty) {
          final ok = await PrintAgentService().printJob(
            jobId: 'rcpt_${receipt.id}_${DateTime.now().millisecondsSinceEpoch}',
            type: 'xarid',
            printerConfig: {
              'type': appState.printerConnectionType,
              'ip': appState.printerIp,
              'port': appState.printerPort,
              'deviceId': appState.printerConnectionType == 'usb'
                  ? appState.printerUsbName
                  : appState.printerBtName,
              'paperWidth': appState.paperWidthMm,
            },
            imageBase64: pngBase64,
            openDrawer: true,
          );
          if (ok) {
            printedViaDirect = true;
          }
        }
      }
    } catch (e) {
      debugPrint('PrintAgent printReceipt error: $e');
    }
  } else if (!kIsWeb && appState.printerConfigured && appState.printerConnectionType == 'wifi') {
    try {
      await NetworkPrinterService.printReceiptNetwork(
        receipt,
        ip: appState.printerIp,
        port: appState.printerPort,
        charsPerLine: appState.printerCharsPerLine,
        fontSize: appState.printerFontSize,
      );
      printedViaDirect = true;
    } catch (e) {
      debugPrint('NetworkPrinterService printReceipt error: $e');
    }
  }

  if (printedViaDirect) {
    receipt.printStatus = 'printed';
    receipt.printedAt = DateTime.now();
    unawaited(ApiClient().patch('/receipts/${receipt.id}/print-status', body: {
      'printStatus': 'printed',
      'printedAt': receipt.printedAt?.toIso8601String(),
    }).catchError((_) => <String, dynamic>{}));
    appState.notifyChanges();
    showZaveroSnackBar(
      message: "Chek printerdan muvaffaqiyatli chop etildi",
      backgroundColor: const Color(0xFF10B981),
      duration: const Duration(seconds: 2),
      prefixIcon: Icons.check_circle_outline,
    );
    return;
  }

  // 2. Masofaviy / Kassa printeri (Cloud Station Print) tekshiruvi:
  if (!appState.isPrinterStation) {
    final result = await CloudPrintService().dispatchPrintJob(
      id: 'rcpt_${receipt.id}',
      type: 'receipt',
      html: html,
      data: printData.toJson(),
      tableNumber: receipt.tableNumber != null ? '${receipt.tableNumber}' : null,
      hallName: receipt.hallName,
      isAutoCheckout: isAutoCheckout,
    );

    if (result.routedToStation) {
      showZaveroSnackBar(
        message: "Chek kassa printeriga yuborildi va chop etilmoqda",
        backgroundColor: const Color(0xFF10B981),
        duration: const Duration(seconds: 2),
        prefixIcon: Icons.print_outlined,
      );
      return;
    } else {
      if (isAutoCheckout) {
        debugPrint('ℹ️ [Print] Kassa printeri ulanmagan, avtomatik to‘lovda chek bloklanmadi.');
        return;
      } else if (!appState.printerConfigured) {
        showZaveroSnackBar(
          message: "Kassa printeri ulanmagan, chek chop etilmadi",
          backgroundColor: const Color(0xFFDC2626),
          prefixIcon: Icons.print_disabled_outlined,
        );
        return;
      }
    }
  }

  if (!appState.printerConfigured && !appState.isPrinterStation) {
    return;
  }

  // 3. Fallback: Yashirin iframe (Web) yoki Printing PDF (Native)
  if (!await _acquirePrintLock()) return;
  try {
    if (kIsWeb) {
      final ok = await WebReceiptPrinter.printHtml(html);
      if (!ok && !isAutoCheckout) {
        throw Exception('Chop etish oynasini ochib bo\'lmadi');
      }
      return;
    }

    final doc = ThermalPdfGenerator.buildReceiptDoc(printData, is58mm: is58mm);
    final pageFormat = ThermalPdfGenerator.getFormat(printData, is58mm: is58mm);

    await Printing.layoutPdf(
      onLayout: (format) async => doc.save(),
      name: 'chek_${receipt.id}',
      format: pageFormat,
      dynamicLayout: false,
    );
  } finally {
    _releasePrintLock();
  }
}

// ---- XARID CHEKI: hali to'lanmagan, stol hisobini mijozga ko'rsatish/chop etish uchun ----
Future<void> printBillPreview({
  required List<CartItem> items,
  required double productsTotal,
  required double serviceTotal,
  required double grandTotal,
  required PaymentMethod method,
  TableModel? table,
  String? hallName,
}) async {
  final cashierName =
      appState.currentUser?.name ?? appState.guestName ?? 'Admin';

  final now = DateTime.now();
  final checkId = 'T${table?.number ?? 1}-${now.millisecondsSinceEpoch}';
  final is58mm = appState.paperWidthMm == 58 || appState.printerCharsPerLine <= 32;

  final printData = ReceiptPrintData(
    checkId: checkId,
    dateTime: now,
    cashierName: cashierName,
    cafeName: appState.effectiveReceiptName.isNotEmpty ? appState.effectiveReceiptName : 'Family Cafe',
    address: appState.restaurantAddress.trim().isNotEmpty ? appState.restaurantAddress.trim() : "Navoi ko'chasi 12, Buxoro",
    phone: appState.restaurantPhone.trim().isNotEmpty ? appState.restaurantPhone.trim() : '+998 90 123 45 67',
    slogan: appState.receiptSlogan.trim().isNotEmpty ? appState.receiptSlogan.trim() : "Yaxshi ta'm • Baxtli onlar",
    footerMessage: appState.receiptFooterNote.trim().isNotEmpty ? appState.receiptFooterNote.trim() : 'Bizni tanlaganingiz uchun rahmat!',
    qrUrl: appState.receiptQrEnabled ? appState.effectiveReceiptQrUrl : '',
    tableNumber: table != null ? '${table.number}' : null,
    hallName: hallName,
    items: items.asMap().entries.map((e) => ReceiptPrintItem(
      index: e.key + 1,
      name: e.value.product.name,
      qty: e.value.qty,
      unitPrice: e.value.product.price,
      lineTotal: e.value.product.price * e.value.qty,
    )).toList(),
    subtotal: productsTotal,
    discount: (productsTotal - grandTotal) > 0 ? (productsTotal - grandTotal) : 0,
    grandTotal: grandTotal,
    paymentMethod: method == PaymentMethod.card ? 'card' : 'cash',
    is58mm: is58mm,
  );

  final html = ThermalHtmlGenerator.buildReceiptHtml(
    printData,
    logoUrl: (appState.appLogoUrl != null && appState.appLogoUrl!.trim().isNotEmpty) ? appState.appLogoUrl!.trim() : null,
  );

  // 1. Termal printerga to'g'ridan-to'g'ri (Print Agent yoki mahalliy tarmoq orqali) chiqarish
  bool printedViaDirect = false;
  if (kIsWeb) {
    try {
      final isAgentUp = await PrintAgentService().isAgentRunning();
      if (isAgentUp && appState.printerConfigured) {
        final pngBase64 = await WebReceiptPrinter.renderHtmlToPng(html, widthPx: is58mm ? 384 : 576);
        if (pngBase64 != null && pngBase64.isNotEmpty) {
          final ok = await PrintAgentService().printJob(
            jobId: checkId,
            type: 'xarid',
            printerConfig: {
              'type': appState.printerConnectionType,
              'ip': appState.printerIp,
              'port': appState.printerPort,
              'deviceId': appState.printerConnectionType == 'usb'
                  ? appState.printerUsbName
                  : appState.printerBtName,
              'paperWidth': appState.paperWidthMm,
            },
            imageBase64: pngBase64,
          );
          if (ok) {
            printedViaDirect = true;
          }
        }
      }
    } catch (e) {
      debugPrint('PrintAgent printBillPreview error: $e');
    }
  } else if (!kIsWeb && appState.printerConfigured && appState.printerConnectionType == 'wifi') {
    try {
      await NetworkPrinterService.printBillNetwork(
        items: items,
        productsTotal: productsTotal,
        serviceTotal: serviceTotal,
        grandTotal: grandTotal,
        method: method,
        cashierName: cashierName,
        ip: appState.printerIp,
        port: appState.printerPort,
        table: table,
        hallName: hallName,
        charsPerLine: appState.printerCharsPerLine,
        fontSize: appState.printerFontSize,
      );
      printedViaDirect = true;
    } catch (e) {
      debugPrint('NetworkPrinterService printBillNetwork error: $e');
    }
  }

  if (printedViaDirect) {
    showZaveroSnackBar(
      message: "Xarid cheki printerdan chop etildi",
      backgroundColor: const Color(0xFF10B981),
      duration: const Duration(seconds: 2),
      prefixIcon: Icons.check_circle_outline,
    );
    return;
  }

  // 2. Masofaviy / Kassa printeri (Cloud Station Print) tekshiruvi:
  if (!appState.isPrinterStation) {
    final result = await CloudPrintService().dispatchPrintJob(
      id: checkId,
      type: 'bill_preview',
      html: html,
      data: printData.toJson(),
      tableNumber: table != null ? '${table.number}' : null,
      hallName: hallName,
    );

    if (result.routedToStation) {
      showZaveroSnackBar(
        message: "Xarid cheki kassa printeriga yuborildi va chop etilmoqda",
        backgroundColor: const Color(0xFF10B981),
        duration: const Duration(seconds: 2),
        prefixIcon: Icons.print_outlined,
      );
      return;
    } else if (!appState.printerConfigured) {
      showZaveroSnackBar(
        message: "Kassa printeri ulanmagan, chek chop etilmadi",
        backgroundColor: const Color(0xFFDC2626),
        prefixIcon: Icons.print_disabled_outlined,
      );
      return;
    }
  }

  if (!appState.printerConfigured && !appState.isPrinterStation) {
    return;
  }

  // 3. Fallback: Yashirin iframe (Web) yoki Printing PDF (Native)
  if (!await _acquirePrintLock()) return;
  try {
    if (kIsWeb) {
      final ok = await WebReceiptPrinter.printHtml(html);
      if (!ok) {
        throw Exception('Chop etish oynasini ochib bo\'lmadi');
      }
      return;
    }

    final doc = ThermalPdfGenerator.buildReceiptDoc(printData, is58mm: is58mm);
    final pageFormat = ThermalPdfGenerator.getFormat(printData, is58mm: is58mm);

    await Printing.layoutPdf(
      onLayout: (format) async => doc.save(),
      name: 'hisob_${DateTime.now().millisecondsSinceEpoch}',
      format: pageFormat,
      dynamicLayout: false,
    );
  } finally {
    _releasePrintLock();
  }
}

// ---- OSHPAZ CHEKI: narxsiz, faqat taom nomi va soni bilan oshxonaga
// chop etiladigan buyurtma cheki (PaymentScreen "Oshpaz cheki" tugmasi) ----
Future<void> printKitchenTicket({
  required List<CartItem> items,
  TableModel? table,
  String? hallName,
  String note = '',
}) async {
  final is58mm = appState.paperWidthMm == 58 || appState.printerCharsPerLine <= 32;
  final printItems = items.asMap().entries.map((e) => ReceiptPrintItem(
    index: e.key + 1,
    name: e.value.product.name,
    qty: e.value.qty,
    unitPrice: e.value.product.price,
    lineTotal: e.value.product.price * e.value.qty,
  )).toList();

  final html = ThermalHtmlGenerator.buildKitchenTicketHtml(
    items: printItems,
    tableNumber: table != null ? '${table.number}' : null,
    hallName: hallName,
    note: note,
    is58mm: is58mm,
  );

  final ticketId = 'kt_${table?.number ?? 0}_${DateTime.now().millisecondsSinceEpoch}';

  // Oshxona printer konfiguratsiyasi (agar yoqilgan bo'lsa, aks holda asosiy printer)
  final useKitchenPrinter = appState.kitchenPrinterEnabled && appState.isKitchenPrinterVerified;
  final printerType = useKitchenPrinter ? appState.kitchenPrinterConnectionType : appState.printerConnectionType;
  final printerIp = useKitchenPrinter ? appState.kitchenPrinterIp : appState.printerIp;
  final printerPort = useKitchenPrinter ? appState.kitchenPrinterPort : appState.printerPort;
  final printerDeviceId = useKitchenPrinter
      ? (appState.kitchenPrinterConnectionType == 'usb' ? appState.kitchenPrinterUsbName : appState.kitchenPrinterBtName)
      : (appState.printerConnectionType == 'usb' ? appState.printerUsbName : appState.printerBtName);
  final isConfigured = useKitchenPrinter || appState.printerConfigured;

  // 1. Termal printerga to'g'ridan-to'g'ri chiqarish
  bool printedViaDirect = false;
  if (kIsWeb) {
    try {
      final isAgentUp = await PrintAgentService().isAgentRunning();
      if (isAgentUp && isConfigured) {
        final pngBase64 = await WebReceiptPrinter.renderHtmlToPng(html, widthPx: is58mm ? 384 : 576);
        if (pngBase64 != null && pngBase64.isNotEmpty) {
          final ok = await PrintAgentService().printJob(
            jobId: ticketId,
            type: 'oshpaz',
            printerConfig: {
              'type': printerType,
              'ip': printerIp,
              'port': printerPort,
              'deviceId': printerDeviceId,
              'paperWidth': appState.paperWidthMm,
            },
            imageBase64: pngBase64,
          );
          if (ok) {
            printedViaDirect = true;
          }
        }
      }
    } catch (e) {
      debugPrint('PrintAgent printKitchenTicket error: $e');
    }
  } else if (!kIsWeb && isConfigured && printerType == 'wifi') {
    try {
      await NetworkPrinterService.printKitchenTicketNetwork(
        items: items,
        ip: printerIp,
        port: printerPort,
        table: table,
        hallName: hallName,
        note: note,
        charsPerLine: appState.printerCharsPerLine,
      );
      printedViaDirect = true;
    } catch (e) {
      debugPrint('NetworkPrinterService printKitchenTicketNetwork error: $e');
    }
  }

  if (printedViaDirect) {
    showZaveroSnackBar(
      message: "Oshpaz cheki printerdan chop etildi",
      backgroundColor: const Color(0xFF10B981),
      duration: const Duration(seconds: 2),
      prefixIcon: Icons.check_circle_outline,
    );
    return;
  }

  // 2. Masofaviy / Kassa printeri (Cloud Station Print) tekshiruvi:
  if (!appState.isPrinterStation) {
    final result = await CloudPrintService().dispatchPrintJob(
      id: ticketId,
      type: 'kitchen_ticket',
      html: html,
      tableNumber: table != null ? '${table.number}' : null,
      hallName: hallName,
    );

    if (result.routedToStation) {
      showZaveroSnackBar(
        message: "Oshpaz cheki oshxona/kassa printeriga yuborildi",
        backgroundColor: const Color(0xFF10B981),
        duration: const Duration(seconds: 2),
        prefixIcon: Icons.soup_kitchen_outlined,
      );
      return;
    } else if (!isConfigured) {
      showZaveroSnackBar(
        message: "Kassa/oshxona printeri ulanmagan, chek chop etilmadi",
        backgroundColor: const Color(0xFFDC2626),
        prefixIcon: Icons.print_disabled_outlined,
      );
      return;
    }
  }

  if (!isConfigured && !appState.isPrinterStation) {
    return;
  }

  // 3. Fallback: Yashirin iframe (Web) yoki Printing PDF (Native)
  if (!await _acquirePrintLock()) return;
  try {
    if (kIsWeb) {
      final ok = await WebReceiptPrinter.printHtml(html);
      if (!ok) {
        throw Exception('Oshpaz chekini chop etishda xatolik');
      }
      return;
    }

    const roll58 = PdfPageFormat(58 * PdfPageFormat.mm, double.infinity, marginAll: 2 * PdfPageFormat.mm);
    final rollFormat = is58mm ? roll58 : PdfPageFormat.roll80;
    final doc = pw.Document();
    doc.addPage(
      pw.Page(
        pageFormat: rollFormat,
        margin: const pw.EdgeInsets.all(10),
        build: (context) {
          return pw.Column(
            crossAxisAlignment: pw.CrossAxisAlignment.start,
            children: [
              pw.Center(
                child: pw.Text(
                  'OSHPAZ CHEKI',
                  style: const pw.TextStyle(
                    fontSize: 16,
                    fontWeight: pw.FontWeight.bold,
                  ),
                ),
              ),
              pw.SizedBox(height: 4),
              pw.Divider(),
              if (table != null)
                pw.Text(
                  '${hallName ?? ''} - Stol ${table.number}',
                  style: const pw.TextStyle(
                    fontSize: 13,
                    fontWeight: pw.FontWeight.bold,
                  ),
                ),
              pw.Text(
                DateTime.now().toString().substring(0, 16),
                style: const pw.TextStyle(fontSize: 9),
              ),
              pw.Divider(),
              ...items.map(
                (item) => pw.Padding(
                  padding: const pw.EdgeInsets.symmetric(vertical: 3),
                  child: pw.Row(
                    children: [
                      pw.Expanded(
                        flex: 3,
                        child: pw.Text(
                          item.product.name,
                          style: const pw.TextStyle(
                            fontSize: 11,
                            fontWeight: pw.FontWeight.bold,
                          ),
                        ),
                      ),
                      pw.Expanded(
                        flex: 1,
                        child: pw.Text(
                          '${item.qty} ta',
                          textAlign: pw.TextAlign.center,
                          style: const pw.TextStyle(
                            fontSize: 11,
                            fontWeight: pw.FontWeight.bold,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              if (note.trim().isNotEmpty) ...[
                pw.Divider(),
                pw.Text(
                  'Izoh: $note',
                  style: const pw.TextStyle(fontSize: 9),
                ),
              ],
            ],
          );
        },
      ),
    );

    await Printing.layoutPdf(
      onLayout: (format) async => doc.save(),
      name: 'oshpaz_cheki_${DateTime.now().millisecondsSinceEpoch}',
      format: rollFormat,
      dynamicLayout: false,
    );
  } finally {
    _releasePrintLock();
  }
}

