/// Global dismissible SnackBar helper
/// Har qanday xabarga (qizil, yashil, ma'lumot) avtomatik [X] yopish tugmasi qo'shadi,
/// floating qilib ekranni to'sib qo'ymasligini ta'minlaydi va bir marta bosishda yo'qotadi.
void showZaveroSnackBar({
  required String message,
  bool isError = false,
  Color? backgroundColor,
  Duration duration = const Duration(milliseconds: 3200),
  SnackBarAction? action,
  String? actionLabel,
  VoidCallback? onAction,
  IconData? prefixIcon,
  BuildContext? context,
}) {
  try {
    final messenger = rootMessengerKey.currentState ?? appMessengerKey.currentState;
    if (messenger == null || !messenger.mounted) return;

    try {
      messenger.hideCurrentSnackBar();
      messenger.clearSnackBars();
    } catch (_) {}

    final effectiveBgColor = backgroundColor ??
        (isError ? const Color(0xFFEF4444) : const Color(0xFF1E293B));
    final effectiveIcon = prefixIcon ?? (isError ? Icons.error_outline : null);

    messenger.showSnackBar(
      SnackBar(
        content: Row(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            if (effectiveIcon != null) ...[
              Icon(effectiveIcon, color: Colors.white, size: 19),
              const SizedBox(width: 10),
            ],
            Expanded(
              child: Text(
                message,
                maxLines: 3,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.w600,
                  fontSize: 13,
                  height: 1.25,
                ),
              ),
            ),
            if (action != null) ...[
              const SizedBox(width: 8),
              InkWell(
                onTap: () {
                  try {
                    messenger.hideCurrentSnackBar();
                    messenger.clearSnackBars();
                  } catch (_) {}
                  action.onPressed();
                },
                borderRadius: BorderRadius.circular(6),
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                  decoration: BoxDecoration(
                    color: Colors.white.withValues(alpha: 0.22),
                    borderRadius: BorderRadius.circular(6),
                  ),
                  child: Text(
                    action.label,
                    style: TextStyle(
                      color: action.textColor ?? Colors.white,
                      fontWeight: FontWeight.bold,
                      fontSize: 12,
                    ),
                  ),
                ),
              ),
            ] else if (actionLabel != null && onAction != null) ...[
              const SizedBox(width: 8),
              InkWell(
                onTap: () {
                  try {
                    messenger.hideCurrentSnackBar();
                    messenger.clearSnackBars();
                  } catch (_) {}
                  onAction();
                },
                borderRadius: BorderRadius.circular(6),
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                  decoration: BoxDecoration(
                    color: Colors.white.withValues(alpha: 0.22),
                    borderRadius: BorderRadius.circular(6),
                  ),
                  child: Text(
                    actionLabel,
                    style: const TextStyle(
                      color: Colors.white,
                      fontWeight: FontWeight.bold,
                      fontSize: 12,
                    ),
                  ),
                ),
              ),
            ],
            const SizedBox(width: 10),
            // Bitta bosishda xabarni yo'qotuvchi [X] tugmasi (barcha yashil, qizil, ma'lumot xabarlari uchun)
            InkWell(
              onTap: () {
                try {
                  messenger.hideCurrentSnackBar();
                  messenger.clearSnackBars();
                } catch (_) {}
              },
              borderRadius: BorderRadius.circular(16),
              child: Container(
                padding: const EdgeInsets.all(4),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.18),
                  shape: BoxShape.circle,
                ),
                child: const Icon(Icons.close_rounded, color: Colors.white, size: 16),
              ),
            ),
          ],
        ),
        backgroundColor: effectiveBgColor,
        duration: duration,
        behavior: SnackBarBehavior.fixed,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(12)),
        ),
        dismissDirection: DismissDirection.down,
      ),
    );
  } catch (e) {
    debugPrint('⚠️ [showZaveroSnackBar] notice: $e');
  }
}

