// ============================================================
// LOGO WIDGET — ZAVERO
// ============================================================

class CafeLogo extends StatelessWidget {
  final double size;
  final bool isWhite;
  const CafeLogo({super.key, this.size = 90, this.isWhite = false});

  Widget _buildFallback(BuildContext context) {
    return Padding(
      padding: EdgeInsets.all(size * 0.10),
      child: Image.asset(
        'assets/logo/logo_transparent.png',
        fit: BoxFit.contain,
        errorBuilder: (c, e, s) => Image.asset(
          'assets/images/logo.png',
          fit: BoxFit.contain,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: appState,
      builder: (context, _) {
        final logoUrl = appState.appLogoUrl;
        Widget childWidget;
        if (logoUrl != null && logoUrl.trim().isNotEmpty) {
          final trimmed = logoUrl.trim();
          if (trimmed.startsWith('http') || trimmed.startsWith('data:image')) {
            childWidget = OptimizedImage(
              imageUrl: trimmed,
              fit: BoxFit.cover,
            );
          } else if (trimmed.startsWith('assets/')) {

            childWidget = Image.asset(
              trimmed,
              fit: BoxFit.cover,
              errorBuilder: (c, e, s) => _buildFallback(context),
            );
          } else {
            final file = File(trimmed);
            if (file.existsSync()) {
              childWidget = Image.file(
                file,
                fit: BoxFit.cover,
                errorBuilder: (c, e, s) => _buildFallback(context),
              );
            } else {
              childWidget = _buildFallback(context);
            }
          }
        } else {
          childWidget = _buildFallback(context);
        }
        

        return Container(
          width: size,
          height: size,
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            color: Colors.white,
            boxShadow: [
              BoxShadow(
                color: Colors.black.withValues(alpha: 0.1),
                blurRadius: 16,
                spreadRadius: 1,
                offset: const Offset(0, 4),
              ),
            ],
            border: Border.all(
              color: Colors.white.withValues(alpha: 0.9),
              width: size * 0.04,
            ),
          ),
          child: ClipOval(child: childWidget),
        );
      },
    );
  }
}

// ============================================================
// SPLASH SCREEN — "ZAVERO" shu yerda chiqadi
// ============================================================

class SplashScreen extends StatefulWidget {
  const SplashScreen({super.key});
  @override
  State<SplashScreen> createState() => _SplashScreenState();
}

class _SplashScreenState extends State<SplashScreen>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _scale;
  late Animation<double> _fade;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1200),
    );
    _scale = CurvedAnimation(parent: _controller, curve: Curves.elasticOut);
    _fade = CurvedAnimation(parent: _controller, curve: Curves.easeIn);
    _controller.forward();
    Future.delayed(const Duration(milliseconds: 1800), () async {
      if (!mounted) return;

      // 0.5. Agar 4-xonali PIN kod o'rnatilgan bo'lsa (Image 2), avval PIN Lock ekrani ochiladi:
      final hasPin = await PinSecurityService().hasAnyPin();
      if (hasPin) {
        await TokenStorage().init();
        await ApiClient().init();
        if (!mounted) return;
        Navigator.of(context).pushReplacement(
          MaterialPageRoute(
            settings: const RouteSettings(name: 'pin_lock'),
            builder: (_) => const PinLockScreen(),
          ),
        );
        return;
      }

      // 1. Avval saqlangan sessiyani tekshiramiz
      final savedUser = await appState.restoreUserSession();
      final hasToken = ApiClient().isAuthenticated;

      if (savedUser != null && hasToken) {
        if (savedUser.role == UserRole.director) {
          if (!mounted) return;
          Navigator.of(context).pushReplacement(
            MaterialPageRoute(
              settings: const RouteSettings(name: 'director'),
              builder: (_) => DirectorScreen(directorUser: savedUser),
            ),
          );
          return;
        }

        if (savedUser.isBlocked || savedUser.isExpired) {
          if (!mounted) return;
          Navigator.of(context).pushReplacement(
            MaterialPageRoute(
              settings: const RouteSettings(name: 'blocked'),
              builder: (_) => BlockedScreen(user: savedUser),
            ),
          );
          return;
        }

        final cafeId = appState.currentCafeId;
        if (cafeId.isNotEmpty && cafeId != 'local_default') {
          try {
            await appState.loadCloudDataForCafe(cafeId);
          } catch (e) {
            debugPrint('Splash saved session load error: $e');
          }
        }
        if (!mounted) return;
        Navigator.of(context).pushReplacement(
          MaterialPageRoute(
            settings: const RouteSettings(name: 'dashboard'),
            builder: (_) => const DashboardScreen(),
          ),
        );
        return;
      }

      // 2. Agar sessiya yoki token yo'q bo'lsa -> to'g'ridan-to'g'ri AuthScreen ochiladi
      if (!mounted) return;
      Navigator.of(context).pushReplacement(
        MaterialPageRoute(
          builder: (_) => const AuthScreen(),
        ),
      );
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF0A0E17),
      body: Stack(
        children: [
          // 1. Background deep dark gradient with luxury mesh glow
          Container(
            decoration: const BoxDecoration(
              gradient: RadialGradient(
                center: Alignment(0.0, -0.15),
                radius: 1.1,
                colors: [
                  Color(0xFF1E293B),
                  Color(0xFF0F172A),
                  Color(0xFF0A0E17),
                  Color(0xFF020617),
                ],
                stops: [0.0, 0.45, 0.75, 1.0],
              ),
            ),
          ),

          // 2. Subtle pulsing gold ambient aura
          Center(
            child: ScaleTransition(
              scale: _scale,
              child: Container(
                width: 260,
                height: 260,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: const Color(0xFFFFB300).withValues(alpha: 0.18),
                      blurRadius: 90,
                      spreadRadius: 20,
                    ),
                  ],
                ),
              ),
            ),
          ),

          // 3. Main Brand Content
          Center(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  // Animated Logo
                  ScaleTransition(
                    scale: _scale,
                    child: FadeTransition(
                      opacity: _fade,
                      child: Container(
                        width: 130,
                        height: 130,
                        padding: const EdgeInsets.all(4),
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(28),
                          gradient: const LinearGradient(
                            colors: [Color(0xFFFFD54F), Color(0xFFFF8F00), Color(0xFF263238)],
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                          ),
                          boxShadow: [
                            BoxShadow(
                              color: const Color(0xFFFFB300).withValues(alpha: 0.35),
                              blurRadius: 30,
                              offset: const Offset(0, 10),
                            ),
                            BoxShadow(
                              color: Colors.black.withValues(alpha: 0.8),
                              blurRadius: 20,
                              offset: const Offset(0, 8),
                            ),
                          ],
                        ),
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(24),
                          child: Image.asset(
                            'assets/logo/logo.png',
                            fit: BoxFit.cover,
                            errorBuilder: (_, __, ___) => const Center(
                              child: Icon(Icons.flash_on_rounded, color: Color(0xFFFFB300), size: 64),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(height: 28),

                  // Brand Name: ZAVERO
                  FadeTransition(
                    opacity: _fade,
                    child: ShaderMask(
                      shaderCallback: (bounds) => const LinearGradient(
                        colors: [Colors.white, Color(0xFFFFE082), Color(0xFFFFB300)],
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                      ).createShader(bounds),
                      child: const Text(
                        'ZAVERO',
                        style: TextStyle(
                          fontSize: 38,
                          fontWeight: FontWeight.w900,
                          letterSpacing: 4.0,
                          color: Colors.white,
                          height: 1.0,
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(height: 10),

                  // Subtitle / Tagline
                  FadeTransition(
                    opacity: _fade,
                    child: Text(
                      tr('tagline'),
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFFFFB300),
                        letterSpacing: 2.8,
                      ),
                    ),
                  ),
                  const SizedBox(height: 8),

                  FadeTransition(
                    opacity: _fade,
                    child: Text(
                      tr('app_subtitle'),
                      textAlign: TextAlign.center,
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w500,
                        color: Color(0xFF94A3B8),
                        letterSpacing: 0.8,
                      ),
                    ),
                  ),
                  const SizedBox(height: 48),

                  // Modern Micro Progress Indicator
                  FadeTransition(
                    opacity: _fade,
                    child: SizedBox(
                      width: 140,
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(8),
                        child: const LinearProgressIndicator(
                          minHeight: 3.5,
                          backgroundColor: Color(0xFF1E293B),
                          valueColor: AlwaysStoppedAnimation<Color>(Color(0xFFFFB300)),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

