// ============================================================
// ============================================================
// ANIMATED MENU BUTTON (hamburger → X)
// ============================================================
class _AnimatedMenuBtn extends StatefulWidget {
  final VoidCallback onTap;
  const _AnimatedMenuBtn({required this.onTap});
  @override
  State<_AnimatedMenuBtn> createState() => _AnimatedMenuBtnState();
}

class _AnimatedMenuBtnState extends State<_AnimatedMenuBtn>
    with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;
  late final Animation<double> _rot;
  late final Animation<double> _scale;
  bool _open = false;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 300));
    _rot   = Tween<double>(begin: 0, end: 0.375).animate(CurvedAnimation(parent: _ctrl, curve: Curves.easeInOut));
    _scale = Tween<double>(begin: 1, end: 0.85).animate(CurvedAnimation(parent: _ctrl, curve: Curves.easeInOut));
  }

  @override
  void dispose() { _ctrl.dispose(); super.dispose(); }

  void _toggle() {
    setState(() => _open = !_open);
    _open ? _ctrl.forward() : _ctrl.reverse();
    widget.onTap();
    // reset after drawer closes
    Future.delayed(const Duration(milliseconds: 500), () {
      if (mounted) { setState(() => _open = false); _ctrl.reverse(); }
    });
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: _toggle,
      child: AnimatedBuilder(
        animation: _ctrl,
        builder: (_, __) => Transform.scale(
          scale: _scale.value,
          child: Container(
            width: 38, height: 38,
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: 0.08 + _ctrl.value * 0.08),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(color: Colors.white.withValues(alpha: 0.12 + _ctrl.value * 0.1), width: 1),
              boxShadow: _open ? [BoxShadow(color: const Color(0xFFFFB300).withValues(alpha: 0.25), blurRadius: 12, spreadRadius: 1)] : [],
            ),
            child: RotationTransition(
              turns: _rot,
              child: Icon(
                _open ? Icons.close_rounded : Icons.menu_rounded,
                color: _open ? const Color(0xFFFFB300) : Colors.white.withValues(alpha: 0.9),
                size: 20,
              ),
            ),
          ),
        ),
      ),
    );
  }
}

// IMAGE 3 & 4: ANIMATED HEADER LOGO BADGE & GREETING PILL BADGE
// ============================================================
class _AnimatedHeaderLogoBadge extends StatefulWidget {
  final double size;
  const _AnimatedHeaderLogoBadge({this.size = 36});

  @override
  State<_AnimatedHeaderLogoBadge> createState() => _AnimatedHeaderLogoBadgeState();
}

class _AnimatedHeaderLogoBadgeState extends State<_AnimatedHeaderLogoBadge>
    with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1400),
    );
    // 1 marta nafis kirish animatsiyasi, keyin CPU yuklamaslik uchun to'xtaydi
    _ctrl.forward().then((_) {
      if (mounted) {
        _ctrl.reverse();
      }
    });
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _ctrl,
      builder: (context, child) {
        final scale = 0.96 + 0.08 * _ctrl.value;
        final glowRadius = 4.0 + 8.0 * _ctrl.value;
        return Transform.scale(
          scale: scale,
          child: Container(
            width: widget.size,
            height: widget.size,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: Colors.white,
              border: Border.all(
                color: Color.lerp(
                  const Color(0xFFFF4D4D),
                  const Color(0xFFFFB300),
                  _ctrl.value,
                )!,
                width: 1.8,
              ),
              boxShadow: [
                BoxShadow(
                  color: const Color(0xFFFF4D4D).withValues(alpha: 0.35 * _ctrl.value + 0.15),
                  blurRadius: glowRadius,
                  spreadRadius: 1.0,
                ),
              ],
            ),
            child: ClipOval(
              child: Padding(
                padding: const EdgeInsets.all(3.0),
                child: Image.asset(
                  'assets/logo/logo_transparent.png',
                  fit: BoxFit.contain,
                  errorBuilder: (c, e, s) => Image.asset(
                    'assets/images/logo.png',
                    fit: BoxFit.contain,
                  ),
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

