class _LivePingBadge extends StatelessWidget {
  final bool isMobile;
  const _LivePingBadge({this.isMobile = false});

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: Listenable.merge([
        ConnectivityService().latencyNotifier,
        ConnectivityService().stateNotifier,
        ConnectivityService().qualityNotifier,
      ]),
      builder: (context, _) {
        final service = ConnectivityService();
        final color = service.color;
        final latency = service.latencyMs;
        final badgeText = !service.isOnline ? 'Offline' : '$latency ms';

        if (isMobile) {
          return Container(
            padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
            decoration: BoxDecoration(
              color: color.withValues(alpha: 0.16),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: color.withValues(alpha: 0.45)),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _PulsingDot(color: color),
                const SizedBox(width: 4),
                Text(
                  badgeText,
                  style: TextStyle(
                    color: color,
                    fontWeight: FontWeight.w700,
                    fontSize: 11,
                  ),
                ),
              ],
            ),
          );
        }

        return Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
          decoration: BoxDecoration(
            color: color.withValues(alpha: 0.12),
            borderRadius: BorderRadius.circular(20),
            border: Border.all(color: color.withValues(alpha: 0.35)),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              _PulsingDot(color: color),
              const SizedBox(width: 5),
              Text(
                badgeText,
                style: TextStyle(
                  color: color,
                  fontWeight: FontWeight.w700,
                  fontSize: 11.5,
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

// ============================================================
// USER ROLE DISPLAY HELPER
// ============================================================
String _roleName(UserRole? role) {
  switch (role) {
    case UserRole.admin:
      return 'Administrator';
    case UserRole.director:
      return 'Direktor';
    case UserRole.waiter:
      return 'Ofitsiant';
    case UserRole.cashier:
      return 'Kassir';
    case UserRole.courier:
      return 'Kuryer';
    case UserRole.customer:
      return 'Mijoz';
    default:
      return 'Foydalanuvchi';
  }
}

