class _UserDropdownButton extends StatelessWidget {
  final AppUser? user;
  final bool iconOnly;
  final bool expanded;

  const _UserDropdownButton({
    this.user,
    this.iconOnly = false,
    // ignore: unused_element_parameter
    this.expanded = false,
  });

  @override
  Widget build(BuildContext context) {
    final initial = (user?.name != null && user!.name.isNotEmpty)
        ? user!.name.substring(0, 1).toUpperCase()
        : 'U';
    final roleStr = _roleName(user?.role);
    final userName = user?.name ?? 'Admin';

    return PopupMenuButton<String>(
      tooltip: 'Foydalanuvchi profili',
      offset: const Offset(0, 48),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
        side: const BorderSide(color: Color(0xFFE2E8F0)),
      ),
      color: Colors.white,
      elevation: 10,
      shadowColor: Colors.black.withValues(alpha: 0.15),
      onSelected: (val) async {
        if (val == 'profile') {
          Navigator.push(context, MaterialPageRoute(builder: (_) => const ProfileScreen()));
        } else if (val == 'settings') {
          Navigator.push(context, MaterialPageRoute(builder: (_) => const SettingsScreen()));
        } else if (val == 'lock') {
          Navigator.push(
            context,
            MaterialPageRoute(
              settings: const RouteSettings(name: 'pin_lock'),
              builder: (_) => PinLockScreen(
                isModal: true,
                onUnlocked: () => Navigator.pop(context),
              ),
            ),
          );
        } else if (val == 'logout') {
          await appState.logout();
          if (context.mounted) {
            Navigator.pushAndRemoveUntil(
              context,
              MaterialPageRoute(builder: (_) => const AuthScreen()),
              (r) => false,
            );
          }
        }
      },
      itemBuilder: (_) => [
        // User info header
        PopupMenuItem<String>(
          enabled: false,
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 4),
            child: Row(
              children: [
                CircleAvatar(
                  radius: 18,
                  backgroundColor: const Color(0xFF0F1E30),
                  child: Text(
                    initial,
                    style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 13),
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        userName,
                        style: const TextStyle(
                          color: Color(0xFF0F1E30),
                          fontSize: 14,
                          fontWeight: FontWeight.w700,
                        ),
                        overflow: TextOverflow.ellipsis,
                      ),
                      Text(
                        roleStr,
                        style: const TextStyle(color: Color(0xFF64748B), fontSize: 11),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
        const PopupMenuDivider(),
        const PopupMenuItem<String>(
          
          value: 'profile',
          child: Row(
            children: [
              Icon(Icons.person_outline_rounded, color: Color(0xFF315EFB), size: 20),
              SizedBox(width: 12),
              Text(
                'Profil',
                style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: Color(0xFF1E293B)),
              ),
            ],
          ),
        ),
        if (user?.role == UserRole.admin || user?.role == UserRole.director)
          const PopupMenuItem<String>(
            value: 'settings',
            child: Row(
              children: [
                Icon(Icons.settings_outlined, color: Color(0xFF64748B), size: 20),
                SizedBox(width: 12),
                Text(
                  'Sozlamalar',
                  style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600, color: Color(0xFF1E293B)),
                ),
              ],
            ),
          ),
        const PopupMenuItem<String>(
          value: 'lock',
          child: Row(
            children: [
              Icon(Icons.lock_outline_rounded, color: Color(0xFFF59E0B), size: 20),
              SizedBox(width: 12),
