class _DashboardScreenState extends State<DashboardScreen> with WidgetsBindingObserver {
  bool _sidebarCollapsed = false;
  bool _reportsExpanded = true;
  int _mobileNavIndex = 0;
  DateTimeRange? _selectedDateRange;

  String _formattedHeaderDate() {
    final now = DateTime.now();
    final nowT = now.toUtc().add(const Duration(hours: 5));
    if (_selectedDateRange != null) {
      final s = _selectedDateRange!.start;
      final e = _selectedDateRange!.end;
      final sStr = '${s.day.toString().padLeft(2, '0')}.${s.month.toString().padLeft(2, '0')}.${s.year}';
      final eStr = '${e.day.toString().padLeft(2, '0')}.${e.month.toString().padLeft(2, '0')}.${e.year}';
      return sStr == eStr ? sStr : '$sStr - $eStr';
    }
    return '${nowT.day.toString().padLeft(2, '0')}.${nowT.month.toString().padLeft(2, '0')}.${nowT.year}';
  }

  // ── Network & Heartbeat state ──────────────────────────────────────────
  Timer? _heartbeatTimer;
  int _lastHeartbeatMs = 0;
  int _heartbeatIntervalMs = 15000;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    ConnectivityService().init();
    _startHeartbeatTimer();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      ConnectivityService().checkNow();
      final cafeId = appState.currentCafeId;
      if (cafeId.isNotEmpty && cafeId != 'local_default' && ApiClient().isAuthenticated) {
        if (!SocketService().isConnected) {
          SocketService().connect(cafeId: cafeId);
        }
        appState.loadCloudDataForCafe(cafeId);
      }
    }
  }

  void _startHeartbeatTimer() {
    _heartbeatTimer?.cancel();
    _heartbeatTimer = Timer.periodic(const Duration(seconds: 15), (_) => _sendHeartbeat());
  }

  Future<void> _sendHeartbeat() async {
    final cafeId = appState.currentCafeId;
    if (cafeId.isNotEmpty && cafeId != 'local_default' && cafeId != 'zavero' && ApiClient().isAuthenticated) {
      final nowMs = DateTime.now().millisecondsSinceEpoch;
      if (nowMs - _lastHeartbeatMs >= _heartbeatIntervalMs) {
        _lastHeartbeatMs = nowMs;
        ApiClient().post('/cafes/heartbeat', body: {'cafeId': cafeId}).then((_) {
          _heartbeatIntervalMs = 15000;
        }).catchError((_) {
          _heartbeatIntervalMs = (_heartbeatIntervalMs == 15000) ? 30000 : 60000;
        });
      }
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _heartbeatTimer?.cancel();
    super.dispose();
  }

  void _showNotificationsModal(BuildContext context) {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.transparent,
      isScrollControlled: true,
      builder: (ctx) => AnimatedBuilder(
        animation: appState,
        builder: (ctx, _) {
          final items = appState.notifications;
          final unreadCount = appState.unreadNotificationsCount;

          return Container(
            constraints: BoxConstraints(
              maxHeight: MediaQuery.of(context).size.height * 0.75,
              maxWidth: 540,
            ),
            decoration: const BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                // Drag handle
                Center(
                  child: Container(
                    margin: const EdgeInsets.only(top: 10, bottom: 6),
                    width: 36,
                    height: 4,
                    decoration: BoxDecoration(
                      color: const Color(0xFFCBD5E1),
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                ),
                // Header
                Padding(
                  padding: const EdgeInsets.fromLTRB(20, 10, 16, 12),
                  child: Row(
                    children: [
                      Container(
                        padding: const EdgeInsets.all(8),
                        decoration: BoxDecoration(
                          color: const Color(0xFFEEF4FF),
                          borderRadius: BorderRadius.circular(10),
                        ),
                        child: const Icon(Icons.notifications_active_rounded, color: Color(0xFF315EFB), size: 20),
                      ),
                      const SizedBox(width: 12),
                      Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'Bildirishnomalar',
                            style: TextStyle(fontWeight: FontWeight.w800, fontSize: 17, color: Color(0xFF0F1E30)),
                          ),
                          Text(
                            unreadCount > 0 ? '$unreadCount ta yangi xabar' : 'Barcha xabarlar o\'qilgan',
                            style: TextStyle(fontSize: 12, color: Colors.grey.shade600, fontWeight: FontWeight.w500),
                          ),
                        ],
                      ),
                      const Spacer(),
                      if (items.isNotEmpty) ...[
                        TextButton(
                          onPressed: () {
                            appState.markAllNotificationsAsRead();
                            appState.markAllAnnouncementsAsRead();
                          },
                          child: const Text('O\'qilgan', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: Color(0xFF315EFB))),
                        ),
                        IconButton(
                          icon: const Icon(Icons.delete_sweep_rounded, size: 20, color: Color(0xFF94A3B8)),
                          tooltip: 'Tozalash',
                          onPressed: () {
                            appState.clearNotifications();
                          },
                        ),
                      ],
                    ],
                  ),
                ),
                const Divider(height: 1, color: Color(0xFFF1F5F9)),

                // Body
                Expanded(
                  child: items.isEmpty
                      ? Center(
                          child: Padding(
                            padding: const EdgeInsets.all(32),
                            child: Column(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Container(
                                  padding: const EdgeInsets.all(18),
                                  decoration: const BoxDecoration(
                                    color: Color(0xFFF1F5F9),
                                    shape: BoxShape.circle,
                                  ),
                                  child: const Icon(Icons.notifications_none_rounded, size: 40, color: Color(0xFF94A3B8)),
                                ),
                                const SizedBox(height: 14),
                                const Text(
                                  'Hozircha bildirishnomalar yo\'q',
                                  style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700, color: Color(0xFF334155)),
                                ),
                                const SizedBox(height: 6),
                                Text(
                                  'Yangi buyurtma, to\'lov yoki obuna yangilanishlari shu yerda ko\'rsatiladi',
                                  textAlign: TextAlign.center,
                                  style: TextStyle(fontSize: 12.5, color: Colors.grey.shade500),
                                ),
                              ],
                            ),
                          ),
                        )
                      : ListView.separated(
                          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                          itemCount: items.length,
                          separatorBuilder: (_, __) => const SizedBox(height: 8),
                          itemBuilder: (ctx, i) {
                            final n = items[i];
                            final timeStr = '${n.time.hour.toString().padLeft(2, '0')}:${n.time.minute.toString().padLeft(2, '0')}';

                            IconData iconData = Icons.info_outline_rounded;
                            Color iconColor = const Color(0xFF315EFB);
                            Color bgIconColor = const Color(0xFFEEF4FF);

                            if (n.type == 'order') {
                              iconData = Icons.shopping_bag_rounded;
                              iconColor = const Color(0xFFF59E0B);
                              bgIconColor = const Color(0xFFFEF3C7);
                            } else if (n.type == 'receipt') {
                              iconData = Icons.check_circle_rounded;
                              iconColor = const Color(0xFF10B981);
                              bgIconColor = const Color(0xFFECFDF5);
                            } else if (n.type == 'subscription') {
                              iconData = Icons.workspace_premium_rounded;
                              iconColor = const Color(0xFF8B5CF6);
                              bgIconColor = const Color(0xFFF3E8FF);
                            } else if (n.type == 'announcement') {
                              iconData = Icons.campaign_rounded;
                              iconColor = const Color(0xFFEF4444);
                              bgIconColor = const Color(0xFFFEE2E2);
                            }

                            return InkWell(
                              onTap: () {
                                n.isRead = true;
                                final annId = safeNullableInt(n.id);
                                if (annId != null) {
                                  appState.markAnnouncementAsRead(annId);
                                }
                                appState.notifyChanges();
                                Navigator.pop(ctx);
                                if (n.type == 'announcement') {
                                  showDialog(
                                    context: context,
                                    builder: (_) => AlertDialog(
                                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
                                      title: Row(
                                        children: [
                                          const Icon(Icons.campaign_rounded, color: Color(0xFF2563EB)),
                                          const SizedBox(width: 8),
                                          Expanded(child: Text(n.title, style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold))),
                                        ],
                                      ),
                                      content: Text(n.body, style: const TextStyle(fontSize: 14)),
                                      actions: [
                                        TextButton(
                                          onPressed: () => Navigator.pop(context),
                                          child: const Text('Yopish', style: TextStyle(fontWeight: FontWeight.bold)),
                                        ),
                                      ],
                                    ),
                                  );
                                } else if (n.type == 'order') {
                                  Navigator.push(context, MaterialPageRoute(builder: (_) => const CustomerOrdersScreen()));
                                } else if (n.type == 'receipt') {
                                  Navigator.push(context, MaterialPageRoute(builder: (_) => const ReceiptHistoryScreen()));
                                } else if (n.type == 'subscription') {
                                  Navigator.push(context, MaterialPageRoute(builder: (_) => const ProfileScreen()));
                                }
                              },
                              borderRadius: BorderRadius.circular(16),
                              child: Container(
                                padding: const EdgeInsets.all(12),
                                decoration: BoxDecoration(
                                  color: n.isRead ? Colors.white : const Color(0xFFF8FAFC),
                                  borderRadius: BorderRadius.circular(16),
                                  border: Border.all(
                                    color: n.isRead ? const Color(0xFFE2E8F0) : const Color(0xFF315EFB).withValues(alpha: 0.35),
                                    width: n.isRead ? 1 : 1.5,
                                  ),
                                ),
                                child: Row(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Container(
                                      padding: const EdgeInsets.all(8),
                                      decoration: BoxDecoration(
                                        color: bgIconColor,
                                        borderRadius: BorderRadius.circular(10),
                                      ),
                                      child: Icon(iconData, color: iconColor, size: 18),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: Column(
                                        crossAxisAlignment: CrossAxisAlignment.start,
                                        children: [
                                          Row(
                                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                                            children: [
                                              Expanded(
                                                child: Text(
                                                  n.title,
                                                  style: TextStyle(
                                                    fontWeight: n.isRead ? FontWeight.w600 : FontWeight.w800,
                                                    fontSize: 13.5,
                                                    color: const Color(0xFF0F1E30),
                                                  ),
                                                  overflow: TextOverflow.ellipsis,
                                                ),
                                              ),
                                              Text(
                                                timeStr,
                                                style: const TextStyle(fontSize: 11, color: Color(0xFF94A3B8)),
                                              ),
                                            ],
                                          ),
                                          const SizedBox(height: 4),
                                          Text(
                                            n.body,
                                            style: const TextStyle(fontSize: 12, color: Color(0xFF64748B)),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            );
                          },
                        ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final user = appState.currentUser;

    if (user != null && user.role == UserRole.director) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          Navigator.of(context).pushReplacement(
            MaterialPageRoute(
              settings: const RouteSettings(name: 'director'),
              builder: (_) => DirectorScreen(directorUser: user),
            ),
          );
        }
      });
      return const Scaffold(
        backgroundColor: Color(0xFF0F172A),
        body: Center(child: CircularProgressIndicator(color: Color(0xFFFFC107))),
      );
    }

    // Texnik ishlar (Maintenance) rejimida bo'lsa:
    if (appState.isUnderMaintenance && user?.role != UserRole.director) {
      return Scaffold(
        backgroundColor: const Color(0xFF0F172A),
        appBar: AppBar(
          backgroundColor: const Color(0xFF1E293B),
          title: Text(appState.restaurantName),
          actions: [
            IconButton(
              icon: const Icon(Icons.logout, color: Colors.redAccent),
              tooltip: 'Chiqish',
              onPressed: () async {
                await appState.logout();
                if (context.mounted) {
                  Navigator.pushAndRemoveUntil(
                    context,
                    MaterialPageRoute(builder: (_) => const AuthScreen()),
                    (r) => false,
                  );
                }
              },
            ),
          ],
        ),
        body: Center(
          child: Container(
            padding: const EdgeInsets.all(32),
            margin: const EdgeInsets.all(24),
            constraints: const BoxConstraints(maxWidth: 480),
            decoration: BoxDecoration(
              color: const Color(0xFF1E293B),
              borderRadius: BorderRadius.circular(24),
              border: Border.all(color: const Color(0xFFFFC107).withValues(alpha: 0.35)),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withValues(alpha: 0.5),
                  blurRadius: 20,
                  offset: const Offset(0, 10),
                ),
              ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: const Color(0xFFFFC107).withValues(alpha: 0.15),
                    shape: BoxShape.circle,
                  ),
                  child: const Icon(Icons.build_circle_rounded, size: 64, color: Color(0xFFFFC107)),
                ),
                const SizedBox(height: 20),
                const Text(
                  'Texnik ishlar olib borilmoqda',
                  style: TextStyle(color: Colors.white, fontSize: 20, fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 10),
                const Text(
                  'Director tomonidan kafeda profilaktika va sozlash ishlari olib borilmoqda.\nIshlar yakunlanishi bilan ilova avtomatik tarzda to\'liq ishlab ketadi.',
                  textAlign: TextAlign.center,
                  style: TextStyle(color: Colors.grey, fontSize: 13.5, height: 1.4),
                ),
                const SizedBox(height: 24),
                const CircularProgressIndicator(color: Color(0xFFFFC107)),
              ],
            ),
          ),
        ),
      );
    }

    final isAdmin = user?.role == UserRole.admin;
    final isWaiter = user?.role == UserRole.waiter;
    // ignore: unused_local_variable
    final isCourier = user?.role == UserRole.courier;
    final isCustomer = user?.role == UserRole.customer;

    return AnimatedBuilder(
      animation: Listenable.merge([appState, LocalizationService()]),
      builder: (context, _) {
        final tiles = <_DashTile>[
          // ==========================================
          // MIJOZ UCHUN BO'LIMLAR
          // ==========================================
          if (isCustomer) ...[
            _DashTile(
              tr('tile_new_order'),
              Icons.restaurant_menu_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const HallSelectionScreen()),
              ),
            ),
            _DashTile(
              tr('tile_customer_orders'),
              Icons.receipt_long_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const CustomerOrdersScreen()),
              ),
              badge: appState.pendingOrdersCount,
            ),
            _DashTile(
              tr('tile_receipt_history'),
              Icons.history_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const ReceiptHistoryScreen()),
              ),
            ),
          ],

          // ==========================================
          // XODIM PANELI (OFITSIANT, KASSIR, XODIM)
          // Faqat: Yangi buyurtma, Mijozlardan buyurtma, Cheklar, Mahsulotlar, Mijozlar
          // ==========================================
          if (!isAdmin && !isCustomer) ...[
            // 1. Yangi buyurtma — dashboard ichida stollar ko'rsatiladi, navigatsiya shart emas
            _DashTile(
              tr('tile_new_order'),
              Icons.point_of_sale_rounded,
              () {},
            ),

            // 2. Mijozlardan buyurtma (QR menyu va online)
            _DashTile(
              'Mijozlardan buyurtma',
              Icons.receipt_long_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const CustomerOrdersScreen()),
              ),
              badge: appState.pendingOrdersCount,
            ),

            // 3. Cheklar
            _DashTile(
              tr('tile_receipt_history'),
              Icons.history_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const ReceiptHistoryScreen()),
              ),
            ),

            // 4. Mahsulotlar
            _DashTile(
              tr('tile_products'),
              Icons.restaurant_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const ProductsScreen()),
              ),
            ),
          ],

          // ==========================================
          // ADMIN (CAFE EGASI) UCHUN ASOSIY BO'LIMLAR
          // ==========================================
          if (isAdmin) ...[
            // Cheklar tarixi
            _DashTile(
              tr('tile_receipt_history'),
              Icons.history_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const ReceiptHistoryScreen()),
              ),
            ),
          ],

          // ==========================================
          // FAQAT CAFE EGASI (ADMIN) UCHUN BO'LIMLAR
          // ==========================================
          // 4. Hisobotlar
          if (isAdmin)
            _DashTile(
              tr('tile_reports'),
              Icons.analytics_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const ReportsScreen()),
              ),
            ),

          // 5. Ombor
          if (isAdmin)
            _DashTile(
              tr('tile_inventory'),
              Icons.inventory_2_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const InventoryScreen()),
              ),
            ),

          // 6. Mahsulotlar
          if (isAdmin)
            _DashTile(
              tr('tile_products'),
              Icons.restaurant_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const ProductsScreen()),
              ),
            ),

          // 7. Kategoriyalar
          if (isAdmin)
            _DashTile(
              tr('tile_categories'),
              Icons.grid_view_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const CategoriesScreen()),
              ),
            ),

          // 8. Xodimlar
          if (isAdmin)
            _DashTile(
              tr('tile_employees'),
              Icons.badge_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const EmployeesScreen()),
              ),
            ),


          // 10. Stollar boshqaruvi
          if (isAdmin)
            _DashTile(
              tr('tile_tables'),
              Icons.table_restaurant_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const TablesManagementScreen()),
              ),
            ),

          // 11. Sozlamalar
          if (isAdmin)
            _DashTile(
              tr('tile_settings'),
              Icons.tune_rounded,
              () => Navigator.push(
                context,
                MaterialPageRoute(builder: (_) => const SettingsScreen()),
              ),
            ),
        ];

        final screenWidth = MediaQuery.of(context).size.width;
        final isMobile = screenWidth < 700;

        // ── Collapsible sidebar builder ──────────────────────
        Widget buildSidebar() {
          final collapsed = _sidebarCollapsed;
          return AnimatedContainer(
            duration: const Duration(milliseconds: 230),
            curve: Curves.easeInOut,
            width: collapsed ? 64 : 220,
            color: const Color(0xFF0F1E30),
            child: LayoutBuilder(
              builder: (context, sbConstraints) {
                if (sbConstraints.maxWidth <= 24) return const SizedBox.shrink();
                final isSbNarrow = collapsed || sbConstraints.maxWidth < 110;

                return Column(
                  children: [
                    // ── Logo + Cafe header ─────────────────────────
                    Container(
                      padding: EdgeInsets.fromLTRB(isSbNarrow ? 10 : 16, 20, isSbNarrow ? 10 : 16, 16),
                      decoration: const BoxDecoration(
                        border: Border(bottom: BorderSide(color: Color(0xFF1A2E45), width: 1)),
                      ),
                      child: isSbNarrow
                          ? Center(
                              child: InkWell(
                                borderRadius: BorderRadius.circular(8),
                                onTap: () => setState(() => _sidebarCollapsed = false),
                                child: Container(
                                  width: math.min(sbConstraints.maxWidth, 40.0),
                                  height: 40,
                                  decoration: BoxDecoration(color: const Color(0xFF1A2E45), borderRadius: BorderRadius.circular(10)),
                                  child: const _AnimatedHeaderLogoBadge(size: 40),
                                ),
                              ),
                            )
                          : Row(
                              children: [
                                Container(
                                  width: 40, height: 40,
                                  decoration: BoxDecoration(
                                    color: const Color(0xFF1A2E45),
                                    borderRadius: BorderRadius.circular(10),
                                  ),
                                  child: const _AnimatedHeaderLogoBadge(size: 40),
                                ),
                                const SizedBox(width: 10),
                                const Expanded(
                                  child: Column(
                                    crossAxisAlignment: CrossAxisAlignment.start,
                                    children: [
                                      Text('ZAVERO', style: TextStyle(color: Colors.white, fontWeight: FontWeight.w900, fontSize: 13, letterSpacing: 1.2), maxLines: 1, overflow: TextOverflow.ellipsis),
                                      Text('POS', style: TextStyle(color: Color(0xFFFFB300), fontWeight: FontWeight.w700, fontSize: 11, letterSpacing: 1.0), maxLines: 1, overflow: TextOverflow.ellipsis),
                                    ],
                                  ),
                                ),
                                // ← Collapse toggle
                                InkWell(
                                  borderRadius: BorderRadius.circular(8),
                                  onTap: () => setState(() => _sidebarCollapsed = true),
                                  child: const Icon(Icons.keyboard_arrow_left_rounded, color: Colors.white54, size: 22),
                                ),
                              ],
                            ),
                    ),

                    // ── Cafe name sub-header (faqat kengaytilganda) ─
                    if (!isSbNarrow) ...[  
                      Container(
                        padding: const EdgeInsets.fromLTRB(16, 12, 16, 12),
                        child: Row(children: [
                          Container(
                            width: 36, height: 36,
                            decoration: BoxDecoration(
                              color: const Color(0xFF1A2E45),
                              borderRadius: BorderRadius.circular(8),
                            ),
                            child: const Icon(Icons.storefront_rounded, color: Color(0xFFFFB300), size: 18),
                          ),
                          const SizedBox(width: 10),
                          Expanded(child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                appState.restaurantName.isNotEmpty ? appState.restaurantName : 'Zavero Cafe',
                                style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w700, fontSize: 13),
                                maxLines: 1, overflow: TextOverflow.ellipsis,
                              ),
                              const Text('Kafe boshqaruvi osonroq', style: TextStyle(color: Color(0xFF6B8BA4), fontSize: 10.5), maxLines: 1, overflow: TextOverflow.ellipsis),
                            ],
                          )),
                        ]),
                      ),
                    ],

                    const Divider(color: Color(0xFF1A2E45), height: 1),
                    const SizedBox(height: 8),

                    // ── Nav items (Image 2 ga 100% mos) ───────────
                    if (isAdmin) ...[
                      Expanded(
                        child: ListView(
                          padding: EdgeInsets.symmetric(horizontal: isSbNarrow ? 8 : 10, vertical: 4),
                          children: [
                            // 1. Boshqaruv paneli (Active - Image 2)
                            _buildSidebarItem(
                              icon: Icons.home_rounded,
                              title: 'Boshqaruv paneli',
                              isActive: _mobileNavIndex == 0,
                              collapsed: isSbNarrow,
                              onTap: () => setState(() => _mobileNavIndex = 0),
                            ),
                            const SizedBox(height: 3),
                            // 2. Stollar (Jonli stollar gridi)
                            _buildSidebarItem(
                              icon: Icons.table_restaurant_rounded,
                              title: 'Stollar',
                              isActive: _mobileNavIndex == 1,
                              collapsed: isSbNarrow,
                              onTap: () => setState(() => _mobileNavIndex = 1),
                            ),
                            const SizedBox(height: 3),
                            // 2. Hisobotlar (Collapsible Submenu - Image 2)
                            if (isSbNarrow)
                              _buildSidebarItem(
                                icon: Icons.bar_chart_rounded,
                                title: 'Hisobotlar',
                                isActive: false,
                                collapsed: true,
                                onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ReportsScreen())),
                              )
                            else ...[
                              _buildExpandableSidebarItem(
                                icon: Icons.bar_chart_rounded,
                                title: 'Hisobotlar',
                                isExpanded: _reportsExpanded,
                                onToggle: () => setState(() => _reportsExpanded = !_reportsExpanded),
                                children: [
                                  _buildSubmenuItem(
                                    title: 'Umumiy hisobot',
                                    onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ReportsScreen(initialTabIndex: 0))),
                                  ),
                                  _buildSubmenuItem(
                                    title: 'Savdo hisobotlari',
                                    onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ReportsScreen(initialTabIndex: 0))),
                                  ),
                                  _buildSubmenuItem(
                                    title: 'Xarajatlar hisoboti',
                                    onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ReportsScreen(initialTabIndex: 0))),
                                  ),
                                  _buildSubmenuItem(
                                    title: 'Xodimlar hisoboti',
                                    onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ReportsScreen(initialTabIndex: 2))),
                                  ),
                                ],
                              ),
                            ],
                            const SizedBox(height: 3),
                            // 3. Cheklar tarixi
                            _buildSidebarItem(
                              icon: Icons.receipt_long_rounded,
                              title: 'Cheklar tarixi',
                              isActive: false,
                              collapsed: isSbNarrow,
                              onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ReceiptHistoryScreen())),
                            ),
                            const SizedBox(height: 3),
                            // 4. Buyurtmalar
                            _buildSidebarItem(
                              icon: Icons.shopping_bag_outlined,
                              title: 'Buyurtmalar',
                              isActive: false,
                              badge: appState.pendingOrdersCount,
                              collapsed: isSbNarrow,
                              onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const CustomerOrdersScreen())),
                            ),
                            const SizedBox(height: 3),
                            // 5. Mahsulotlar
                            _buildSidebarItem(
                              icon: Icons.restaurant_rounded,
                              title: 'Mahsulotlar',
                              isActive: false,
                              collapsed: isSbNarrow,
                              onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ProductsScreen())),
                            ),
                            const SizedBox(height: 3),
                            // 6. Kategoriyalar
                            _buildSidebarItem(
                              icon: Icons.grid_view_rounded,
                              title: 'Kategoriyalar',
                              isActive: false,
                              collapsed: isSbNarrow,
                              onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const CategoriesScreen())),
                            ),
                            const SizedBox(height: 3),
                            // 7. Xodimlar
                            _buildSidebarItem(
                              icon: Icons.people_outline_rounded,
                              title: 'Xodimlar',
                              isActive: false,
                              collapsed: isSbNarrow,
                              onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const EmployeesScreen())),
                            ),
                            const SizedBox(height: 3),
                            // 8. Stollar boshqaruvi
                            _buildSidebarItem(
                              icon: Icons.table_restaurant_rounded,
                              title: 'Stollar boshqaruvi',
                              isActive: false,
                              collapsed: isSbNarrow,
