                                setState(() => _mobileNavIndex = 2);
                                await Future.delayed(const Duration(milliseconds: 80));
                                if (context.mounted) {
                                  await Navigator.push(
                                    context,
                                    MaterialPageRoute(builder: (_) => const ReportsScreen()),
                                  );
                                }
                                if (mounted) setState(() => _mobileNavIndex = 0);
                              },
                            ),
                            // 4. Cheklar
                            _mobileNavBtn(
                              Icons.history_rounded,
                              Icons.history_rounded,
                              'Cheklar',
                              3 == _mobileNavIndex,
                              () async {
                                setState(() => _mobileNavIndex = 3);
                                await Future.delayed(const Duration(milliseconds: 80));
                                if (context.mounted) {
                                  await Navigator.push(
                                    context,
                                    MaterialPageRoute(builder: (_) => const ReceiptHistoryScreen()),
                                  );
                                }
                                if (mounted) setState(() => _mobileNavIndex = 0);
                              },
                            ),
                            // 5. Profil
                            _mobileNavBtn(
                              Icons.person_outline_rounded,
                              Icons.person_rounded,
                              'Profil',
                              4 == _mobileNavIndex,
                              () async {
                                setState(() => _mobileNavIndex = 4);
                                await Future.delayed(const Duration(milliseconds: 80));
                                if (context.mounted) {
                                  await Navigator.push(
                                    context,
                                    MaterialPageRoute(builder: (_) => const ProfileScreen()),
                                  );
                                }
                                if (mounted) setState(() => _mobileNavIndex = 0);
                              },
                            ),
                          ] else ...[
                            // 1. Stollar (Ofitsiant uchun asosiy stol buyurtmalari)
                            _mobileNavBtn(
                              Icons.table_restaurant_outlined,
                              Icons.table_restaurant_rounded,
                              'Stollar',
                              0 == _mobileNavIndex,
                              () => setState(() => _mobileNavIndex = 0),
                            ),
                            // 2. Buyurtmalar (Ofitsiant paneli)
                            _mobileNavBtn(
                              Icons.receipt_long_outlined,
                              Icons.receipt_long_rounded,
                              'Buyurtmalar',
                              1 == _mobileNavIndex,
                              () async {
                                setState(() => _mobileNavIndex = 1);
                                await Future.delayed(const Duration(milliseconds: 80));
                                if (context.mounted) {
                                  await Navigator.push(
                                    context,
                                    MaterialPageRoute(builder: (_) => const CustomerOrdersScreen()),
                                  );
                                }
                                if (mounted) setState(() => _mobileNavIndex = 0);
                              },
                              badge: appState.pendingOrdersCount,
                            ),
                            // 3. Cheklar
                            _mobileNavBtn(
                              Icons.history_rounded,
                              Icons.history_rounded,
                              'Cheklar',
                              2 == _mobileNavIndex,
                              () async {
                                setState(() => _mobileNavIndex = 2);
                                await Future.delayed(const Duration(milliseconds: 80));
                                if (context.mounted) {
                                  await Navigator.push(
                                    context,
                                    MaterialPageRoute(builder: (_) => const ReceiptHistoryScreen()),
                                  );
                                }
                                if (mounted) setState(() => _mobileNavIndex = 0);
                              },
                            ),
                            // 4. Profil
                            _mobileNavBtn(
                              Icons.person_outline_rounded,
                              Icons.person_rounded,
                              'Profil',
                              3 == _mobileNavIndex,
                              () async {
                                setState(() => _mobileNavIndex = 3);
                                await Future.delayed(const Duration(milliseconds: 80));
                                if (context.mounted) {
                                  await Navigator.push(
                                    context,
                                    MaterialPageRoute(builder: (_) => const ProfileScreen()),
                                  );
                                }
                                if (mounted) setState(() => _mobileNavIndex = 0);
                              },
                            ),
                          ],
                        ],
                      ),
                    ),
                  ),
                )
              : null,

          body: isMobile
              ? Column(children: [
                  // Mobile: compact top AppBar
                  Container(
                    color: const Color(0xFF0F1E30),
                    child: SafeArea(
                      bottom: false,
                      child: LayoutBuilder(
                        builder: (context, barConstraints) {
                          final w = barConstraints.maxWidth;
                          if (w <= 0) return const SizedBox.shrink();
                          final isNarrow = w < 320;
                          final isUltraNarrow = w < 240;

                          return Container(
                            height: 52,
                            padding: EdgeInsets.symmetric(horizontal: isNarrow ? 8 : 16),
                            child: Row(
                              children: [
                                _AnimatedHeaderLogoBadge(size: isNarrow ? 28 : 32),
                                if (!isUltraNarrow) ...[
                                  const SizedBox(width: 8),
                                  Flexible(
                                    child: Text(
                                      'ZAVERO POS',
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: TextStyle(
                                        color: Colors.white,
                                        fontWeight: FontWeight.w900,
                                        fontSize: isNarrow ? 14 : 16,
                                        letterSpacing: 0.5,
                                      ),
                                    ),
                                  ),
                                ],
                                const Spacer(),
                                // Mobile pending actions badge
                                ValueListenableBuilder<int>(
                                  valueListenable: OfflineSyncService().pendingCountNotifier,
