// To'lov / hisob ekrani — stol band bo'lganda ustiga bosilganda ham,
// "To'lovga o'tish" tugmasi bosilganda ham shu ekran ochiladi. Bu yerda
// taomlar ro'yxati (nomi, narxi, soni, xizmat foizi, jami), to'lanayotgan
// summa, izoh, "Xarid cheki"/"Oshpaz cheki" chop etish tugmalari va
// naqd/karta orqali to'lash belgilari bor.
class _PaymentScreenState extends State<PaymentScreen> {
  // 0% = hozircha xizmat haqi yo'q (kerak bo'lsa shu yerdan o'zgartiriladi)
  double servicePercent = 0;
  // ---- To'lov turi belgilari (Naqd/Karta/Olib ketish) ----
  bool payByCash = false;
  bool payByCard = false;
  bool isTakeaway = false;
  final TextEditingController _payingCtrl = TextEditingController();
  final TextEditingController _noteCtrl = TextEditingController();
  bool printingKitchen = false;
  bool confirming = false;
  bool _isCompleting = false;
  bool _isPaid = false;
  bool _isProcessingWithPrint = false;
  bool _isProcessingWithoutPrint = false;
  bool _payingInitialized = false;
  double? _lastSyncedTotal;

  @override
  void initState() {
    super.initState();
    _noteCtrl.text = appState.selectedTableNote;
    if (appState.selectedHall?.name.toLowerCase() == 'saboy' ||
        _noteCtrl.text.contains('[Olib ketish]')) {
      isTakeaway = true;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) {
        appState.checkPrinterConnectionQuick().then((_) {
          if (mounted) setState(() {});
        });
        appState.checkCloudPrinterStationStatus().then((_) {
          if (mounted) setState(() {});
        });
      }
    });
  }

  @override
  void dispose() {
    _globalCheckoutInProgress = false;
    _payingCtrl.dispose();
    _noteCtrl.dispose();
    super.dispose();
  }

  double get _productsTotal => appState.cartTotal;
  double get _serviceTotal => _productsTotal * servicePercent / 100;
  double get _grandTotal => _productsTotal + _serviceTotal;

  void _ensurePayingInitialized() {
    if (!_payingInitialized || _lastSyncedTotal != _grandTotal) {
      _payingCtrl.text = _grandTotal.round().toString();
      _payingInitialized = true;
      _lastSyncedTotal = _grandTotal;
    }
  }

  double get _payingAmount => double.tryParse(_payingCtrl.text) ?? 0;

  void _changePaying(double delta) {
    final v = (_payingAmount + delta).clamp(0, double.infinity);
    setState(() => _payingCtrl.text = v.round().toString());
  }

  bool printingBill = false;

  Future<void> _sendReceiptToBackend({required String type}) async {
    try {
      final table = appState.selectedTable;
      final hall = appState.selectedHall;
      final cashierName = appState.currentUser?.name ?? appState.guestName ?? 'Ofitsiant';
      final cashierId = appState.currentUser?.id;
      final now = DateTime.now();
      final checkId = 'T${table?.number ?? '-'}-${now.millisecondsSinceEpoch}';

      final method = payByCash && payByCard
          ? 'split'
          : (payByCash ? 'cash' : 'card');

      final itemsPayload = appState.cart.map((it) => {
        'product': {
          'id': it.product.id,
          'name': it.product.name,
          'price': it.product.price,
        },
        'qty': it.qty,
      }).toList();

      final effectiveHall = hall ?? (table != null ? appState.halls.firstWhere((h) => h.id == table.hallId, orElse: () => Hall(id: -1, name: '', icon: Icons.home)) : null);
      final effectiveHallName = (effectiveHall != null && effectiveHall.name.trim().isNotEmpty) ? effectiveHall.name.trim() : null;
      final effectiveTableName = table != null
          ? ((effectiveHallName != null) ? '$effectiveHallName - Stol ${table.number}' : 'Stol ${table.number}')
          : (effectiveHallName ?? 'Zal');

      await ApiClient().post('/receipts', body: {
        'orderId': checkId,
        'tableName': effectiveTableName,
        'tableId': table?.id,
        'hallId': table?.hallId ?? effectiveHall?.id,
        'tableNumber': table?.number,
        'hallName': effectiveHallName,
        'items': itemsPayload,
        'total': _grandTotal,
        'paymentMethod': method,
        'waiterId': cashierId != null ? '$cashierId' : null,
        'waiterName': cashierName,
        'createdAt': now.toIso8601String(),
        'type': type,
      });
    } catch (e) {
      debugPrint('ℹ️ [Receipt] Fon yuborish: $e');
    }
  }

  // ---- "Xarid cheki" tugmasi endi hech qanday oraliq sahifa ochmaydi —
  // to'g'ridan-to'g'ri (hali to'lanmagan) hisobni zamonaviy chek
  // ko'rinishida printer/"Chop etish" oynasiga yuboradi. ----
  Future<void> _printBill() async {
    if (appState.cart.isEmpty) return;
    setState(() => printingBill = true);
    final method = payByCash && payByCard
        ? PaymentMethod.split
        : (payByCash ? PaymentMethod.cash : PaymentMethod.card);
    try {
      await printBillPreview(
        items: List<CartItem>.from(appState.cart),
        productsTotal: _productsTotal,
        serviceTotal: _serviceTotal,
        grandTotal: _grandTotal,
        method: method,
        table: appState.selectedTable,
        hallName: appState.selectedHall?.name,
      );
      // 1-TALAB: Agar oldin "Xarid cheki" chiqarilgan bo'lsa, "To'landi" da qayta chiqmasligi uchun belgilaymiz
      appState.markReceiptPrintedForOrder(appState.selectedTable?.id, appState.selectedTable?.number);
      // 4-TALAB: Ofitsiant paneliga real vaqtda yuborish
      unawaited(_sendReceiptToBackend(type: 'bill_preview'));
    } catch (e) {
      if (mounted) {
        showZaveroSnackBar(
          message: 'Kassa printeri oflayn yoki ulanmagan: $e',
          backgroundColor: const Color(0xFFEF4444),
          prefixIcon: Icons.print_disabled_outlined,
        );
      }
    } finally {
      if (mounted) setState(() => printingBill = false);
    }
  }

  Future<void> _printKitchen() async {
    setState(() => printingKitchen = true);
    try {
      await printKitchenTicket(
        items: appState.cart,
        table: appState.selectedTable,
        hallName: appState.selectedHall?.name,
        note: _noteCtrl.text,
      );
      // 4-TALAB: Ofitsiant paneliga real vaqtda yuborish
      unawaited(_sendReceiptToBackend(type: 'kitchen_ticket'));
    } catch (e) {
      if (mounted) {
        showZaveroSnackBar(
          message: 'Oshpaz chekini chop etishda xatolik: $e',
          backgroundColor: const Color(0xFFEF4444),
          prefixIcon: Icons.error_outline,
        );
      }
    } finally {
      if (mounted) setState(() => printingKitchen = false);
    }
  }

  // ---- "Chekni ko'rish" — to'lovdan oldin, real (joriy) savat
  // ma'lumotlari bilan iframe srcdoc orqali modalda chek ko'rinishini
  // ko'rsatadi. Bu yerdan to'g'ridan-to'g'ri "Chop etish" va "Yopish" mumkin. ----
  void _showReceiptPreview() {
    if (appState.cart.isEmpty) return;
    final table = appState.selectedTable;
    final hall = appState.selectedHall;
    final cashierName =
        appState.currentUser?.name ?? appState.guestName ?? 'Mehmon';
    final now = DateTime.now();
    final dateTimeStr = '${now.year}.${now.month.toString().padLeft(2, '0')}.'
        '${now.day.toString().padLeft(2, '0')} - '
        '${now.hour.toString().padLeft(2, '0')}:'
        '${now.minute.toString().padLeft(2, '0')}:'
        '${now.second.toString().padLeft(2, '0')}';
    final checkId = 'T${table?.number ?? '-'}-${now.millisecondsSinceEpoch}';
    final is58mm = appState.paperWidthMm == 58 || appState.printerCharsPerLine <= 32;

    final printData = ReceiptPrintData(
      checkId: checkId,
      dateTime: now,
      cashierName: cashierName,
      cafeName: appState.effectiveReceiptName.isNotEmpty ? appState.effectiveReceiptName : 'Family Cafe',
      address: appState.restaurantAddress.trim().isNotEmpty ? appState.restaurantAddress.trim() : "Navoi ko'chasi 12, Buxoro",
      phone: appState.restaurantPhone.trim().isNotEmpty ? appState.restaurantPhone.trim() : '+998 90 123 45 67',
      slogan: appState.receiptSlogan.trim().isNotEmpty ? appState.receiptSlogan.trim() : "Yaxshi ta'm • Baxtli onlar",
      footerMessage: appState.receiptFooterNote.trim().isNotEmpty ? appState.receiptFooterNote.trim() : 'Bizni tanlaganingiz uchun rahmat!',
      qrUrl: appState.receiptQrEnabled ? appState.effectiveReceiptQrUrl : '',
      tableNumber: table != null ? '${table.number}' : null,
      hallName: hall?.name,
      items: appState.cart.asMap().entries.map((e) => ReceiptPrintItem(
        index: e.key + 1,
        name: e.value.product.name,
        qty: e.value.qty,
        unitPrice: e.value.product.price,
        lineTotal: e.value.product.price * e.value.qty,
      )).toList(),
      subtotal: _productsTotal,
      discount: (_productsTotal - _grandTotal) > 0 ? (_productsTotal - _grandTotal) : 0,
      grandTotal: _grandTotal,
      paymentMethod: payByCard ? 'card' : 'cash',
      is58mm: is58mm,
    );

    final html = ThermalHtmlGenerator.buildReceiptHtml(
      printData,
      logoUrl: (appState.appLogoUrl != null && appState.appLogoUrl!.trim().isNotEmpty) ? appState.appLogoUrl!.trim() : null,
    );

    if (kIsWeb) {
      // 3-TALAB: Mavjud chek HTML'ini sahifa ichidagi modalda (iframe srcdoc) ko'rsatish
      WebReceiptPrinter.showModal(html);
      return;
    }

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) {
        return DraggableScrollableSheet(
          initialChildSize: 0.85,
          minChildSize: 0.5,
          maxChildSize: 0.95,
          expand: false,
          builder: (context, scrollController) {
            return Container(
              decoration: const BoxDecoration(
                color: Color(0xFFEDEDED),
                borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
              ),
              child: Column(
                children: [
                  const SizedBox(height: 10),
                  Container(
                    width: 40,
                    height: 4,
                    decoration: BoxDecoration(
                      color: Colors.grey.shade400,
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                  Expanded(
                    child: SingleChildScrollView(
                      controller: scrollController,
                      padding: const EdgeInsets.symmetric(vertical: 16),
                      child: Center(
                        child: Material(
                          elevation: 2,
                          borderRadius: BorderRadius.circular(4),
                          child: ReceiptWidget(
                            checkId: checkId,
                            waiter: cashierName,
                            hallName: hall?.name ?? 'Зал',
                            table: '${table?.number ?? ''}',
                            customer: '1',
                            dateTime: dateTimeStr,
                            items: appState.cart
                                .map(
                                  (c) => ReceiptItem(
                                    name: c.product.name,
                                    quantity: '${c.qty} dona',
                                    price: ReceiptWidget.money(
                                      c.product.price.round(),
                                    ),
                                  ),
                                )
                                .toList(),
                          ),
                        ),
                      ),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.fromLTRB(16, 8, 16, 16),
                    child: SizedBox(
                      width: double.infinity,
                      child: ElevatedButton.icon(
                        style: ElevatedButton.styleFrom(
                          backgroundColor: const Color(0xFF3B6E91),
                          foregroundColor: Colors.white,
                          padding: const EdgeInsets.symmetric(vertical: 14),
                        ),
                        onPressed: () {
                          Navigator.pop(context);
                          _printBill();
                        },
                        icon: const Icon(Icons.print),
                        label: const Text('Chop etish'),
                      ),
                    ),
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }

  void _addMoreItems() {
    Navigator.push(
      context,
      MaterialPageRoute(
        settings: const RouteSettings(name: 'pos'),
        builder: (_) => const POSScreen(),
      ),
    ).then((_) => setState(() {}));
  }

  void _backToTableSelection() {
    if (confirming || _isCompleting || _isPaid) return;
    appState.leaveOrderSession();
    if (!mounted) return;
    final nav = appNavigatorKey.currentState;
    if (nav != null && nav.canPop()) {
      nav.popUntil((route) => route.isFirst);
    }
  }

  static bool _globalCheckoutInProgress = false;
  static int _lastCheckoutTimestamp = 0;

  Future<void> _confirmPaid({bool shouldPrintReceipt = true}) async {
    final now = DateTime.now().millisecondsSinceEpoch;
    // 1. Zudlik bilan sinxron bloklash (double-click, triple-click va takroriy bosishlarni 100% to'sadi)
    if (_globalCheckoutInProgress || (now - _lastCheckoutTimestamp < 3000)) {
      debugPrint('⚠️ [Payment] To‘lov allaqachon bajarilmoqda yoki bloklangan.');
      return;
    }
    if (confirming || _isCompleting || _isPaid || appState.cart.isEmpty) return;

    _globalCheckoutInProgress = true;
    _lastCheckoutTimestamp = now;
    _isCompleting = true;
    setState(() {
      confirming = true;
      if (shouldPrintReceipt) {
        _isProcessingWithPrint = true;
      } else {
        _isProcessingWithoutPrint = true;
      }
    });

    final nav = Navigator.of(context);

    // Agar to'lov turi belgilanmagan bo'lsa, standart Naqd pul sifatida qabul qilamiz
    if (!payByCash && !payByCard) {
      payByCash = true;
    }
    final method = payByCash && payByCard
        ? PaymentMethod.split
        : (payByCash ? PaymentMethod.cash : PaymentMethod.card);
    double cash = 0, card = 0;
    if (method == PaymentMethod.split) {
      cash = _payingAmount;
      card = (_grandTotal - cash).clamp(0, double.infinity).toDouble();
    } else if (method == PaymentMethod.cash) {
      cash = _payingAmount < _grandTotal ? _grandTotal : _payingAmount;
    } else {
      card = _grandTotal;
    }

    Hall? hallBeforeCheckout = appState.selectedHall;
    final curTable = appState.selectedTable;
    if (hallBeforeCheckout == null && curTable != null) {
      for (final h in appState.halls) {
        if (h.id == curTable.hallId) {
          hallBeforeCheckout = h;
          break;
        }
      }
    }

    if (isTakeaway) {
      final existingNote = appState.selectedTableNote;
      if (!existingNote.contains('[Olib ketish]')) {
        appState.setTableNote('[Olib ketish] $existingNote'.trim());
      }
    }

    final selTable = appState.selectedTable;
    final ik = 'chk_tbl_${selTable?.id ?? 0}_${selTable?.number ?? 0}_${appState.cartTotal.round()}_${appState.cart.length}_$now';
    final isPrinterReady = appState.isPrinterVerified ||
        (!appState.isPrinterStation && appState.hasCloudPrinterStation && appState.isCloudStationPrinterReady);
    final initialPrintStatus = (shouldPrintReceipt && isPrinterReady)
        ? (appState.autoPrintOnPaid ? 'queued' : 'unprinted')
        : 'unprinted';

    // ── TRY 1: Haqiqiy to'lovni qayd qilish (Postgres commit & OfflineSync outbox) ──
    Receipt? receipt;
    try {
      receipt = await appState.checkout(
        method: method,
        cashPaid: cash,
        cardPaid: card,
        idempotencyKey: ik,
        printStatus: initialPrintStatus,
      );
    } catch (e) {
      debugPrint('To‘lovni amalga oshirishda xatolik: $e');
      final errStr = e.toString().toLowerCase();
      final isUiGlitch = errStr.contains('deactivated') ||
          errStr.contains('ancestor') ||
          errStr.contains('defunct') ||
          errStr.contains('setstate');

      if (isUiGlitch) {
        debugPrint('⚠️ [Payment] UI framework glitch ushlandi, to‘lov ma’lumotlari buzilmadi.');
        _isPaid = true;
      } else {
        _globalCheckoutInProgress = false;
        _isCompleting = false;
        _isPaid = false;
        if (mounted) {
          setState(() {
            confirming = false;
            _isProcessingWithPrint = false;
            _isProcessingWithoutPrint = false;
          });
        }
        showZaveroSnackBar(
          message: 'To‘lovda xatolik yuz berdi: $e',
          backgroundColor: const Color(0xFFDC2626),
          duration: const Duration(seconds: 3),
          prefixIcon: Icons.error_outline,
        );
        return;
      }
    }

    // To'lov muvaffaqiyatli saqlandi — endi hech qanday holatda to'lov bekor qilinmaydi!
    _isPaid = true;

    // Stolni xotirada 100% bo'shatilishini kafolatlaymiz (Band qolib ketmasligi uchun)
    if (selTable != null) {
      appState.tableOrders.remove(selTable.id);
      appState.tableOrdersByZone.remove(selTable.tableKey);
      appState.tableNotes.remove(selTable.id);
      appState.tableNotesByZone.remove(selTable.tableKey);
      for (final t in appState.tables) {
        if (t.id == selTable.id || (t.number == selTable.number && t.hallId == selTable.hallId)) {
          t.status = TableStatus.free;
          appState.tableOrders.remove(t.id);
          appState.tableOrdersByZone.remove(t.tableKey);
          appState.tableNotes.remove(t.id);
          appState.tableNotesByZone.remove(t.tableKey);
        }
      }
      appState.notifyChanges();
    }

    // ── TRY 2: PRINTER YO'LI (Fire-and-forget, to'lovni aslo to'xtatmaydi) ──
    final targetReceipt = receipt;
    if (shouldPrintReceipt && targetReceipt != null) {
      unawaited(() async {
        try {
          await printReceipt(targetReceipt, isAutoCheckout: false);
          targetReceipt.printStatus = 'printed';
          targetReceipt.printedAt = DateTime.now();
          await ApiClient().patch('/receipts/${targetReceipt.id}/print-status', body: {
            'printStatus': 'printed',
            'printedAt': targetReceipt.printedAt?.toIso8601String(),
          });
          appState.notifyChanges();
        } catch (e) {
          debugPrint('Chek chiqarishda xatolik: $e');
        }
      }());
    }
    appState.clearReceiptPrintedForOrder(selTable?.id, selTable?.number);

    // ── TRY 3: UI NAVIGATSIYA VA XABARNOMA (Alohida xavfsiz blok) ──
    try {
      final rootNav = appNavigatorKey.currentState ?? nav;
      if (rootNav.canPop()) {
        rootNav.popUntil((route) => route.isFirst);
      }

      WidgetsBinding.instance.addPostFrameCallback((_) {
        try {
          rootMessengerKey.currentState?.clearSnackBars();
          if (shouldPrintReceipt) {
            if (!isPrinterReady && !kIsWeb) {
              showZaveroSnackBar(
                message: "To'lov qabul qilindi. Printer oflayn bo'lgani sababli chek Cheklar tarixiga saqlandi.",
                backgroundColor: const Color(0xFFD97706),
                duration: const Duration(milliseconds: 3500),
                prefixIcon: Icons.print_disabled_outlined,
                action: SnackBarAction(
                  label: "Cheklar tarixi",
                  textColor: Colors.white,
                  onPressed: () {
                    rootMessengerKey.currentState?.clearSnackBars();
                    appNavigatorKey.currentState?.push(
                      MaterialPageRoute(builder: (_) => const ReceiptHistoryScreen()),
                    );
                  },
                ),
              );
            } else {
              showZaveroSnackBar(
                message: "To'lov qabul qilindi va chek chiqarildi",
                backgroundColor: const Color(0xFF10B981),
                duration: const Duration(milliseconds: 2500),
                prefixIcon: Icons.check_circle_outline,
              );
            }
          } else {
            showZaveroSnackBar(
              message: "To'lov muvaffaqiyatli qabul qilindi (cheksiz)",
              backgroundColor: const Color(0xFF10B981),
              duration: const Duration(milliseconds: 3000),
              prefixIcon: Icons.check_circle_outline,
              action: targetReceipt != null
                  ? SnackBarAction(
                      label: "Chek chiqarish",
                      textColor: Colors.white,
                      onPressed: () {
                        rootMessengerKey.currentState?.clearSnackBars();
                        printReceipt(targetReceipt);
                      },
                    )
                  : null,
            );
          }
        } catch (_) {}
      });
    } catch (uiError) {
      debugPrint('UI navigation notice: $uiError');
    } finally {
      _globalCheckoutInProgress = false;
      if (mounted) {
        setState(() {
          confirming = false;
          _isProcessingWithPrint = false;
          _isProcessingWithoutPrint = false;
        });
      }
    }
  }

  bool _isTelegramWebApp() {
    if (!kIsWeb) return false;
    try {
      final uri = Uri.base;
      if (uri.queryParameters.containsKey('tgWebAppData') ||
          uri.fragment.contains('tgWebAppData') ||
          uri.toString().contains('tgWebApp')) {
        return true;
      }
    } catch (_) {}
    return false;
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: appState,
      builder: (context, _) {
        _ensurePayingInitialized();
        final table = appState.selectedTable;
        final hall = appState.selectedHall;

        if (confirming || _isCompleting || _isPaid) {
          return const Scaffold(
            backgroundColor: Color(0xFFF8F9FA),
            body: Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  CircularProgressIndicator(color: Color(0xFFE25C1D)),
                  SizedBox(height: 16),
                  Text(
                    'To‘lov qabul qilindi, boshqaruv paneliga qaytilmoqda...',
                    style: TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.bold,
                      color: Color(0xFF0F172A),
                    ),
                  ),
                ],
              ),
            ),
          );
        }

        if (appState.cart.isEmpty) {
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted && !confirming && !_isCompleting && !_isPaid) {
              _backToTableSelection();
            }
          });
          return const Scaffold(
            backgroundColor: Color(0xFFF8F9FA),
            body: Center(
              child: CircularProgressIndicator(color: Color(0xFFE25C1D)),
            ),
          );
        }

        final screenWidth = MediaQuery.of(context).size.width;
        final isTelegram = _isTelegramWebApp();
        final isDesktop = !isTelegram && screenWidth >= 1024;
        final isTablet = !isTelegram && screenWidth >= 700 && screenWidth < 1024;

        return PopScope(
          canPop: false,
          onPopInvokedWithResult: (didPop, result) {
            if (didPop) return;
            _backToTableSelection();
          },
          child: Scaffold(
            backgroundColor: const Color(0xFFF8F9FA),
            body: SafeArea(
              child: Column(
                children: [
                  _buildTopHeader(context),
                  Expanded(
                    child: SingleChildScrollView(
                      padding: EdgeInsets.symmetric(
                        horizontal: isDesktop ? 40 : (isTablet ? 24 : 16),
                        vertical: isDesktop ? 24 : 16,
                      ),
                      child: Center(
                        child: ConstrainedBox(
                          constraints: const BoxConstraints(maxWidth: 1200),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: [
                              _buildSubHeader(context, table, hall),
                              const SizedBox(height: 20),
                              if (isDesktop)
                                _buildDesktopLayout(table, hall)
                              else if (isTablet)
                                _buildTabletLayout(table, hall)
                              else
                                _buildMobileLayout(table, hall, isTelegram: isTelegram),
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _buildTopHeader(BuildContext context) {
    return Container(
      height: 60,
      padding: const EdgeInsets.symmetric(horizontal: 20),
      decoration: const BoxDecoration(
        color: Colors.white,
        border: Border(
          bottom: BorderSide(color: Color(0xFFE5E7EB), width: 1),
        ),
      ),
      child: Row(
        children: [
          // Logo & Name
          ClipRRect(
            borderRadius: BorderRadius.circular(8),
            child: Image.asset(
              'assets/images/logo.png',
              width: 32,
              height: 32,
              fit: BoxFit.contain,
              errorBuilder: (_, __, ___) => Container(
                width: 32,
                height: 32,
                decoration: BoxDecoration(
                  color: const Color(0xFFE25C1D),
                  borderRadius: BorderRadius.circular(8),
                ),
                alignment: Alignment.center,
                child: const Text(
                  'z',
                  style: TextStyle(
