                          final isWide = constraints.maxWidth >= 720;

                          if (isWide) {
                            return GridView.builder(
                              padding: const EdgeInsets.fromLTRB(16, 6, 16, 24),
                              gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                                maxCrossAxisExtent: 420,
