class ReportsScreen extends StatefulWidget {
  final int initialTabIndex;
  const ReportsScreen({super.key, this.initialTabIndex = 0});
  @override
  State<ReportsScreen> createState() => _ReportsScreenState();
}

enum ReportFilterMode { day, week, month, year, all, custom }

class _ReportsScreenState extends State<ReportsScreen>
    with SingleTickerProviderStateMixin {
  late TabController tabController;
  ReportFilterMode _filterMode = ReportFilterMode.day;
  DateTime _selectedDate = DateTime.now();

  @override
  void initState() {
    super.initState();
    tabController = TabController(length: 3, vsync: this, initialIndex: widget.initialTabIndex.clamp(0, 2));
    unawaited(appState.fetchLiveTodayReport());
    appState.addListener(_onAppStateChanged);
  }

  void _onAppStateChanged() {
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    appState.removeListener(_onAppStateChanged);
    tabController.dispose();
    super.dispose();
  }

  bool _isReceiptInFilter(Receipt r) {
    final d = r.date.toLocal();
    final sel = _selectedDate.toLocal();
    switch (_filterMode) {
      case ReportFilterMode.day:
      case ReportFilterMode.custom:
        return d.year == sel.year &&
            d.month == sel.month &&
            d.day == sel.day;
      case ReportFilterMode.week:
        final now = sel;
        final weekAgo = now.subtract(const Duration(days: 7));
        return d.isAfter(weekAgo) && d.isBefore(now.add(const Duration(days: 1)));
      case ReportFilterMode.month:
        return d.year == sel.year && d.month == sel.month;
      case ReportFilterMode.year:
        return d.year == sel.year;
      case ReportFilterMode.all:
        return true;
    }
  }

  String get _periodLabel {
    final y = _selectedDate.year;
    final m = _selectedDate.month.toString().padLeft(2, '0');
    final day = _selectedDate.day.toString().padLeft(2, '0');
    switch (_filterMode) {
      case ReportFilterMode.day:
        return 'Bugun ($y-$m-$day)';
      case ReportFilterMode.week:
        return 'Oxirgi 7 kun';
      case ReportFilterMode.custom:
        return 'Tanlangan sana: $y-$m-$day';
      case ReportFilterMode.month:
        return 'Shu Oy ($y-$m)';
      case ReportFilterMode.year:
        return 'Shu Yil ($y)';
      case ReportFilterMode.all:
        return 'Barcha davr (Jami)';
    }
  }

