  Widget _buildStaffOverviewSection(
    BuildContext context,
    AppState appState,
    List<MapEntry<String, double>> sortedStaff,
    Map<String, int> staffOrderCount,
    double totalRevenue,
  ) {
    final List<Map<String, dynamic>> displayItems = [];

    if (sortedStaff.isNotEmpty) {
      for (final entry in sortedStaff) {
        final staffName = entry.key;
        final rev = entry.value;
        final ordersCount = staffOrderCount[staffName] ?? 0;
        final userModel = appState.users.firstWhere(
          (u) => u.name.toLowerCase() == staffName.toLowerCase() || u.username.toLowerCase() == staffName.toLowerCase(),
          orElse: () => AppUser(id: 0, name: staffName, username: staffName, password: '', role: UserRole.waiter),
        );
        displayItems.add({
          'name': staffName,
          'rev': rev,
          'orders': ordersCount,
          'user': userModel,
        });
      }
    } else {
      for (final u in appState.users) {
        displayItems.add({
          'name': u.name,
          'rev': 0.0,
          'orders': 0,
          'user': u,
        });
      }
    }

    final currentUser = appState.currentUser;
    final isWaiterUser = currentUser?.role == UserRole.waiter;
    if (isWaiterUser && currentUser != null) {
      displayItems.retainWhere((item) {
        final AppUser u = item['user'];
        final String name = item['name'];
        return (currentUser.id != 0 && u.id == currentUser.id) ||
               name.toLowerCase() == currentUser.name.toLowerCase();
      });
    }

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: const Color(0xFFE2E8F0)),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.02),
            blurRadius: 10,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                padding: const EdgeInsets.all(7),
                decoration: BoxDecoration(
                  color: const Color(0xFF10B981).withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: const Icon(Icons.badge_rounded, color: Color(0xFF10B981), size: 18),
              ),
              const SizedBox(width: 10),
              const Expanded(
                child: Text(
                  'Bugungi Ofitsiantlar va Xodimlar Natijalari',
                  style: TextStyle(fontWeight: FontWeight.w800, fontSize: 15, color: Color(0xFF0F172A)),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: BoxDecoration(
                  color: const Color(0xFFF1F5F9),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Text(
                  '${displayItems.length} ta xodim',
                  style: const TextStyle(fontSize: 11, fontWeight: FontWeight.bold, color: Color(0xFF64748B)),
                ),
              ),
            ],
          ),
          const SizedBox(height: 14),
          if (displayItems.isEmpty)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 8),
              child: Text(
                'Xodimlar ro\'yxati bo\'sh',
                style: TextStyle(color: Colors.grey, fontSize: 13),
              ),
            )
          else
            ...displayItems.map((item) {
              final String name = item['name'];
              final double rev = item['rev'];
              final int orders = item['orders'];
              final AppUser u = item['user'];
              final isWaiter = u.role == UserRole.waiter;
              final avg = orders > 0 ? (rev / orders) : 0.0;
              final pct = totalRevenue > 0 ? (rev / totalRevenue) : 0.0;

              final staffStatus = StaffTrackingService().getStatus(u.id);
              final isOnBreak = staffStatus?.isOnBreak ?? false;

              return Container(
                margin: const EdgeInsets.only(bottom: 10),
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: const Color(0xFFF8FAFC),
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(
                    color: isOnBreak ? const Color(0xFFFECACA) : const Color(0xFFE2E8F0),
                    width: isOnBreak ? 1.4 : 1,
                  ),
                ),
                child: Row(
                  children: [
                    Container(
                      width: 42,
                      height: 42,
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          colors: isOnBreak
                              ? [const Color(0xFFEF4444), const Color(0xFFDC2626)]
                              : (isWaiter
                                  ? [const Color(0xFF10B981), const Color(0xFF059669)]
                                  : [const Color(0xFFFFB300), const Color(0xFFFF8F00)]),
                        ),
                        shape: BoxShape.circle,
                      ),
                      child: Center(
                        child: Icon(
                          isOnBreak
                              ? Icons.coffee_rounded
                              : (isWaiter ? Icons.room_service_rounded : Icons.person_rounded),
                          color: Colors.white,
                          size: 20,
                        ),
                      ),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            children: [
                              Text(
                                name,
                                style: const TextStyle(
                                  fontWeight: FontWeight.w800,
                                  fontSize: 14.5,
                                  color: Color(0xFF0F172A),
                                ),
                              ),
                              const SizedBox(width: 6),
                              Container(
                                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 1.5),
                                decoration: BoxDecoration(
                                  color: isWaiter ? const Color(0xFFDCFCE7) : const Color(0xFFFEF3C7),
                                  borderRadius: BorderRadius.circular(6),
                                ),
                                child: Text(
                                  isWaiter ? 'Ofitsiant' : 'Kassir',
                                  style: TextStyle(
                                    fontSize: 10,
                                    fontWeight: FontWeight.bold,
                                    color: isWaiter ? const Color(0xFF16A34A) : const Color(0xFFD97706),
                                  ),
                                ),
                              ),
                              if (isOnBreak) ...[
                                const SizedBox(width: 6),
                                Container(
                                  padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 1.5),
                                  decoration: BoxDecoration(
                                    color: const Color(0xFFFEF2F2),
                                    borderRadius: BorderRadius.circular(6),
                                    border: Border.all(color: const Color(0xFFFCA5A5)),
                                  ),
                                  child: const Text(
                                    '☕ Dam olmoqda',
                                    style: TextStyle(
                                      fontSize: 9.5,
                                      fontWeight: FontWeight.w800,
                                      color: Color(0xFFDC2626),
                                    ),
                                  ),
                                ),
                              ],
                            ],
                          ),
                          const SizedBox(height: 3),
                          Text(
                            'Bugun: $orders ta mijozga qaradi · O\'rtacha: ${formatSum(avg)}',
                            style: const TextStyle(fontSize: 12, color: Color(0xFF64748B)),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(width: 10),
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.end,
                      children: [
                        Text(
                          formatSum(rev),
                          style: const TextStyle(
                            fontWeight: FontWeight.w800,
                            fontSize: 14,
                            color: Color(0xFF10B981),
                          ),
                        ),
                        if (totalRevenue > 0)
                          Text(
                            '${(pct * 100).toStringAsFixed(1)}%',
                            style: const TextStyle(fontSize: 11, color: Colors.grey, fontWeight: FontWeight.bold),
                          ),
                      ],
                    ),
                  ],
                ),
              );
            }),
        ],
      ),
    );
  }
}

// ============================================================
// INVENTORY SCREEN
// ============================================================

class InventoryScreen extends StatefulWidget {
  const InventoryScreen({super.key});
  @override
  State<InventoryScreen> createState() => _InventoryScreenState();
}

class _InventoryScreenState extends State<InventoryScreen> {
  String _searchQuery = '';
  int? _selectedCategoryId;
  Timer? _searchDebounce;

  @override
  void dispose() {
    _searchDebounce?.cancel();
    super.dispose();
  }

  void _adjust(Product p, [int? delta]) {
    if (delta != null) {
      final newStock = (p.stock + delta).clamp(0, 999999);
      setState(() => appState.adjustStock(p, newStock));
      return;
    }

    final ctrl = TextEditingController(text: '${p.stock}');
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: Row(
          children: [
            const Icon(Icons.inventory_2_rounded, color: Color(0xFFFFB300)),
            const SizedBox(width: 8),
            Expanded(child: Text('Zaxirani o\'zgartirish: ${p.name}', style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold))),
          ],
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Hozirgi zaxira: ${p.stock} ta', style: const TextStyle(color: Colors.grey, fontSize: 13)),
            const SizedBox(height: 12),
            TextField(
              controller: ctrl,
              autofocus: true,
              keyboardType: TextInputType.number,
              decoration: InputDecoration(
                labelText: 'Yangi miqdor (dona/porsiya)',
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
                filled: true,
                fillColor: const Color(0xFFF8FAFC),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Bekor qilish'),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFFFFB300),
              foregroundColor: const Color(0xFF0F172A),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
            ),
            onPressed: () {
              final v = int.tryParse(ctrl.text) ?? p.stock;
              setState(() => appState.adjustStock(p, v));
              Navigator.pop(context);
            },
            child: const Text('Saqlash', style: TextStyle(fontWeight: FontWeight.bold)),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final filtered = appState.products.where((p) {
      final matchSearch = _searchQuery.isEmpty || p.name.toLowerCase().contains(_searchQuery.toLowerCase());
      final matchCat = _selectedCategoryId == null || p.categoryId == _selectedCategoryId;
      return matchSearch && matchCat;
    }).toList();

    final totalProducts = appState.products.length;
    final lowStockCount = appState.products.where((p) => p.stock <= 5 && p.stock > 0).length;
    final outOfStockCount = appState.products.where((p) => p.stock == 0).length;
    final totalInventoryValue = appState.products.fold(0.0, (sum, p) => sum + (p.price * p.stock));

    return Scaffold(
      backgroundColor: const Color(0xFFF8FAFC),
      appBar: AppBar(
        elevation: 0,
        backgroundColor: const Color(0xFF0F172A),
        foregroundColor: Colors.white,
        title: const Text('Ombor va Zaxira Boshqaruvi', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18)),
      ),
      body: Column(
        children: [
          // Metrics Cards Bar
          Container(
            padding: const EdgeInsets.all(14),
            color: Colors.white,
            child: Column(
              children: [
                Row(
                  children: [
                    _buildStatCard('Jami taomlar', '$totalProducts ta', Icons.fastfood_rounded, const Color(0xFF3B82F6)),
                    const SizedBox(width: 8),
                    _buildStatCard('Kam qolgan', '$lowStockCount ta', Icons.warning_amber_rounded, const Color(0xFFF59E0B)),
                    const SizedBox(width: 8),
                    _buildStatCard('Tugagan', '$outOfStockCount ta', Icons.highlight_off_rounded, const Color(0xFFEF4444)),
                    const SizedBox(width: 8),
                    _buildStatCard('Zaxira qiymati', formatSum(totalInventoryValue), Icons.account_balance_wallet_rounded, const Color(0xFF10B981)),
                  ],
                ),
                const SizedBox(height: 12),
                // Search Input
                TextField(
                  onChanged: (v) {
                    _searchDebounce?.cancel();
                    _searchDebounce = Timer(const Duration(milliseconds: 180), () {
                      if (mounted) setState(() => _searchQuery = v);
                    });
                  },
                  decoration: InputDecoration(
                    hintText: 'Taom yoki mahsulot nomi bo\'yicha qidirish...',
                    prefixIcon: const Icon(Icons.search_rounded, color: Color(0xFF64748B)),
                    suffixIcon: _searchQuery.isNotEmpty
                        ? IconButton(
                            icon: const Icon(Icons.clear_rounded, color: Colors.grey),
                            onPressed: () => setState(() => _searchQuery = ''),
                          )
                        : null,
                    filled: true,
                    fillColor: const Color(0xFFF1F5F9),
                    contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                      borderSide: BorderSide.none,
                    ),
                  ),
                ),
                if (appState.categories.isNotEmpty) ...[
                  const SizedBox(height: 10),
                  SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    child: Row(
                      children: [
                        FilterChip(
                          label: const Text('Barchasi'),
                          selected: _selectedCategoryId == null,
                          selectedColor: const Color(0xFFFFB300),
                          onSelected: (_) => setState(() => _selectedCategoryId = null),
                        ),
                        const SizedBox(width: 6),
                        ...appState.categories.map((c) {
                          final isSel = _selectedCategoryId == c.id;
                          return Padding(
                            padding: const EdgeInsets.only(right: 6),
                            child: FilterChip(
                              label: Text(c.name),
                              selected: isSel,
                              selectedColor: const Color(0xFFFFB300),
                              onSelected: (_) => setState(() => _selectedCategoryId = isSel ? null : c.id),
                            ),
                          );
                        }),
                      ],
                    ),
                  ),
                ],
              ],
            ),
          ),
          const Divider(height: 1),

          // Products List
          Expanded(
            child: filtered.isEmpty
                ? Center(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Icon(Icons.search_off_rounded, size: 56, color: Colors.grey.shade400),
                        const SizedBox(height: 10),
                        Text(
                          _searchQuery.isNotEmpty ? 'Mos mahsulot topilmadi' : 'Hozircha mahsulotlar yo\'q',
                          style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w600, color: Colors.grey),
                        ),
                      ],
                    ),
                  )
                : ListView.builder(
                    padding: const EdgeInsets.all(14),
                    itemCount: filtered.length,
                    itemBuilder: (context, i) {
                      final p = filtered[i];
                      final isOutOfStock = p.stock == 0;
                      final isLowStock = p.stock <= 5 && !isOutOfStock;
                      final category = appState.categories.firstWhere(
                        (c) => c.id == p.categoryId,
                        orElse: () => Category(id: 0, name: 'Umumiy', icon: Icons.category),
                      );

                      return Container(
                        margin: const EdgeInsets.only(bottom: 10),
                        decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius: BorderRadius.circular(16),
                          border: Border.all(
                            color: isOutOfStock
                                ? const Color(0xFFFCA5A5)
                                : isLowStock
                                    ? const Color(0xFFFDE68A)
                                    : const Color(0xFFE2E8F0),
                          ),
                          boxShadow: [
                            BoxShadow(
                              color: Colors.black.withValues(alpha: 0.03),
                              blurRadius: 8,
                              offset: const Offset(0, 2),
                            ),
                          ],
                        ),
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: Row(
                            children: [
                              // Food Image Preview
                              Container(
                                width: 56,
                                height: 56,
                                decoration: BoxDecoration(
                                  color: const Color(0xFFF1F5F9),
                                  borderRadius: BorderRadius.circular(12),
                                  border: Border.all(color: const Color(0xFFE2E8F0)),
                                ),
                                child: ClipRRect(
                                  borderRadius: BorderRadius.circular(12),
                                  child: p.imageUrl != null && p.imageUrl!.isNotEmpty
                                      ? Image.network(
                                          p.imageUrl!,
                                          fit: BoxFit.cover,
                                          errorBuilder: (_, __, ___) => Icon(p.icon, color: const Color(0xFFFFB300), size: 28),
                                        )
                                      : Center(
                                          child: Icon(p.icon, color: const Color(0xFFFFB300), size: 28),
                                        ),
                                ),
                              ),
                              const SizedBox(width: 14),

                              // Info
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Row(
                                      children: [
                                        Expanded(
                                          child: Text(
                                            p.name,
                                            style: const TextStyle(fontSize: 15.5, fontWeight: FontWeight.w700, color: Color(0xFF0F172A)),
                                            maxLines: 1,
                                            overflow: TextOverflow.ellipsis,
                                          ),
                                        ),
                                        const SizedBox(width: 6),
                                        Text(
                                          formatSum(p.price),
                                          style: const TextStyle(fontSize: 14, fontWeight: FontWeight.bold, color: Color(0xFF10B981)),
                                        ),
                                      ],
                                    ),
                                    const SizedBox(height: 4),
                                    Row(
                                      children: [
                                        Container(
                                          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                                          decoration: BoxDecoration(
                                            color: const Color(0xFFF1F5F9),
                                            borderRadius: BorderRadius.circular(6),
                                          ),
                                          child: Text(
                                            category.name,
                                            style: const TextStyle(fontSize: 11, color: Color(0xFF64748B), fontWeight: FontWeight.w500),
                                          ),
                                        ),
                                        const SizedBox(width: 8),
                                        Container(
                                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                                          decoration: BoxDecoration(
                                            color: isOutOfStock
                                                ? const Color(0xFFFEE2E2)
                                                : isLowStock
                                                    ? const Color(0xFFFEF3C7)
                                                    : const Color(0xFFDCFCE7),
                                            borderRadius: BorderRadius.circular(8),
                                          ),
                                          child: Text(
                                            isOutOfStock
                                                ? 'Tugadi: 0 ta'
                                                : isLowStock
                                                    ? 'Kam qoldi: ${p.stock} ta'
                                                    : 'Mavjud: ${p.stock} ta',
                                            style: TextStyle(
                                              fontSize: 11.5,
                                              fontWeight: FontWeight.bold,
                                              color: isOutOfStock
                                                  ? const Color(0xFFDC2626)
                                                  : isLowStock
                                                      ? const Color(0xFFD97706)
                                                      : const Color(0xFF16A34A),
                                            ),
                                          ),
                                        ),
                                      ],
                                    ),
                                  ],
                                ),
                              ),

                              const SizedBox(width: 12),

                              // Quick Stock Adjusters
                              Row(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  IconButton(
                                    style: IconButton.styleFrom(
                                      backgroundColor: const Color(0xFFF1F5F9),
                                      padding: const EdgeInsets.all(6),
                                      minimumSize: const Size(32, 32),
                                    ),
                                    icon: const Icon(Icons.remove_rounded, size: 16, color: Color(0xFF0F172A)),
                                    tooltip: '-1 kamaytirish',
                                    onPressed: p.stock > 0 ? () => _adjust(p, -1) : null,
                                  ),
                                  const SizedBox(width: 4),
                                  InkWell(
                                    onTap: () => _adjust(p),
                                    borderRadius: BorderRadius.circular(8),
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                                      decoration: BoxDecoration(
                                        color: const Color(0xFFF8FAFC),
                                        borderRadius: BorderRadius.circular(8),
                                        border: Border.all(color: const Color(0xFFCBD5E1)),
                                      ),
                                      child: Text(
                                        '${p.stock}',
                                        style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 14),
                                      ),
                                    ),
                                  ),
                                  const SizedBox(width: 4),
                                  IconButton(
                                    style: IconButton.styleFrom(
                                      backgroundColor: const Color(0xFFF1F5F9),
                                      padding: const EdgeInsets.all(6),
                                      minimumSize: const Size(32, 32),
                                    ),
                                    icon: const Icon(Icons.add_rounded, size: 16, color: Color(0xFF0F172A)),
                                    tooltip: '+1 qo\'shish',
                                    onPressed: () => _adjust(p, 1),
                                  ),
                                  const SizedBox(width: 6),
                                  IconButton(
                                    icon: const Icon(Icons.edit_note_rounded, color: Color(0xFF3B82F6), size: 22),
                                    tooltip: 'Miqdorni kiritish',
                                    onPressed: () => _adjust(p),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }

  Widget _buildStatCard(String label, String value, IconData icon, Color color) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        decoration: BoxDecoration(
          color: color.withValues(alpha: 0.08),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: color.withValues(alpha: 0.2)),
        ),
        child: Row(
          children: [
            Icon(icon, color: color, size: 20),
            const SizedBox(width: 6),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(label, style: TextStyle(fontSize: 10.5, color: Colors.grey.shade700, fontWeight: FontWeight.w500), maxLines: 1),
                  Text(value, style: TextStyle(fontSize: 13, fontWeight: FontWeight.w800, color: color), maxLines: 1),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ============================================================
// PRODUCTS SCREEN (Admin CRUD)
// ============================================================

class ProductsScreen extends StatefulWidget {
  const ProductsScreen({super.key});
  @override
  State<ProductsScreen> createState() => _ProductsScreenState();
}

class _ProductsScreenState extends State<ProductsScreen> {
  void _onAppStateChanged() {
    if (mounted) setState(() {});
  }

  @override
  void initState() {
    super.initState();
    appState.addListener(_onAppStateChanged);
  }

  final Set<int> _selectedIds = {};
  final TextEditingController _searchCtrl = TextEditingController();
  String _searchQuery = '';
  int? _selectedCategoryId;
  bool _loadingSeed = false;

  @override
  void dispose() {
    appState.removeListener(_onAppStateChanged);
    _searchCtrl.dispose();
    super.dispose();
  }

  Future<void> _loadReadyMenu() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
        title: const Row(
          children: [
            Icon(Icons.restaurant_menu_rounded, color: Color(0xFFE25C1D)),
            SizedBox(width: 10),
            Text('Tayyor menyuni yuklash', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 17)),
          ],
        ),
        content: const Text(
          'O‘zbekiston kafelari uchun to‘liq tayyor menyu (Shashlik, Milliy taomlar, Fast food, Salatlar, Garnirlar, Shirinliklar, Issiq va Sovuq ichimliklar) qo‘shiladi.\n\nMavjud mahsulotlaringiz o‘chmaydi va dublikat qilinmaydi.',
          style: TextStyle(fontSize: 13.5, height: 1.4),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('Bekor qilish'),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFFE25C1D),
              foregroundColor: Colors.white,
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
            ),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Yuklash', style: TextStyle(fontWeight: FontWeight.bold)),
          ),
        ],
      ),
    );
    if (ok != true) return;

    setState(() => _loadingSeed = true);
    try {
      final success = await appState.restoreDefaultMenu();
      if (mounted) {
        if (success) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Tayyor menyu muvaffaqiyatli yuklandi!'),
              backgroundColor: Color(0xFF10B981),
              duration: Duration(seconds: 2),
            ),
          );
        } else {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Menyuni yuklashda xatolik yuz berdi'),
              backgroundColor: Colors.red,
            ),
          );
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Xatolik: $e'),
            backgroundColor: Colors.red,
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _loadingSeed = false);
    }
  }

  void _edit([Product? product]) {
    showDialog(
      context: context,
      builder: (_) => _ProductEditDialog(product: product),
    ).then((_) => setState(() {}));
  }

  void _delete(Product p) {
    showDialog(
      context: context,
      builder: (dlgContext) => AlertDialog(
        title: const Text('Mahsulotni o\'chirish'),
        content: Text(
          '"${p.name}" ni rostdan ham o\'chirmoqchimisiz? Bu amalni qaytarib bo\'lmaydi.',
          style: const TextStyle(fontSize: 14),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dlgContext),
            child: const Text('Bekor qilish'),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () async {
              Navigator.pop(dlgContext);
              try {
                await appState.deleteProduct(p);
                if (mounted) {
                  setState(() {
                    _selectedIds.remove(p.id);
                  });
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text('"${p.name}" muvaffaqiyatli o\'chirildi!'),
                      backgroundColor: const Color(0xFF10B981),
                      duration: const Duration(seconds: 2),
                    ),
                  );
                }
              } catch (e) {
                if (mounted) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text('O\'chirishda xatolik: $e'),
                      backgroundColor: Colors.red,
                      duration: const Duration(seconds: 3),
                    ),
                  );
                }
              }
            },
            child: const Text(
              'O\'chirish',
              style: TextStyle(color: Colors.white),
            ),
          ),
        ],
      ),
    );
  }

  void _deleteSelected() {
    if (_selectedIds.isEmpty) return;
    final count = _selectedIds.length;
    showDialog(
      context: context,
      builder: (dlgContext) => AlertDialog(
        title: const Text('Tanlangan mahsulotlarni o\'chirish'),
        content: Text(
          'Rostdan ham $count ta tanlangan mahsulotni o\'chirmoqchimisiz? Bu amalni qaytarib bo\'lmaydi.',
          style: const TextStyle(fontSize: 14),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dlgContext),
            child: const Text('Bekor qilish'),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () async {
              Navigator.pop(dlgContext);
              final idsToDelete = _selectedIds.toList();
              try {
                await appState.deleteProductsBulk(idsToDelete);
                if (mounted) {
                  setState(() {
                    _selectedIds.clear();
                  });
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text('$count ta mahsulot muvaffaqiyatli o\'chirildi!'),
                      backgroundColor: const Color(0xFF10B981),
                      duration: const Duration(seconds: 2),
                    ),
                  );
                }
              } catch (e) {
                if (mounted) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text('O\'chirishda xatolik: $e'),
                      backgroundColor: Colors.red,
                      duration: const Duration(seconds: 3),
                    ),
                  );
                }
              }
            },
            child: const Text(
              'O\'chirish',
              style: TextStyle(color: Colors.white),
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final isSelectionMode = _selectedIds.isNotEmpty;
    final isDark = Theme.of(context).brightness == Brightness.dark;

    final displayedProducts = appState.products.where((p) {
      if (_selectedCategoryId != null && p.categoryId != _selectedCategoryId) {
        return false;
      }
      if (_searchQuery.trim().isNotEmpty) {
        final q = _searchQuery.trim().toLowerCase();
        return p.name.toLowerCase().contains(q);
      }
      return true;
    }).toList();

    return Scaffold(
      appBar: AppBar(
        title: Text(isSelectionMode
            ? '${_selectedIds.length} ta tanlandi'
            : 'Mahsulotlar (${displayedProducts.length})'),
        actions: [
          if (isSelectionMode) ...[
            IconButton(
              icon: const Icon(Icons.select_all),
              tooltip: 'Barchasini tanlash',
              onPressed: () {
                setState(() {
                  if (_selectedIds.length == displayedProducts.length) {
                    _selectedIds.clear();
                  } else {
                    _selectedIds.addAll(displayedProducts.map((e) => e.id));
                  }
                });
              },
            ),
            IconButton(
              icon: const Icon(Icons.delete_sweep, color: Colors.redAccent),
              tooltip: 'Tanlanganlarni o\'chirish',
              onPressed: _deleteSelected,
            ),
          ] else ...[
            if (_loadingSeed)
              const Center(
                child: Padding(
                  padding: EdgeInsets.symmetric(horizontal: 16),
                  child: SizedBox(
                    width: 20,
                    height: 20,
                    child: CircularProgressIndicator(strokeWidth: 2.2, color: Color(0xFFE25C1D)),
                  ),
                ),
              )
            else
              TextButton.icon(
                style: TextButton.styleFrom(
                  foregroundColor: const Color(0xFFE25C1D),
                  backgroundColor: const Color(0xFFE25C1D).withValues(alpha: 0.1),
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
                ),
                onPressed: _loadReadyMenu,
                icon: const Icon(Icons.restaurant_menu_rounded, size: 18),
                label: const Text('Tayyor menyuni yuklash', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
              ),
            const SizedBox(width: 8),
          ],
        ],
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () => _edit(),
        backgroundColor: const Color(0xFFE25C1D),
        child: const Icon(Icons.add, color: Colors.white),
      ),
      body: Column(
        children: [
          // ── Search Bar ──────────────────────────────────────────────
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
            child: TextField(
              controller: _searchCtrl,
              onChanged: (val) => setState(() => _searchQuery = val),
              decoration: InputDecoration(
                hintText: 'Taom yoki ichimlik qidirish (nomi bo\'yicha)...',
                prefixIcon: const Icon(Icons.search, size: 20),
                suffixIcon: _searchQuery.isNotEmpty
                    ? IconButton(
                        icon: const Icon(Icons.clear, size: 18),
                        onPressed: () {
                          _searchCtrl.clear();
                          setState(() => _searchQuery = '');
                        },
                      )
                    : null,
                contentPadding: const EdgeInsets.symmetric(vertical: 10, horizontal: 14),
                filled: true,
                fillColor: isDark ? const Color(0xFF1E293B) : const Color(0xFFF1F5F9),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide.none,
                ),
              ),
            ),
          ),

          // ── Category Filter Chips ───────────────────────────────────
          if (appState.categories.isNotEmpty)
            SizedBox(
              height: 44,
              child: ListView(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.symmetric(horizontal: 16),
                children: [
                  Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: FilterChip(
                      selected: _selectedCategoryId == null,
                      label: Text('Barchasi (${appState.products.length})'),
                      selectedColor: const Color(0xFFE25C1D),
                      checkmarkColor: Colors.white,
                      labelStyle: TextStyle(
                        color: _selectedCategoryId == null ? Colors.white : (isDark ? Colors.white70 : Colors.black87),
                        fontWeight: _selectedCategoryId == null ? FontWeight.bold : FontWeight.w500,
                        fontSize: 12,
                      ),
                      onSelected: (_) => setState(() => _selectedCategoryId = null),
                    ),
                  ),
                  ...appState.categories.map((cat) {
                    final isSel = _selectedCategoryId == cat.id;
                    final count = appState.products.where((p) => p.categoryId == cat.id).length;
                    return Padding(
                      padding: const EdgeInsets.only(right: 8),
                      child: FilterChip(
                        selected: isSel,
                        label: Text('${cat.name} ($count)'),
                        selectedColor: const Color(0xFFE25C1D),
                        checkmarkColor: Colors.white,
                        labelStyle: TextStyle(
                          color: isSel ? Colors.white : (isDark ? Colors.white70 : Colors.black87),
                          fontWeight: isSel ? FontWeight.bold : FontWeight.w500,
                          fontSize: 12,
                        ),
                        onSelected: (_) => setState(() => _selectedCategoryId = isSel ? null : cat.id),
                      ),
                    );
                  }),
                ],
              ),
            ),
          const SizedBox(height: 6),

          // ── Product List ───────────────────────────────────────────
          Expanded(
            child: displayedProducts.isEmpty
                ? Center(
                    child: Padding(
                      padding: const EdgeInsets.all(24),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            Icons.no_food_outlined,
                            size: 56,
                            color: Colors.grey.shade400,
                          ),
                          const SizedBox(height: 12),
                          Text(
                            _searchQuery.isNotEmpty
                                ? '"$_searchQuery" bo\'yicha mahsulot topilmadi'
                                : 'Hozircha mahsulot yo\'q.',
                            style: TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.bold,
                              color: isDark ? Colors.white70 : Colors.grey.shade700,
                            ),
                          ),
                          const SizedBox(height: 8),
                          if (appState.products.isEmpty)
                            ElevatedButton.icon(
                              style: ElevatedButton.styleFrom(
                                backgroundColor: const Color(0xFFE25C1D),
                                foregroundColor: Colors.white,
                                padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 12),
                                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
                              ),
                              onPressed: _loadReadyMenu,
                              icon: const Icon(Icons.restaurant_menu_rounded),
                              label: const Text('Tayyor menyuni yuklash', style: TextStyle(fontWeight: FontWeight.bold)),
                            ),
                        ],
                      ),
                    ),
                  )
                : ListView.builder(
                    padding: const EdgeInsets.all(12),
                    itemCount: displayedProducts.length,
                    itemBuilder: (context, i) {
                      final p = displayedProducts[i];
                      final isSelected = _selectedIds.contains(p.id);
                      final catName = appState.categories
                          .firstWhere(
                            (c) => c.id == p.categoryId,
                            orElse: () => appState.categories.isNotEmpty ? appState.categories.first : Category(id: 0, name: 'Boshqa', icon: Icons.fastfood),
                          )
                          .name;
                      return Card(
                        color: isSelected ? Colors.amber.withValues(alpha: 0.15) : null,
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(12),
                          side: isSelected
                              ? const BorderSide(color: Color(0xFFFFC107), width: 1.5)
                              : BorderSide.none,
                        ),
                        child: ListTile(
                          leading: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Checkbox(
                                value: isSelected,
                                activeColor: const Color(0xFFFFC107),
                                checkColor: Colors.black,
                                onChanged: (val) {
                                  setState(() {
                                    if (val == true) {
                                      _selectedIds.add(p.id);
                                    } else {
                                      _selectedIds.remove(p.id);
                                    }
                                  });
                                },
                              ),
                              SizedBox(
                                width: 42,
                                height: 42,
                                child: _ProductThumb(product: p, iconSize: 22),
                              ),
                            ],
                          ),
                          title: Text(p.name, style: const TextStyle(fontWeight: FontWeight.bold)),
                          subtitle: Text(
                            '$catName · ${formatSum(p.price)} · Zaxira ${p.stock}',
                          ),
                          trailing: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              IconButton(
                                icon: const Icon(Icons.edit, color: Colors.blueAccent),
                                onPressed: () => _edit(p),
                              ),
                              IconButton(
                                icon: const Icon(
                                  Icons.delete_outline,
                                  color: Colors.red,
                                ),
                                onPressed: () => _delete(p),
                              ),
                            ],
                          ),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }
}

