  Widget _buildWaiterSalesCard(AppUser user) {
    final now = DateTime.now();
    final todayReceipts = appState.receipts.where((r) {
      final isMe = r.cashierName.trim().toLowerCase() == user.name.trim().toLowerCase();
      return isMe && r.date.year == now.year && r.date.month == now.month && r.date.day == now.day;
    }).toList();

    final weekAgo = now.subtract(const Duration(days: 7));
    final weekReceipts = appState.receipts.where((r) {
      final isMe = r.cashierName.trim().toLowerCase() == user.name.trim().toLowerCase();
      return isMe && r.date.isAfter(weekAgo);
    }).toList();

    final monthAgo = now.subtract(const Duration(days: 30));
    final monthReceipts = appState.receipts.where((r) {
      final isMe = r.cashierName.trim().toLowerCase() == user.name.trim().toLowerCase();
      return isMe && r.date.isAfter(monthAgo);
    }).toList();

    final todayRev = todayReceipts.fold<double>(0, (sum, r) => sum + r.total);
    final weekRev = weekReceipts.fold<double>(0, (sum, r) => sum + r.total);
    final monthRev = monthReceipts.fold<double>(0, (sum, r) => sum + r.total);

    final todayOrders = todayReceipts.length;
    final weekOrders = weekReceipts.length;
    final monthOrders = monthReceipts.length;

    final avgCheck = todayOrders > 0 ? (todayRev / todayOrders).round() : 0;

    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(20),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.05),
            blurRadius: 16,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 38,
                height: 38,
                decoration: BoxDecoration(
                  color: const Color(0xFF10B981).withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: const Icon(Icons.trending_up_rounded, color: Color(0xFF10B981), size: 20),
              ),
              const SizedBox(width: 12),
              const Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Mening Savdo Natijalarim',
                      style: TextStyle(
                        fontSize: 16,
                        fontWeight: FontWeight.w800,
                        color: Color(0xFF0F1E30),
                      ),
                    ),
                    Text(
                      'Sizning shaxsiy savdo ko\'rsatkichlaringiz',
                      style: TextStyle(fontSize: 12, color: Color(0xFF64748B)),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 18),
          Row(
            children: [
              Expanded(
                child: _buildMetricTile(
                  label: 'Bugun',
                  value: '${formatSum(todayRev)} so\'m',
                  sub: '$todayOrders ta buyurtma',
                  color: const Color(0xFF315EFB),
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: _buildMetricTile(
                  label: 'O\'rtacha chek',
                  value: '${formatSum(avgCheck)} so\'m',
                  sub: 'Bugungi o\'rtacha',
                  color: const Color(0xFF10B981),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          Row(
            children: [
              Expanded(
                child: _buildMetricTile(
                  label: 'Shu hafta (7 kun)',
                  value: '${formatSum(weekRev)} so\'m',
                  sub: '$weekOrders ta buyurtma',
                  color: const Color(0xFF8B5CF6),
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: _buildMetricTile(
                  label: 'Shu oy (30 kun)',
                  value: '${formatSum(monthRev)} so\'m',
                  sub: '$monthOrders ta buyurtma',
                  color: const Color(0xFFF59E0B),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildMetricTile({
    required String label,
    required String value,
    required String sub,
    required Color color,
  }) {
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.06),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: color.withValues(alpha: 0.18)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            label,
            style: TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: color),
          ),
          const SizedBox(height: 4),
          Text(
            value,
            style: const TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w800,
              color: Color(0xFF0F1E30),
            ),
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
          const SizedBox(height: 2),
          Text(
            sub,
            style: const TextStyle(fontSize: 10.5, color: Color(0xFF64748B)),
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
        ],
      ),
    );
  }

  Widget _section({required IconData icon, required String title, required List<Widget> children}) {
    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(20),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.04),
            blurRadius: 14,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      padding: const EdgeInsets.all(18),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Container(
            padding: const EdgeInsets.all(7),
            decoration: BoxDecoration(
              color: const Color(0xFF0F1E30).withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(10),
            ),
            child: Icon(icon, color: const Color(0xFF0F1E30), size: 18),
          ),
          const SizedBox(width: 10),
          Text(title, style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w800, color: Color(0xFF0F1E30))),
        ]),
        const SizedBox(height: 12),
        const Divider(height: 1, color: Color(0xFFF1F5F9)),
        const SizedBox(height: 10),
        ...children,
      ]),
    );
  }

  Widget _infoRow(String label, String value) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 7),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Flexible(
            child: Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(color: Color(0xFF64748B), fontSize: 13, fontWeight: FontWeight.w500),
            ),
          ),
          const SizedBox(width: 8),
          Flexible(
            child: Text(
              value,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              textAlign: TextAlign.end,
              style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 13.5, color: Color(0xFF0F1E30)),
            ),
          ),
        ],
      ),
    );
  }

  Widget _actionRow({
    required IconData icon,
    required Color iconColor,
    required String title,
    required String subtitle,
    required VoidCallback onTap,
  }) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(12),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 4),
        child: Row(
          children: [
            Container(
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                color: iconColor.withValues(alpha: 0.1),
                borderRadius: BorderRadius.circular(10),
              ),
              child: Icon(icon, color: iconColor, size: 20),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(title, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: Color(0xFF0F1E30))),
                  const SizedBox(height: 2),
                  Text(subtitle, style: const TextStyle(fontSize: 11.5, color: Color(0xFF64748B))),
                ],
              ),
            ),
            const Icon(Icons.chevron_right_rounded, color: Color(0xFF94A3B8), size: 20),
          ],
        ),
      ),
    );
  }

  Widget _pwField(String label, TextEditingController ctrl, bool obscure, VoidCallback toggle) {
    return TextField(
      controller: ctrl,
      obscureText: obscure,
      decoration: InputDecoration(
        labelText: label,
        prefixIcon: const Icon(Icons.lock_outline_rounded, size: 20),
        suffixIcon: IconButton(
          icon: Icon(obscure ? Icons.visibility_off_rounded : Icons.visibility_rounded, size: 20),
          onPressed: toggle,
        ),
        border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
        contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 14),
      ),
    );
  }

  String _roleName(UserRole? role) {
    switch (role) {
      case UserRole.admin:
        return 'Administrator';
      case UserRole.director:
        return 'Direktor';
      case UserRole.waiter:
        return 'Ofitsiant';
      case UserRole.cashier:
        return 'Kassir';
      case UserRole.courier:
        return 'Kuryer';
      case UserRole.customer:
        return 'Mijoz';
      default:
        return 'Foydalanuvchi';
    }
  }
}

class SettingsScreen extends StatefulWidget {

  const SettingsScreen({super.key});
  @override
  State<SettingsScreen> createState() => _SettingsScreenState();
}

class _SettingsScreenState extends State<SettingsScreen> {
  late TextEditingController nameCtrl;
  late TextEditingController addressCtrl;
  late TextEditingController phoneCtrl;
  late TextEditingController footerCtrl;
  late TextEditingController printerIpCtrl;
  late TextEditingController printerPortCtrl;
  int printerCharsPerLine = 48;
  PrinterFontSize printerFontSize = PrinterFontSize.normal;
  bool receiptBoldHeader = true;
  ReceiptHeaderAlign receiptHeaderAlign = ReceiptHeaderAlign.center;
  bool testingPrinter = false;
  bool testingTelegram = false;
  bool savingPrinter = false;
  Hall? _selectedHallForTables;

  // Ko'p ulanishli printer sozlamalari (Wi-Fi, USB, Bluetooth)
  String printerConnectionType = 'wifi';
  String? selectedUsbPrinter;
  String? selectedBtPrinter;
  List<DiscoveredPrinter> discoveredUsbPrinters = [];
  List<DiscoveredPrinter> discoveredBtPrinters = [];
  bool scanningPrinters = false;
  bool autoPrintOnPaid = true;
  String? cashierStatusMessage;
  bool cashierStatusOk = false;

  // Oshxona printeri (alohida oshpaz cheki uchun)
  bool kitchenPrinterEnabled = false;
  String kitchenPrinterConnectionType = 'wifi';
  late TextEditingController kitchenPrinterIpCtrl;
  late TextEditingController kitchenPrinterPortCtrl;
  String? selectedKitchenUsbPrinter;
  String? selectedKitchenBtPrinter;
  bool testingKitchenPrinter = false;
  String? kitchenStatusMessage;
  bool kitchenStatusOk = false;
  bool printingTestReceipt = false;
  late TextEditingController telegramChatIdCtrl;
  bool telegramReceiptsEnabled = false;
  String paperFormat = '80mm';
  bool isAgentRunning = false;

  @override
  void initState() {
    super.initState();
    if (appState.currentUser?.role == UserRole.waiter) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          Navigator.of(context).pop();
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text("Ofitsiant uchun sozlamalar bo'limi yopiq"),
              backgroundColor: Color(0xFFEF4444),
            ),
          );
        }
      });
    }
    if (appState.halls.isNotEmpty) {
      _selectedHallForTables = appState.halls.first;
    }
    nameCtrl = TextEditingController(text: appState.restaurantName);
    addressCtrl = TextEditingController(text: appState.restaurantAddress);
    phoneCtrl = TextEditingController(text: appState.restaurantPhone);
    footerCtrl = TextEditingController(text: appState.receiptFooterNote);
    printerIpCtrl = TextEditingController(text: appState.printerIp);
    printerPortCtrl = TextEditingController(
      text: appState.printerPort.toString(),
    );
    printerCharsPerLine = appState.printerCharsPerLine;
    printerFontSize = appState.printerFontSize;
    receiptBoldHeader = appState.receiptBoldHeader;
    receiptHeaderAlign = appState.receiptHeaderAlign;

    printerConnectionType = appState.printerConnectionType;
    selectedUsbPrinter = appState.printerUsbName;
    selectedBtPrinter = appState.printerBtName;
    autoPrintOnPaid = appState.autoPrintOnPaid;
    cashierStatusOk = appState.isPrinterVerified;
    if (appState.isPrinterVerified) {
      cashierStatusMessage = 'Ulangan ${appState.printerVerifiedInfo != null ? "(${appState.printerVerifiedInfo})" : ""}';
    }

    kitchenPrinterEnabled = appState.kitchenPrinterEnabled;
    kitchenPrinterConnectionType = appState.kitchenPrinterConnectionType;
    kitchenPrinterIpCtrl = TextEditingController(text: appState.kitchenPrinterIp);
    kitchenPrinterPortCtrl = TextEditingController(text: appState.kitchenPrinterPort.toString());
    selectedKitchenUsbPrinter = appState.kitchenPrinterUsbName;
    selectedKitchenBtPrinter = appState.kitchenPrinterBtName;
    kitchenStatusOk = appState.isKitchenPrinterVerified;
    if (appState.isKitchenPrinterVerified) {
      kitchenStatusMessage = 'Ulangan ${appState.kitchenPrinterVerifiedInfo != null ? "(${appState.kitchenPrinterVerifiedInfo})" : ""}';
    }

    paperFormat = appState.paperFormat;
    telegramReceiptsEnabled = appState.telegramReceiptsEnabled;
    telegramChatIdCtrl = TextEditingController(text: appState.telegramReceiptsChatId);
    PrintAgentService().isAgentRunning().then((val) {
      if (mounted) setState(() => isAgentRunning = val);
    });
  }

  @override
  void dispose() {
    nameCtrl.dispose();
    addressCtrl.dispose();
    phoneCtrl.dispose();
    footerCtrl.dispose();
    printerIpCtrl.dispose();
    printerPortCtrl.dispose();
    kitchenPrinterIpCtrl.dispose();
    kitchenPrinterPortCtrl.dispose();
    telegramChatIdCtrl.dispose();
    super.dispose();
  }

  void _save() {
    appState.updateSettings(
      name: nameCtrl.text.trim(),
      address: addressCtrl.text.trim(),
      phone: phoneCtrl.text.trim(),
      footerNote: footerCtrl.text.trim(),
    );
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Sozlamalar saqlandi'),
        duration: Duration(milliseconds: 900),
      ),
    );
  }

  Future<void> _editReceiptName() async {
    await showEditReceiptNameDialog(context);
    if (!mounted) return;
    setState(() {});
  }

  // ---- "CHEKNI TAHRIRLASH" — endi umumiy (top-level) funksiya orqali
  // ochiladi (showEditReceiptTemplateDialog), shu bilan bir xil oyna
  // "Sozlamalar" ekranidan ham, "Printer sozlamalari" tezkor panelidan
  // ham chaqiriladi. Bu yerdan chaqirilgach, matn maydonlarini ekranda
  // ham yangilab qo'yamiz. ----
  Future<void> _editReceiptTemplate() async {
    await showEditReceiptTemplateDialog(context);
    if (!mounted) return;
    setState(() {
      nameCtrl.text = appState.restaurantName;
      addressCtrl.text = appState.restaurantAddress;
      phoneCtrl.text = appState.restaurantPhone;
      footerCtrl.text = appState.receiptFooterNote;
    });
  }

  Future<void> _editProfileDialog() async {
    final user = appState.currentUser;
    if (user == null) return;

    final nameController = TextEditingController(text: user.name);
    final surnameController = TextEditingController(text: user.surname);
    final usernameController = TextEditingController(text: user.username);
    final phoneController = TextEditingController(text: user.phone);
    bool saving = false;
    String? errorMsg;

    await showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (dlgCtx, setDState) => AlertDialog(
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
          title: Row(
            children: [
              Icon(Icons.person, color: kDarkYellow),
              const SizedBox(width: 10),
              const Text('Profilni tahrirlash', style: TextStyle(fontSize: 18)),
            ],
          ),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: nameController,
                  decoration: const InputDecoration(labelText: 'Ism *'),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: surnameController,
                  decoration: const InputDecoration(labelText: 'Familiya'),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: usernameController,
                  decoration: const InputDecoration(
                    labelText: 'Login / Username *',
                    hintText: 'Login kiriting',
                  ),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: phoneController,
                  keyboardType: TextInputType.phone,
                  decoration:
                      const InputDecoration(labelText: 'Telefon raqami'),
                ),
                if (errorMsg != null)
                  Padding(
                    padding: const EdgeInsets.only(top: 10),
                    child: Text(errorMsg!,
                        style:
                            const TextStyle(color: Colors.red, fontSize: 13)),
                  ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: saving ? null : () => Navigator.pop(ctx),
              child: const Text('Bekor qilish'),
            ),
            ElevatedButton(
              onPressed: saving
                  ? null
                  : () async {
                      final n = nameController.text.trim();
                      final u = usernameController.text.trim();
                      if (n.isEmpty || u.isEmpty) {
                        setDState(() =>
                            errorMsg = 'Ism va Login to\'ldirilishi shart');
                        return;
                      }
                      setDState(() => saving = true);
                      try {
                        await AuthService().updateUserProfile(
                          uid: user.uid,
                          name: n,
                          surname: surnameController.text.trim(),
                          username: u,
                          phone: phoneController.text.trim(),
                        );
                        user.name = n;
                        user.surname = surnameController.text.trim();
                        user.username = u;
                        user.phone = phoneController.text.trim();
                        if (ctx.mounted) Navigator.pop(ctx);
                        if (mounted) {
                          setState(() {});
                          ScaffoldMessenger.of(context).showSnackBar(
                            const SnackBar(
                                content:
                                    Text('Profil muvaffaqiyatli saqlandi!')),
                          );
                        }
                      } catch (e) {
                        setDState(() {
                          saving = false;
                          errorMsg = 'Xatolik: $e';
                        });
                      }
                    },
              child: saving
                  ? const SizedBox(
                      width: 18,
                      height: 18,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white),
                    )
                  : const Text('Saqlash'),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _changePasswordDialog() async {
    final passController = TextEditingController();
    final confirmPassController = TextEditingController();
    bool obscure1 = true;
    bool obscure2 = true;
    bool saving = false;
    String? errorMsg;

    await showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (dlgCtx, setDState) => AlertDialog(
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
          title: Row(
            children: [
              Icon(Icons.lock_reset, color: kDarkYellow),
              const SizedBox(width: 10),
              const Text('Parolni o\'zgartirish',
                  style: TextStyle(fontSize: 18)),
            ],
          ),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: passController,
                  obscureText: obscure1,
                  decoration: InputDecoration(
                    labelText: 'Yangi parol (kamida 6 ta belgi) *',
                    suffixIcon: IconButton(
                      icon: Icon(
                          obscure1 ? Icons.visibility_off : Icons.visibility),
                      onPressed: () => setDState(() => obscure1 = !obscure1),
                    ),
                  ),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: confirmPassController,
                  obscureText: obscure2,
                  decoration: InputDecoration(
                    labelText: 'Yangi parolni tasdiqlang *',
                    suffixIcon: IconButton(
                      icon: Icon(
                          obscure2 ? Icons.visibility_off : Icons.visibility),
                      onPressed: () => setDState(() => obscure2 = !obscure2),
                    ),
                  ),
                ),
                if (errorMsg != null)
                  Padding(
                    padding: const EdgeInsets.only(top: 10),
                    child: Text(errorMsg!,
                        style:
                            const TextStyle(color: Colors.red, fontSize: 13)),
                  ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: saving ? null : () => Navigator.pop(ctx),
              child: const Text('Bekor qilish'),
            ),
            ElevatedButton(
              onPressed: saving
                  ? null
                  : () async {
                      final p = passController.text.trim();
                      final cp = confirmPassController.text.trim();
                      if (p.length < 6) {
                        setDState(() => errorMsg =
                            'Parol kamida 6 ta belgidan iborat bo\'lishi shart');
                        return;
                      }
                      if (p != cp) {
                        setDState(
                            () => errorMsg = 'Tasdiqlash paroli mos kelmadi');
                        return;
                      }
                      setDState(() => saving = true);
                      try {
                        await AuthService().changePassword(p);
                        if (ctx.mounted) Navigator.pop(ctx);
                        if (mounted) {
                          ScaffoldMessenger.of(context).showSnackBar(
                            const SnackBar(
                              content: Text('Parol muvaffaqiyatli yangilandi!'),
                              backgroundColor: Colors.green,
                            ),
                          );
                        }
                      } catch (e) {
                        setDState(() {
                          saving = false;
                          errorMsg = 'Xatolik: $e';
                        });
                      }
                    },
              child: saving
                  ? const SizedBox(
                      width: 18,
                      height: 18,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white),
                    )
                  : const Text('Yangilash'),
            ),
          ],
        ),
      ),
    );
  }

  // ---- TARMOQ (Wi-Fi/LAN) PRINTERGA ULANISH ----
  // Printer bilan ulanish uning IP-manzili va porti (odatda 9100) orqali
  // amalga oshiriladi. "Saqlash" tugmasi shu ma'lumotlarni AppState ga
  // (va SharedPreferences orqali xotiraga) yozadi — shundan so'ng barcha
  // cheklar (mijoz cheki, hisob, oshpaz cheki) avtomatik shu printerga
  // IP orqali chiqadi.
  int? get _parsedPort => int.tryParse(printerPortCtrl.text.trim());

  Future<void> _scanPrinters() async {
    setState(() => scanningPrinters = true);
    try {
      final res = await PrintAgentService().discoverPrinters();
      setState(() {
        discoveredUsbPrinters = res['usb'] ?? [];
        discoveredBtPrinters = res['bluetooth'] ?? [];
        if (selectedUsbPrinter == null && discoveredUsbPrinters.isNotEmpty) {
          selectedUsbPrinter = discoveredUsbPrinters.first.id;
        }
        if (selectedBtPrinter == null && discoveredBtPrinters.isNotEmpty) {
          selectedBtPrinter = discoveredBtPrinters.first.id;
        }
        if (selectedKitchenUsbPrinter == null && discoveredUsbPrinters.isNotEmpty) {
          selectedKitchenUsbPrinter = discoveredUsbPrinters.first.id;
        }
        if (selectedKitchenBtPrinter == null && discoveredBtPrinters.isNotEmpty) {
          selectedKitchenBtPrinter = discoveredBtPrinters.first.id;
        }
      });
      if (mounted) {
        final total = discoveredUsbPrinters.length + discoveredBtPrinters.length;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(total > 0
                ? '$total ta qurilma topildi (USB: ${discoveredUsbPrinters.length}, Bluetooth: ${discoveredBtPrinters.length})'
                : 'Ulangan USB/Bluetooth printer topilmadi. Kompyuterda print-agent ishlab turganligini tekshiring.'),
            backgroundColor: total > 0 ? const Color(0xFF10B981) : const Color(0xFFF59E0B),
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Qidirishda xatolik: $e'), backgroundColor: Colors.red),
        );
      }
    } finally {
      if (mounted) setState(() => scanningPrinters = false);
    }
  }

  Future<void> _testPrinterConnection({bool isKitchen = false}) async {
    final type = isKitchen ? kitchenPrinterConnectionType : printerConnectionType;
    final ip = isKitchen ? kitchenPrinterIpCtrl.text.trim() : printerIpCtrl.text.trim();
    final port = isKitchen
        ? (int.tryParse(kitchenPrinterPortCtrl.text.trim()) ?? 9100)
        : (_parsedPort ?? 9100);
    final deviceId = isKitchen
        ? (kitchenPrinterConnectionType == 'usb' ? selectedKitchenUsbPrinter : selectedKitchenBtPrinter)
        : (printerConnectionType == 'usb' ? selectedUsbPrinter : selectedBtPrinter);

    if (type == 'wifi' && ip.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Printer IP-manzilini kiriting')),
      );
      return;
    }

    if (isKitchen) {
      setState(() => testingKitchenPrinter = true);
    } else {
      setState(() => testingPrinter = true);
    }

    try {
      final result = await PrintAgentService().testConnection(
        type: type,
        ip: ip,
        port: port,
        deviceId: deviceId,
      );

      setState(() {
        if (isKitchen) {
          kitchenStatusOk = result.ok;
          kitchenStatusMessage = result.ok
              ? 'Ulangan (${result.latencyMs}ms)'
              : (result.error ?? 'Ulanmadi');
          appState.isKitchenPrinterVerified = result.ok;
          appState.kitchenPrinterVerifiedInfo = result.ok ? '${result.latencyMs}ms' : null;
        } else {
          cashierStatusOk = result.ok;
          cashierStatusMessage = result.ok
              ? 'Ulangan (${result.latencyMs}ms)'
              : (result.error ?? 'Ulanmadi');
          appState.isPrinterVerified = result.ok;
          appState.printerVerifiedInfo = result.ok ? '${result.latencyMs}ms' : null;
          if (result.ok) {
            appState.connectedPrinterName = type == 'wifi'
                ? '$ip:$port'
                : (deviceId ?? type.toUpperCase());
          }
        }
      });

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(result.ok
                ? '${isKitchen ? "Oshxona" : "Kassa"} printeriga ulanish muvaffaqiyatli! (${result.latencyMs}ms)'
                : 'Ulanishda xatolik: ${result.error ?? "Printer javob bermadi"}'),
            backgroundColor: result.ok ? const Color(0xFF10B981) : const Color(0xFFEF4444),
          ),
        );
      }
    } catch (e) {
      setState(() {
        if (isKitchen) {
          kitchenStatusOk = false;
          kitchenStatusMessage = 'Xatolik: $e';
        } else {
          cashierStatusOk = false;
          cashierStatusMessage = 'Xatolik: $e';
        }
      });
    } finally {
      if (mounted) {
        setState(() {
          if (isKitchen) {
            testingKitchenPrinter = false;
          } else {
            testingPrinter = false;
          }
        });
      }
    }
  }

  Future<void> _printTestReceipt({bool isKitchen = false}) async {
    setState(() => printingTestReceipt = true);
    try {
      final type = isKitchen ? kitchenPrinterConnectionType : printerConnectionType;
      final ip = isKitchen ? kitchenPrinterIpCtrl.text.trim() : printerIpCtrl.text.trim();
      final port = isKitchen
          ? (int.tryParse(kitchenPrinterPortCtrl.text.trim()) ?? 9100)
          : (_parsedPort ?? 9100);
      final deviceId = isKitchen
          ? (kitchenPrinterConnectionType == 'usb' ? selectedKitchenUsbPrinter : selectedKitchenBtPrinter)
          : (printerConnectionType == 'usb' ? selectedUsbPrinter : selectedBtPrinter);

      final ok = await PrintAgentService().printJob(
        jobId: 'test_${DateTime.now().millisecondsSinceEpoch}',
        type: 'test',
        printerConfig: {
          'type': type,
          'ip': ip,
          'port': port,
          'deviceId': deviceId,
          'paperWidth': printerCharsPerLine == 32 ? 58 : 80,
        },
      );

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(ok
                ? 'Test cheki printerdan muvaffaqiyatli chop etildi!'
                : 'Test chek chiqarib bo‘lmadi. Printer ulanishini tekshiring.'),
            backgroundColor: ok ? const Color(0xFF10B981) : const Color(0xFFEF4444),
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Xatolik: $e'), backgroundColor: Colors.red),
        );
      }
    } finally {
      if (mounted) setState(() => printingTestReceipt = false);
    }
  }

  Future<void> _testTelegramConnection() async {
    final target = telegramChatIdCtrl.text.trim();
    if (target.isEmpty) {
      showZaveroSnackBar(
        message: "Iltimos, avval Telegram Chat ID yoki telefon raqam kiriting!",
        backgroundColor: const Color(0xFFDC2626),
        prefixIcon: Icons.warning_amber_rounded,
      );
      return;
    }
    setState(() => testingTelegram = true);
    showZaveroSnackBar(
      message: "Telegramga ulanish tekshirilmoqda...",
      backgroundColor: const Color(0xFF0284C7),
      prefixIcon: Icons.send_rounded,
      duration: const Duration(seconds: 2),
    );
    try {
      final res = await ApiClient().post('/cafe/test-telegram', body: {
        'telegramChatId': target,
      });
      if (res['success'] == true) {
        showZaveroSnackBar(
          message: res['message'] ?? "Telegram ulanishi muvaffaqiyatli! Test chek yuborildi.",
          backgroundColor: const Color(0xFF10B981),
          prefixIcon: Icons.check_circle_outline,
          duration: const Duration(seconds: 4),
        );
      } else {
        showZaveroSnackBar(
          message: res['error'] ?? "Telegramga yuborib bo'lmadi.",
          backgroundColor: const Color(0xFFDC2626),
          prefixIcon: Icons.error_outline,
          duration: const Duration(seconds: 5),
        );
      }
    } catch (e) {
      showZaveroSnackBar(
        message: "Xatolik: $e",
        backgroundColor: const Color(0xFFDC2626),
        prefixIcon: Icons.error_outline,
      );
    } finally {
      if (mounted) setState(() => testingTelegram = false);
    }
  }

  Future<void> _savePrinterSettings({bool silent = false}) async {
    setState(() => savingPrinter = true);
    final ip = printerIpCtrl.text.trim();
    final port = _parsedPort ?? 9100;

    appState.printerConnectionType = printerConnectionType;
    appState.printerIp = ip;
    appState.printerPort = port;
    appState.printerUsbName = selectedUsbPrinter;
    appState.printerBtName = selectedBtPrinter;
    appState.printerCharsPerLine = printerCharsPerLine;
    appState.paperWidthMm = printerCharsPerLine == 32 ? 58 : 80;
    appState.setPaperFormat(paperFormat);
    appState.telegramReceiptsEnabled = telegramReceiptsEnabled;
    appState.telegramReceiptsChatId = telegramChatIdCtrl.text.trim();
    appState.printerFontSize = printerFontSize;
    appState.autoPrintOnPaid = autoPrintOnPaid;
    appState.receiptBoldHeader = receiptBoldHeader;
    appState.receiptHeaderAlign = receiptHeaderAlign;

    appState.kitchenPrinterEnabled = kitchenPrinterEnabled;
    appState.kitchenPrinterConnectionType = kitchenPrinterConnectionType;
    appState.kitchenPrinterIp = kitchenPrinterIpCtrl.text.trim();
    appState.kitchenPrinterPort = int.tryParse(kitchenPrinterPortCtrl.text.trim()) ?? 9100;
    appState.kitchenPrinterUsbName = selectedKitchenUsbPrinter;
    appState.kitchenPrinterBtName = selectedKitchenBtPrinter;

    await appState.savePrinterSettingsToCloud();

    if (!silent && mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text("Barcha printer sozlamalari saqlandi va bulutga yuklandi!"),
          backgroundColor: Color(0xFF10B981),
        ),
      );
    }
    if (mounted) setState(() => savingPrinter = false);
  }

